window.SIM_VDE = window.SIM_VDE || {};
window.SIM_VDE['ined3'] = {"slug":"ined3","nome":"Simulado Inédito 3","fonte":"Método VDE","questoes":[{"id":"vde_ined3_01","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":1,"discipline":"Ética Profissional","topic":"Publicidade Profissional","statement":"Sobre o novo provimento da, Nº 205\\2021, que trata sobre a publicidade profissional, é correto afirmar que:","alternative_a":"Os consultores e as sociedades de consultores em direito estrangeiro devidamente autorizadas pela só poderão realizar o marketing jurídico em relação às suas atividades de consultoria em direito estrangeiro correspondente ao país ou Estado de origem do profissional interessado.","alternative_b":"Somente a publicidade passiva será utilizada como estratégia de marketing em conteúdos jurídicos, desde que não esteja incluída a mercantilização, a captação de clientela ou o emprego excessivo de recursos financeiros.","alternative_c":"Em relação à divulgação de imagem, vídeo ou áudio (contendo atuação profissional) em audiências, sustentações orais e em processos judiciais ou administrativos não alcançados por segredo de justiça, serão flexibilizados o sigilo e a dignidade profissional quando justificado.","alternative_d":"A publicidade profissional permite a utilização de anúncios, desde que não sejam pagos, nos meios de comunicação não vedados pelo Código de Ética e Disciplina.","correct_answer":"A","explanation":"A) Correta. Nos termos do art. 3º, §2º, do Provimento 205/2021 os consultores e as sociedades de consultores em direito estrangeiro devidamente autorizadas pela OAB, somente poderão realizar o marketing jurídico com relação às suas atividades de consultoria em direito estrangeiro correspondente ao país ou Estado de origem do profissional interessado. Para isso, nas peças de caráter publicitário, eles deverão acrescentar obrigatoriamente a expressão “Consultores em direito estrangeiro” ao nome ou à razão social que internacionalmente adotem. Art. 3º, § 2º. Provimento 205/2021. Os consultores e as sociedades de consultores em direito estrangeiro devidamente autorizadas pela, nos termos do Provimento n. 91/2000, somente poderão realizar o marketing jurídico com relação às suas atividades de consultoria em direito estrangeiro correspondente ao país ou Estado de origem do profissional interessado. Para esse fim, nas peças de caráter publicitário a sociedade acrescentará obrigatoriamente ao nome ou razão social que internacionalmente adote a expressão “Consultores em direito estrangeiro” (art. 4º do Provimento 91/2000). B) Errada. No marketing de conteúdos jurídicos poderá ser utilizada a publicidade ativa (divulgação capaz de atingir número indeterminado de pessoas) ou passiva (divulgação capaz de atingir somente público certo que tenha buscado informações acerca do anunciante ou dos temas anunciados). Art. 4º. Provimento 205/2021. No marketing de conteúdos jurídicos poderá ser utilizada a publicidade ativa ou passiva, desde que não esteja incutida a mercantilização, a captação de clientela ou o emprego excessivo de recursos financeiros, sendo admitida a utilização de anúncios, pagos ou não, nos meios de comunicação, exceto nos meios vedados pelo art. 40 do Código de Ética e Disciplina e desde que respeitados os limites impostos pelo inciso V do mesmo artigo e pelo Anexo Único deste provimento. C) Errada. Na divulgação de imagem, vídeo ou áudio contendo atuação profissional, inclusive em audiências e sustentações orais, em processos judiciais ou administrativos, devem ser respeitados o sigilo e a dignidade profissional. Art. 4º §2º. Provimento 205/2021. Na divulgação de imagem, vídeo ou áudio contendo atuação profissional, inclusive em audiências e sustentações orais, em processos judiciais ou administrativos, não alcançados por segredo de justiça, serão respeitados o sigilo e a dignidade profissional e vedada a referência ou menção a decisões judiciais e resultados de qualquer natureza obtidos em procedimentos que patrocina ou participa de alguma forma, ressalvada a hipótese de manifestação espontânea em caso coberto pela mídia. D) Errada. A publicidade profissional permite a utilização de anúncios, pagos ou não. Art. 5º. Provimento 205/2021. A publicidade profissional permite a utilização de anúncios, pagos ou não, nos meios de comunicação não vedados pelo art. 40 do Código de Ética e Disciplina.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_02","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":2,"discipline":"Ética Profissional","topic":"Honorários Advocatícios","statement":"Enrolado da Silva é um advogado sabidamente conhecido por seu péssimo desempenho no exercício da advocacia, uma vez que, costumeiramente, perde prazos e comete atos irresponsáveis perante os colegas de profissão e clientes. Recentemente, ele se envolveu em uma confusão com o cliente Coitado, pois não passou os detalhes sobre o recebimento dos valores oriundos de determinado processo, fato que gerou o encerramento do vínculo por parte do cliente ao revogar o mandato. Ocorre que, alguns anos depois, Coitado ficou sabendo que possuía o direito de cobrar a prestação de contas ao advogado, não sabendo se ainda poderia exercer tal direito. Sobre o prazo prescricional para cobrança da prestação de contas no caso em tela, é correto afirmar que, de acordo com o Estatuto da Advocacia e da OAB:","alternative_a":"O prazo prescricional é de 5 anos, começando a contar do momento que o cliente firmou o vínculo com o advogado.","alternative_b":"O prazo prescricional é de 3 anos, começando a contar do momento que o cliente firmou o vínculo com o advogado.","alternative_c":"O prazo prescricional é de 5 anos, começando a contar do momento que o vínculo entre as partes se encerrou.","alternative_d":"O prazo prescricional é de 3 anos, começando a contar do momento que o vínculo entre as partes se encerrou.","correct_answer":"C","explanation":"A) Errada. No caso, conta-se 5 anos a partir da renúncia ou revogação do mandato (encerramento do vínculo). Aplica-se às regras previstas para a cobrança de honorários. B) Errada. O prazo prescricional é de 5 anos e conta-se a partir do encerramento do vínculo entre as partes, que se deu com a revogação do mandato. C) Correta. O Art. 25-A do Estatuto da Advocacia e da OAB menciona que prescreve em cinco anos a ação de prestação de contas pelas quantias recebidas pelo advogado de seu cliente. No caso em tela, o prazo começaria a contar a partir do encerramento do vínculo entre as partes, que é um dos termos iniciais para contagem do prazo prescricional, conforme o Art. 25, V, do mesmo diploma. Art. 25-A. EAOAB. Prescreve em cinco anos a ação de prestação de contas pelas quantias recebidas pelo advogado de seu cliente, ou de terceiros por conta dele (art. 34, XXI). Art. 25. EAOAB. Prescreve em cinco anos a ação de cobrança de honorários de advogado, contado o prazo: V - da renúncia ou revogação do mandato. 2 D) Errada. O prazo prescricional é de 5 anos.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_03","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":3,"discipline":"Ética Profissional","topic":"Honorários Advocatícios","statement":"A atividade da advocacia é marcada pela diversidade de características próprias, uma delas diz respeito à maioria dos advogados não possuir salário fixo como outros profissionais de diversas áreas. Os honorários advocatícios são o meio pelo qual tais profissionais recebem a contraprestação financeira do seu trabalho. O valor percebido é bastante variado, pois depende de muitos fatores, entre eles a atividade, o esforço e o tempo empregado no serviço. Sabendo disso, sobre a fase de execução dos honorários, é correto afirmar que, de acordo com o Estatuto da Advocacia e da OAB:","alternative_a":"Os honorários incluídos na condenação, por arbitramento ou sucumbência, pertencem ao advogado, tendo este o direito autônomo de executar a sentença nesta parte, podendo requerer que o precatório, quando necessário, seja expedido em seu favor.","alternative_b":"A decisão judicial que fixar ou arbitrar honorários, bem como o contrato escrito que os estipular são títulos executivos e constituem crédito sem prioridade na falência, concordata, concurso de credores, insolvência civil e liquidação extrajudicial.","alternative_c":"A execução dos honorários não pode ser promovida nos mesmos autos da ação em que tenha atuado o advogado, sendo necessário que este ajuíze uma ação própria.","alternative_d":"Na hipótese de falecimento do advogado, os honorários de sucumbência não serão devidos.","correct_answer":"A","explanation":"A) Correta. O advogado tem direito autônomo a executar a sentença quanto aos honorários incluídos na condenação por arbitramento ou por sucumbência, podendo requerer que o precatório seja expedido em seu favor. Art. 23. EOAOB. Os honorários incluídos na condenação, por arbitramento ou sucumbência, pertencem ao advogado, tendo este direito autônomo para executar a sentença nesta parte, podendo requerer que o precatório, quando necessário, seja expedido em seu favor. B) Errada. Tais créditos são privilegiados, tendo prioridade na falência, concordata, concurso de credores, insolvência civil e liquidação extrajudicial. Art. 24. EAOAB. A decisão judicial que fixar ou arbitrar honorários e o contrato escrito que os estipular são títulos executivos e constituem crédito privilegiado na falência, concordata, concurso de credores, insolvência civil e liquidação extrajudicial. C) Errada. É possível que a execução seja promovida nos mesmos autos da ação. Art. 24, §1º. EAOAB. A execução dos honorários pode ser promovida nos mesmos autos da ação em que tenha atuado o advogado, se assim lhe convier. D) Errada. Os honorários de sucumbência serão devidos aos sucessores ou representantes legais do advogado que faleceu. Art. 24, §2º. EAOAB. Na hipótese de falecimento ou incapacidade civil do advogado, os honorários de sucumbência, proporcionais ao trabalho realizado, são recebidos por seus sucessores ou representantes legais.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_04","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":4,"discipline":"Ética Profissional","topic":"Infrações e Sanções Disciplinares","statement":"Em razão da prática de delito, determinado advogado teve a sua inscrição excluída pela OAB após o regular procedimento disciplinar administrativo. Anos após à prática da conduta criminosa, o profissional procurou você, especialista no processo disciplinar da Ordem, para saber acerca da possibilidade de retornar ao exercício da profissão, então você o responde dizendo que:","alternative_a":"É permitido, àquele que tenha sofrido qualquer sanção disciplinar requerer, um ano após seu cumprimento, a reabilitação, independente do ato praticado.","alternative_b":"Embora a reabilitação seja possível na maioria dos casos, as situações que ensejam a pena de exclusão não permitem o referido benefício, em razão da gravidade.","alternative_c":"É possível a solicitação de reabilitação após 5 anos do cumprimento da pena, independente de qual tenha sido a conduta.","alternative_d":"A reabilitação é possível em qualquer sanção disciplinar, desde que obedecidos os requisitos básicos. Ocorre que, se a sanção for em razão de crime, é preciso que haja a reabilitação criminal também.","correct_answer":"D","explanation":"A) Errada. Quando a sanção disciplinar resultar da prática de crime, o pedido de reabilitação depende também da correspondente reabilitação criminal. B) Errada. O retorno ao exercício da profissão é permitido ao que tenha sofrido qualquer sanção disciplinar. C) Errada. O requerimento poderá ser feito um ano após o cumprimento da pena. D) Correta. É permitido ao que tenha sofrido qualquer sanção disciplinar requerer, um ano após seu cumprimento, a reabilitação, em face de provas efetivas de bom comportamento. Quando a sanção disciplinar resultar da prática de crime, o pedido de reabilitação dependerá, também, da correspondente reabilitação criminal. Art. 41. EAOAB. É permitido ao que tenha sofrido qualquer sanção disciplinar requerer, um ano após seu cumprimento, a reabilitação, em face de provas efetivas de bom comportamento. Parágrafo único. Quando a sanção disciplinar resultar da prática de crime, o pedido de reabilitação depende também da correspondente reabilitação criminal.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_05","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":5,"discipline":"Ética Profissional","topic":"Publicidade Profissional","statement":"O Comitê Regulador do Marketing Jurídico foi criado pelo Provimento 205\\2021 que trata sobre a publicidade profissional. Sua finalidade essencial é ser um órgão de caráter consultivo vinculado à Diretoria do Conselho Federal da OAB. Sobre sua composição e função, é incorreto afirmar que:","alternative_a":"Entre os membros, estarão 10 Conselheiros Federais, 2 por cada região do país, indicados (as) pela Diretoria do CFOAB.","alternative_b":"As Seccionais poderão conceder poderes coercitivos à respectiva Comissão de Fiscalização, permitindo a expedição de notificações com a finalidade de dar efetividade às disposições do provimento.","alternative_c":"Com a finalidade de pacificar e unificar a interpretação dos temas pertinentes perante os Tribunais de Ética e Disciplina e Comissões de Fiscalização das Seccionais, o Comitê poderá propor ao Órgão Especial sugestões de interpretação dos dispositivos sobre publicidade e informação.","alternative_d":"Entre os membros do Comitê estará um representante do Colégio de Presidentes de Seccionais.","correct_answer":"A","explanation":"A questão pede para assinalar a alternativa incorreta! A) Correta. O Comitê Regulador do Marketing Jurídico, que é um órgão consultivo vinculado à diretoria do Conselho Federal da OAB, composto por 5 Conselheiros Federais, 1 por cada região do país, indicados (as) pela Diretoria do CFOAB. Art. 9º. Provimento 205/2021. Fica criado o Comitê Regulador do Marketing Jurídico, de caráter consultivo, vinculado à Diretoria do Conselho Federal, que nomeará seus membros, com mandato concomitante ao da gestão, e será composto por: I – 05 (cinco) Conselheiros(as) Federais, um (a) de cada região do país, indicados(as) pela Diretoria do CFOAB. B) Errada. A questão pede o item falso e essa assertiva é verdadeira. Vejamos: Art. 10. Provimento 205/2021. As Seccionais poderão conceder poderes coercitivos à respectiva Comissão de Fiscalização, permitindo a expedição de notificações com a finalidade de dar efetividade às disposições deste provimento. C) Errada. A questão pede o item falso e essa assertiva é verdadeira. O Comitê poderá propor ao Conselho Federal a alteração, a supressão ou a inclusão de novos critérios e propostas de alteração do Provimento. 3 Art. 9º §1º, Provimento 205/2021. O Comitê Regulador do Marketing Jurídico se reunirá periodicamente para acompanhar a evolução dos critérios específicos sobre marketing, publicidade e informação na advocacia constantes do Anexo Único deste provimento, podendo propor ao Conselho Federal a alteração, a supressão ou a inclusão de novos critérios e propostas de alteração do provimento. D)Errada. A questão pede o item falso e essa assertiva é verdadeira. Art. 9º Provimento 205/2021. Fica criado o Comitê Regulador do Marketing Jurídico, de caráter consultivo, vinculado à Diretoria do Conselho Federal, que nomeará seus membros, com mandato concomitante ao da gestão, e será composto por: II - 01 (um) representante do Colégio de Presidentes de Seccionais.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_06","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":6,"discipline":"Ética Profissional","topic":"Da Advocacia Pro Bono","statement":"A secretária Kim é uma jovem que possui uma grande admiração pelas causas sociais, visto que, durante sua infância, foi amparada por projetos de defesa social. Após passar no exame da ordem e requerer sua inscrição, ela decidiu prestar auxílio jurídico a uma instituição que carecia de apoio. Com dúvidas sobre o funcionamento da advocacia pro bono, ela pesquisou no Código de Ética e Disciplina que:","alternative_a":"Considera-se advocacia pro bono a prestação gratuita, eventual e voluntária de serviços jurídicos em favor de instituições sociais com ou sem fins econômicos, sempre que os beneficiários não dispuserem de recursos para a contratação de profissional.","alternative_b":"A advocacia pro bono pode ser exercida em favor de pessoas naturais que, igualmente, não dispuserem de recursos para, sem prejuízo do próprio sustento, contratar advogado.","alternative_c":"A advocacia pro bono não pode ser utilizada para fins político-partidários ou eleitorais, regra que não se aplica quando o intuito é beneficiar instituições que visem a tais objetivos.","alternative_d":"No exercício da advocacia pro bono e, ao atuar como defensor nomeado, conveniado ou dativo, o advogado empregará o zelo e a dedicação habituais, o que não importa na necessidade da parte se sentir totalmente assistida, visto que o advogado atua para ajudar.","correct_answer":"B","explanation":"A) Errada. Em favor de instituições sociais sem fins econômicos. Art. 30. §1º. CED. Considera-se advocacia pro bono a prestação gratuita, eventual e voluntária de serviços jurídicos em favor de instituições sociais sem fins econômicos e aos seus assistidos, sempre que os beneficiários não dispuserem de recursos para a contratação de profissional. B) Correta. São três os sujeitos-alvo dessa prática: instituições sociais sem fins econômicos; os seus assistidos, desde que não tenham condições de contratar advogado; e as pessoas naturais que, sem prejuízo do próprio sustento, não possam arcar com a remuneração deste profissional. Art. 30. §2º. CED. A advocacia pro bono pode ser exercida em favor de pessoas naturais que, igualmente, não dispuserem de recursos para, sem prejuízo do próprio sustento, contratar advogado. C) Errada. A advocacia pro bono não pode beneficiar instituições que visem objetivos político-partidários ou eleitorais. Art. 30. §3º. CED. A advocacia pro bono não pode ser utilizada para fins político partidários ou eleitorais, nem beneficiar instituições que visem a tais objetivos, ou como instrumento de publicidade para captação de clientela. D) Errada. O advogado empregará o zelo e a dedicação habituais, de forma que a parte por ele assistida se sinta amparada e confie no seu patrocínio. Art. 30. CED. No exercício da advocacia pro bono, e ao atuar como defensor nomeado, conveniado ou dativo, o advogado empregará o zelo e a dedicação habituais, de forma que a parte por ele assistida se sinta amparada e confie no seu patrocínio.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_07","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":7,"discipline":"Ética Profissional","topic":"Da Publicidade Profissional","statement":"Joel, empolgado com o recebimento da carteira da OAB, decide abrir seu próprio escritório e, visando ter um designer único, coloca um outdoor enorme na cidade para anunciar os seus serviços. Já Rayane, também advogada, aproveita que é comerciante já conhecida na cidade e opta por anunciar os seus serviços jurídicos juntamente aos serviços de sua outra atividade comercial. Dheise, por sua vez, tem uma estratégia diferente de publicidade. Ela decidiu que tentaria realizar algumas reportagens, concedendo algumas entrevistas aos meios de comunicação da cidade, a fim de que se tornasse conhecida publicamente como advogada. Sobre a conduta dos três amigos, marque a alternativa correta de acordo com o Código de Ética e Disciplina da OAB.","alternative_a":"Nenhum dos três cometeu publicidade irregular.","alternative_b":"Somente Joel e Rayane incorreram em práticas vedadas pelo Código de Ética.","alternative_c":"Os três advogados praticaram publicidade irregular.","alternative_d":"Somente Joel contrariou o Código de Ética.","correct_answer":"C","explanation":"A) Errada. Joel, Rayane e Dheise cometeram publicidade irregular. B) Errada. Dheise também incorreu em prática de publicidade vedada pelo Código de Ética, qual seja: insinuar-se para reportagens. C) Correta. Todas as três condutas configuram publicidade irregular. Joel - Art. 40, CED. Os meios utilizados para a publicidade profissional hão de ser compatíveis com a diretriz estabelecida no artigo anterior, sendo vedados: II - o uso de outdoors, painéis luminosos ou formas assemelhadas de publicidade; Rayane - Art. 40, CED. Os meios utilizados para a publicidade profissional hão de ser compatíveis com a diretriz estabelecida no artigo anterior, sendo vedados: IV - a divulgação de serviços de advocacia juntamente com a de outras atividades ou a indicação de vínculos entre uns e outras. Dheise - Art. 42, CDE. É vedado ao advogado: V - insinuar-se para reportagens e declarações públicas. D) Errada. Rayne e Dheise também incorreram em práticas vedadas pelo Código de Ética.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_08","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":8,"discipline":"Ética Profissional","topic":"Das Incompatibilidades e Impedimentos","statement":"Daniel é dono de cartório. Séfora ocupa função de direção em determinado órgão da Administração Pública direta. Já Damiana é juíza de direito. Sabendo disso, assinale a alternativa que indica aqueles que realizam atividade incompatível com o exercício da advocacia.","alternative_a":"Séfora e Daniel.","alternative_b":"Séfora e Damiana.","alternative_c":"Séfora, Daniel e Damiana.","alternative_d":"Somente Daniel.","correct_answer":"C","explanation":"A) Errada. Damiana (juíza) também exerce atividade incompatível com a advocacia. B) Errada. Daniel, como dono de cartório, desempenha atividade incompatível com a advocacia (exerce serviços notariais e de registro). C) Correta. Todas as três atividades citadas são incompatíveis com o exercício da advocacia. Nesse sentido, o Art. 28, EOAB. 4 A advocacia é incompatível (proibição total), mesmo em causa própria, com as seguintes atividades: II - membros de órgãos do Poder Judiciário, do Ministério Público, dos tribunais e conselhos de contas, dos juizados especiais, da justiça de paz, juízes classistas, bem como de todos os que exerçam função de julgamento em órgãos de deliberação coletiva da administração pública direta e indireta; III - ocupantes de cargos ou funções de direção em Órgãos da Administração Pública direta ou indireta, em suas fundações e em suas empresas controladas ou concessionárias de serviço público; IV - ocupantes de cargos ou funções vinculados direta ou indiretamente a qualquer órgão do Poder Judiciário e os que exercem serviços notariais e de registro. D) Errada. Os três exercem atividade incompatível com a advocacia. FILOSOFIA","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_09","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":9,"discipline":"Filosofia do Direito","topic":"Filosofia do Direito","statement":"A preocupação com a moralidade humana sempre foi um dos focos de Imannuel Kant, de modo que, após longos estudos, o filósofo desenvolveu o conceito conhecido como “O Imperativo Categórico”. Na prática, tal teoria tinha como escopo analisar o que motiva a ação humana e compreender a moral e a ética. Sobre o Imperativo Categórico, é correto afirmar que:","alternative_a":"Para Kant, o princípio supremo da moralidade está diretamente relacionado à maximização do bem-estar geral.","alternative_b":"A base da doutrina moral de Kant depende de uma visão religiosa que dá sentido à estruturação da sua teoria.","alternative_c":"Segunda Kant, a moral exclui a noção de intenção como elemento de uma alma pura, e o dever não é uma obrigação a ser seguida em virtude de um ente superior.","alternative_d":"Para Kant, intenção e dever não dependem do sujeito epistemológico (eu transcendental), mas do eu psicológico (indivíduo).","correct_answer":"C","explanation":"A doutrina moral de Kant independe de qualquer sentido religioso. Sua moral exclui a noção de intenção como elemento de uma alma pura, e o dever não é uma obrigação a ser seguida em virtude de um ente superior. Intenção e dever (em Kant) dependem do sujeito epistemológico (eu transcendental) e não do eu psicológico (indivíduo).","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":"TEMA nao localizado no gabarito; comentario discursivo, sem vereditos por alternativa; TEMA ausente no material; topic derivado da matéria"},{"id":"vde_ined3_10","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":10,"discipline":"Filosofia do Direito","topic":"Filosofia do Direito","statement":"Rudolf Smend, jurista alemão, desenvolveu, no início do século XX, uma doutrina constitucionalista que tinha, como objetivo, a aproximação entre a hermenêutica constitucional e a realidade social fática, através da aplicação coerente de normas da Constituição. Sua teoria teceu diversas críticas ao entendimento sobre sistema constitucional da época que possuía uma formalidade excessiva, quase mecânica. Assim sendo, a doutrina de Smend resultava na necessidade do hermeneuta, no desempenho da sua função, considerar os fatores externos (cultura, costumes, situação econômica da sociedade), para que, somente após essa avaliação, as normas constitucionais fossem aplicadas aos casos concretos, gerando, dessa forma, uma verdadeira integração, gradativa e contínua, da própria constituição. Essa teoria de Smend foi denominada de:","alternative_a":"Hermenêutico-concretizador.","alternative_b":"Normativo-estruturante.","alternative_c":"Tópico-problemático.","alternative_d":"Método Científico-espiritual.","correct_answer":"D","explanation":"O Método Científico-espiritual tem como finalidade analisar o espírito da CF e seus valores. Precisam ser verificados os valores axiológicos subjacentes ao texto constitucional. Tal teoria atua como elemento do processo de integração comunitária, visto que se atenta à cultura do povo, estágio social, situação econômica, etc. CONSTITUCIONAL","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":"TEMA nao localizado no gabarito; comentario discursivo, sem vereditos por alternativa; TEMA ausente no material; topic derivado da matéria"},{"id":"vde_ined3_11","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":11,"discipline":"Direito Constitucional","topic":"Direitos e Garantías Individuais","statement":"Determinado cidadão (jurisdicionado) apresentou reclamação, perante o Conselho Nacional de Justiça (CNJ), em face do juiz do trabalho. Ao apreciar o caso, o CNJ, em sessão presidida pelo Conselheiro Presidente do Supremo Tribunal Federal, conhece a reclamação e instaura Processo Administrativo Disciplinar (PAD). Considerando que os fundamentos da defesa já haviam sido amplamente apresentados pelo juiz do trabalho em suas manifestações públicas, o CNJ, em prol da celeridade processual, afastou a necessidade de nova manifestação do referido agente, tendo decidido pela aposentadoria do magistrado com proventos proporcionais ao tempo de serviço. Sobre o caso em tela, assinale a alternativa que analisa corretamente o acontecido.","alternative_a":"O referido cidadão não possui legitimidade para dirigir-se, diretamente, ao CNJ, uma vez não estar presente no rol de legitimados descritos pela Constituição Federal. Quanto ao procedimento adotado pelo Conselho, verifica-se que foi incorreto, visto que cerceou o direito de defesa do magistrado.","alternative_b":"O referido cidadão, segundo a Constituição Federal, possui legitimidade para representar ilegalidades perante o CNJ. Quanto ao procedimento adotado pelo Conselho, verifica-se que foi incorreto, visto que cerceou o direito de defesa do magistrado.","alternative_c":"O referido cidadão não possui legitimidade para dirigir-se, diretamente, ao CNJ, uma vez não estar presente no rol de legitimados descritos pela Constituição Federal. Quanto ao procedimento adotado pelo Conselho, verifica-se que foi correto, obedecendo o que é estipulado pela Carta Magna.","alternative_d":"O referido cidadão, segundo a Constituição Federal, possui legitimidade para representar ilegalidades perante o CNJ. Quanto ao procedimento adotado pelo Conselho, verifica-se que foi correto, obedecendo o que é estipulado pela Carta Magna.","correct_answer":"B","explanation":"A) Errada. A primeira parte da assertiva está errada, pois qualquer pessoa é parte legítima para representar ilegalidades perante o CNJ. B) Correta. De acordo com o direito de petição previsto no artigo 5º, inciso XXXIV, alínea a, da CRFB/88, “qualquer pessoa é parte legítima para representar ilegalidades perante o CNJ”. Em relação ao procedimento, ele foi equivocado, visto que impediu a defesa do juiz, ou seja, o seu direito fundamental à defesa que não pode ser prejudicado ou relativizado por conduta não prevista na Constituição da República. C) Errada. A primeira parte da assertiva está errada, pois qualquer pessoa é parte legítima para representar ilegalidades perante o CNJ. No que diz respeito ao procedimento, foi incorreto (contrariamente afirmado na assertiva), pois violou o direito fundamental à defesa. D) Errada. A primeira parte da assertiva está correta, todavia, no que diz respeito ao procedimento foi incorreto, por violar o direito fundamental à defesa.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_12","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":12,"discipline":"Direito Constitucional","topic":"Controle de Constitucionalidade","statement":"Em razão de flagrante inconstitucionalidade, o Governador do Estado T ajuizou uma representação de inconstitucionalidade contra a Lei Estadual X, perante o Tribunal de Justiça local. A motivação deu-se em razão da Lei em apreço ter violado normas contidas na Constituição Estadual e que são de reprodução obrigatória. Tendo este caso em mente, é correto afirmar que:","alternative_a":"O Governador agiu de maneira equivocada, pois deveria ajuizar, de imediato, uma Ação Direta de Inconstitucionalidade perante o Supremo Tribunal Federal.","alternative_b":"O posterior ajuizamento de uma Ação Direta de Inconstitucionalidade perante o Supremo Tribunal Federal não prejudicará a Representação de Inconstitucionalidade perante o TJ, dado que ambas podem tramitar simultaneamente.","alternative_c":"O Governador agiu de maneira equivocada, pois a Constituição Federal não permite que existam ADI’s estaduais, razão pela qual a Representação de Inconstitucionalidade Estadual não é coerente com a Carta Magna.","alternative_d":"O posterior ajuizamento de uma Ação Direta de Inconstitucionalidade perante o Supremo Tribunal Federal fará com que a Representação de Inconstitucionalidade Estadual seja suspensa até a decisão do STF.","correct_answer":"D","explanation":"A) Errada. O objeto da ADI é em face de lei ou ato normativo federal ou estadual e a ação declaratória de constitucionalidade de lei ou ato normativo federal. B) Errada. Haverá prejudicialidade, uma vez que suspender-se-á a ação direta proposta no TJ até o final da decisão do STF. C) Errada. O Objeto da ADI é em face de lei ou ato normativo federal ou estadual. D) Correta. Se a lei estadual for impugnada perante o Tribunal de Justiça local e perante o Supremo Tribunal Federal, com fundamento em norma constitucional de reprodução obrigatória, com base no princípio da simetria, suspende-se a ação direta proposta na Justiça estadual até a decisão final do Supremo Tribunal Federal.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_13","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":13,"discipline":"Direito Constitucional","topic":"Remédios Constitucionais","statement":"Em razão do grande índice de criminalidade no Estado R, o Presidente da República decidiu decretar intervenção federal na área da Segurança Pública. Dada a relevância social, a mídia resolveu fazer uma cobertura dos fatos, mas foi impedida de ter amplo acesso aos locais de operação, pois, segundo as autoridades, os jornalistas deveriam ficar a uma distância de 300 metros do local das abordagens. Em razão da flagrante violação aos direitos constitucionalmente amparados, os jornalistas decidiram tomar as medidas cabíveis. Assim sendo, a ação constitucional que devem adotar para garantir a liberdade violada é:","alternative_a":"Ação Popular.","alternative_b":"Habeas Data.","alternative_c":"Mandado de Segurança.","alternative_d":"Habeas Corpus.","correct_answer":"C","explanation":"A) Errada. A ação popular é o cidadão (no pleno gozo dos direitos políticos) que interpõe com o objetivo de anular ato lesivo ao Poder Público. B) Errada. O Habeas Data é remédio constitucional que visa assegurar informação ou retificação de dados. C) Correta. O mandado de segurança é instrumento destinado a proteger direito líquido e certo, não amparado por habeas corpus ou habeas data quando o responsável por ilegalidade ou abuso de poder for autoridade pública ou agente de PJ no exercício de atribuições do Poder Público. A situação narrada revela um ataque ao direito de liberdade de imprensa 5 (Art. 5º, XIV), razão pela qual não seria cabível Habeas Corpus, mas sim o Mandado de Segurança (em razão do seu caráter subsidiário). D) Errada. O Habeas Corpus é o remédio constitucional adequado para quando alguém se vê na iminência ou sofre uma restrição ilegal de sua liberdade.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_14","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":14,"discipline":"Direito Constitucional","topic":"Controle de Constitucionalidade","statement":"Após várias tentativas de diálogo com o Estado brasileiro para assegurar assistência à população quilombola no enfrentamento da pandemia de COVID-19, a Coordenação Nacional de Articulação das Comunidades Negras Rurais Quilombolas (CONAQ) constatou que não houve a elaboração e a implementação de um “Plano Nacional de Combate aos Efeitos da Pandemia de COVID-19 nas Comunidades Quilombolas”, garantindo acesso às medidas de proteção recomendadas pela Organização Mundial de Saúde (OMS) às comunidades quilombolas, tais como itens de higiene, álcool em gel, equipamentos de segurança individual, acesso à água potável e segurança alimentar. A omissão em assegurar essas medidas acaba por inviabilizar o isolamento social para a população quilombola. Em relação à omissão indicada pela CONAQ, considera-se que:","alternative_a":"Cabe mandado de injunção, pois a falta de norma regulamentadora torna inviável o exercício dos direitos e liberdades constitucionais e das prerrogativas inerentes à nacionalidade, à soberania e à cidadania.","alternative_b":"Cabe a propositura de Arguição de Descumprimento de Preceito Fundamental, pois a violação a direitos fundamentais só pode ser suscitada no controle concentrado por esta via.","alternative_c":"Cabe a propositura de Arguição de Descumprimento de Preceito Fundamental, por se tratar de impugnação de comportamento concreto da Administração Pública.","alternative_d":"Cabe Ação Direta de Inconstitucionalidade por Omissão para tornar efetiva a norma constitucional em razão de omissão de qualquer dos Poderes.","correct_answer":"C","explanation":"A) Errada. De acordo com a CF (art. 5°, LXXI) o Mandado de Injunção será cabível em caso de ausência de norma regulamentadora. O caso em questão não se trata disso, mas da não elaboração e ausência de implementação de um Plano Nacional de Combate aos Efeitos da Pandemia de COVID. B) Errada. A ADPF possui caráter subsidiário, razão pela qual a assertiva está errada ao afirmar que a “violação a direitos fundamentais só pode ser suscitada no controle concentrado por esta via.” Lei 9.882/99 Art. 4° A petição inicial será indeferida liminarmente, pelo relator, quando não for o caso de arguição de descumprimento de preceito fundamental, faltar algum dos requisitos prescritos nesta Lei ou for inepta. § 1° Não será admitida argüição de descumprimento de preceito fundamental quando houver qualquer outro meio eficaz de sanar a lesividade. C) Correta. Não há ausência de norma regulamentadora, mas da elaboração e da implementação de um Plano Nacional de Combate, ou seja, um ato não normativo, um ato concreto do poder público. Desse modo, mostra-se incabível Ação Direta de Inconstitucionalidade por Omissão ou Mandado de Injunção, pois esses instrumentos são destinados a impugnar a ausência de atos normativos. Portanto, como é possível o ajuizamento da Arguição de Descumprimento de Preceito Fundamental para impugnar atos não normativos do Poder Público, vê-se que a ADPF é o instrumento adequado para ser utilizado no caso em tela. D) Errada. O objetivo da ADI é o controle da lei ou ato normativo.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_15","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":15,"discipline":"Direito Constitucional","topic":"Competência Legislativa","statement":"Joel, atual prefeito do Município de Santa Maria da Boa Vista, movido pelos conhecimentos informais sobre o comércio, decide modificar o horário comercial da sua cidade. O objetivo era adequar o horário às necessidades dos cidadãos no que tange o desempenho das atividades profissionais. A mudança foi recebida com felicidade pela população, de modo que a primeira dama, que é bancária na cidade, também demonstrou gratidão em razão da possibilidade de ter um horário mais adequado ao costume do município. Sobre o caso narrado, assinale a alternativa correta.","alternative_a":"O Município não possui competência para legislar sobre o horário comercial, em razão desta temática ser de competência privativa da União.","alternative_b":"O Município possui competência para legislar sobre o horário comercial, em razão de ser assunto de interesse local. Ocorre que o setor bancário não pode ser beneficiado, visto que o tratamento sobre as instituições financeiras ultrapassa o interesse local, sendo de competência da União.","alternative_c":"Embora a competência para legislar sobre o horário comercial dos Municípios seja privativa 7 da União, entende-se que tal regra não alcança o tratamento sobre as instituições bancárias, razão pela qual o Prefeito poderá alterar o horário de funcionamento somente dos bancos.","alternative_d":"O Município possui competência para legislar sobre o horário comercial, em razão de ser assunto de interesse local. No que tange às instituições financeiras, a regra é que poderão ter seus horários modificados pelo Município, em razão do claro interesse local que legitima a competência legislativa municipal.","correct_answer":"B","explanation":"A) Errada. O Município possui sim competência para legislar sobre o horário comercial, exceto das instituições financeiras que são de competência da União. B) Correta. Por se tratar de assunto de interesse local, o Município poderá legislar sobre o horário do comércio, conforme o Art. 30, I, da CF/88 e a Súmula Vinculante 38. Ocorre que o horário de funcionamento das instituições financeiras ultrapassa o interesse local, não sendo possível sua alteração pelo Município, mas pela União (Art. 22, I, CF/88). C) Errada. A competência para legislar sobre o horário comercial dos Municípios não é privativa da União, os Municípios podem legislar sobre interesses locais. D) Errada. A primeira parte da assertiva está correta, mas a segunda equivocada, uma vez que em se tratando de instituições financeiras a competência é da União.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_16","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":16,"discipline":"Direito Constitucional","topic":"Poder Legislativo","statement":"O Estado Z, ao criar sua Constituição Estadual, possibilitou a alteração do texto constitucional através de projeto de emenda com iniciativa popular. Essa regra foi bastante questionada no que tange a sua constitucionalidade. Sobre essa previsão, pode-se afirmar que:","alternative_a":"Embora a Constituição Federal não preveja a iniciativa popular como legitimada para propor emendas à Constituição Federal, o Supremo Tribunal Federal entendeu a previsão da iniciativa popular como meio hábil para proposição de emendas às Constituições dos Estados como compatível com o texto constitucional.","alternative_b":"Além de não prever a iniciativa popular como meio hábil para propositura de Projetos de Emenda à Constituição, a Constituição Federal de 1988 tornou tal regra de observância obrigatória pelos Estados, razão pela qual não será possível a referida norma na Constituição do Estado Z.","alternative_c":"As Constituições Estaduais devem obediência aos valores e limites constitucionais bem como precisam seguir as normas de reprodução obrigatória, o que significa dizer que inexiste autonomia na construção dos textos. Assim sendo, a norma que vise inovar na Carta Estadual do Estado Z é contrária ao que apregoa a Constituição Federal.","alternative_d":"Embora preveja a Iniciativa Popular como meio hábil para a propositura de Projetos de Emenda à Constituição, a Constituição Federal de 1988 impossibilitou que essa regra fosse reproduzida no âmbito das Constituições Estaduais, razão pela qual não será possível a referida norma na Constituição do Estado Z.","correct_answer":"A","explanation":"A) Correta. Embora o art. 60 da CF/88 não preveja a iniciativa popular como legitimada para propor emendas à Constituição Federal, o Supremo Tribunal Federal entendeu a previsão da iniciativa popular como meio hábil para proposição de emendas às Constituições dos Estados como compatível com o texto constitucional. As Constituições Estaduais devem obediência aos valores e limites constitucionais, bem como precisam seguir as normas de reprodução obrigatória, mas isso não significa dizer que inexiste autonomia. B) Errada. O STF entendeu a previsão da iniciativa popular como meio hábil de proposição. C) Errada. O poder constituinte estadual tem certa liberdade criativa, o que ele não faz é inaugurar/instaurar/implementar uma nova ordem jurídica. D) Errada. A CF não prevê a iniciativa popular como legitimada. DIREITOS HUMANOS","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_17","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":17,"discipline":"Direitos Humanos","topic":"Sistema Interamericano de Proteção aos Direitos Humanos","statement":"“A Corte Interamericana de Direitos Humanos (...) é órgão jurisdicional do sistema interamericano que resolve sobre os casos de violação de direitos humanos perpetrados pelos Estados-partes da OEA e que tenham ratificado a Convenção Americana. Sua sede é na cidade de San José, Costa Rica. Trata-se de um tribunal supranacional interamericano capaz de condenar os Estados-partes da Convenção Americana por violação de direitos humanos, desde que estes tenham aceitado a competência contenciosa do tribunal”. (MAZZUOLI, Valerio de Oliveira. Curso de direitos humanos. 4. ed. São Paulo: Método, 2017, p. 149). Considerando o texto acima e as regras contidas na Convenção Americana de Direitos Humanos, quem ou quais órgãos podem submeter um caso à Corte Interamericana de Direitos Humanos?","alternative_a":"Somente os Estados e a Comissão Interamericana de Direitos Humanos podem submeter um caso à Corte Interamericana de Direitos Humanos.","alternative_b":"Somente a Comissão Interamericana de Direitos Humanos pode submeter um caso à Corte Interamericana de Direitos Humanos.","alternative_c":"A Defensoria Pública, o Ministério Público, os Estados e a Comissão Interamericana de Direitos Humanos podem submeter um caso à Corte Interamericana de Direitos Humanos.","alternative_d":"Qualquer pessoa natural pode submeter um caso à Corte Interamericana de Direitos Humanos.","correct_answer":"A","explanation":"A) Correta. Segundo o art. 61, item 1 da Convenção Americana de Direitos Humanos, \"Somente os 6 Estados Partes e a Comissão têm direito de submeter caso à decisão da Corte\". B) Errada. Segundo o art. 61, item 1 da Convenção Americana de Direitos Humanos, \"Somente os Estados Partes e a Comissão têm direito de submeter caso à decisão da Corte\". C) Errada. Segundo o art. 61, item 1 da Convenção Americana de Direitos Humanos, \"Somente os Estados Partes e a Comissão têm direito de submeter caso à decisão da Corte\". D) Errada. Segundo o art. 61, item 1 da Convenção Americana de Direitos Humanos, \"Somente os Estados Partes e a Comissão têm direito de submeter caso à decisão da Corte\".","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_18","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":18,"discipline":"Direitos Humanos","topic":"Direitos Humanos no Ordenamento Nacional","statement":"A respeito do controle de convencionalidade, assinale a alternativa correta, considerando o ordenamento jurídico interno e a jurisprudência da Corte Interamericana de Direitos Humanos.","alternative_a":"Só pode ser realizado em âmbito interno pelo Superior Tribunal de Justiça, haja vista o caráter supralegal do parâmetro de controle.","alternative_b":"Em âmbito interno, é um poder-dever não só dos membros do Poder Judiciário, mas de toda e qualquer autoridade pública.","alternative_c":"Trata-se de poder-dever exclusivo das cortes e tribunais internacionais, como a Corte Interamericana de Direitos Humanos.","alternative_d":"Em âmbito interno, é uma faculdade dos membros do Poder Judiciário.","correct_answer":"B","explanation":"A) Errada. O controle de convencionalidade não é feito somente pelo STJ, mas por todo o ordenamento jurídico. B) Correta. O controle de convencionalidade tem a finalidade de conformar a legislação brasileira aos tratados internacionais de direitos humanos em vigor no país. Nesse viés, a legislação nacional é tida como objeto, enquanto os tratados internacionais de direitos humanos são considerados parâmetros ou paradigmas, a ponto de ampliar a parametricidade constitucional. C) Errada. Não é poder-dever exclusivo das Cortes. O controle de convencionalidade deve ser exercido pelo Estado signatário, responsável pela adoção das medidas necessárias para o devido adimplemento da Convenção. D) Errada. A CCJ da Câmara dos Deputados ou do Senado, por exemplo, da mesma forma que pode entender pela inconstitucionalidade de uma lei, pode entender também por sua inconvencionalidade (neste último, caso se ela ferir tratado internacional de direitos humanos). Neste caso, é possível afirmar que o controle de convencionalidade não é exclusivamente jurisdicional. DIREITO ELEITORAL","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_19","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":19,"discipline":"Direito Eleitoral","topic":"Crimes Eleitorais","statement":"Jaiminho, candidato à prefeitura da cidade de Tangamandapio, durante o horário de propaganda eleitoral em rede televisiva, proferiu as seguintes palavras: “O atual prefeito e candidato à reeleição, que se mostra defensor da família, posando com esposa e filhos para fotos, foi flagrado na semana passada entrando em um motel com uma prostituta! É esse tipo de governante que você quer?”. A partir do caso exposto, assinale a opção que indica o delito praticado por Jaiminho.","alternative_a":"Injúria, previsto no Código Penal.","alternative_b":"Calúnia, previsto no Código Penal.","alternative_c":"Injúria, previsto no Código Eleitoral.","alternative_d":"Difamação, previsto no Código Eleitoral.","correct_answer":"D","explanation":"A) Errada. Por força do princípio da especialidade não se aplica ao crime previsto no CP e na verdade o crime praticado é o de \"difamação\". B) Errada. Por força do princípio da especialidade não se aplica ao crime previsto no CP e na verdade o crime praticado é o de “Difamação” e não de “Calúnia” que é imputar falsamente a alguém fato definido como crime (art. 138). C) Errada. Não se trata de crime de injúria, pois o objetivo do tipo penal é proteger a honra subjetiva (e não objetiva). D) Correta. Está de acordo com o art. 325 do Código Eleitoral. Código eleitoral. Art. 325. Difamar alguém, na propaganda eleitoral, ou visando a fins de propaganda, imputando-lhe fato ofensivo à sua reputação:","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_20","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":20,"discipline":"Direito Eleitoral","topic":"Inelegibilidade","statement":"Jake Peralta, delegado da polícia civil em atuação há dois anos na cidade noventa e nove, se candidatou ao cargo de prefeito desta cidade e solicitou formalmente sua desincompatibilização três meses antes do pleito. O Ministério Público ajuizou ação de impugnação de registro de candidatura. À luz do ordenamento jurídico em vigor e da jurisprudência atual, a ação de impugnação ao registro de candidatura de Jake Peralta:","alternative_a":"acarreta a declaração de inelegibilidade de Jake, se julgada procedente;","alternative_b":"pode ser ajuizada em até dez dias da publicação do edital relativo ao pedido de registro;","alternative_c":"deve ser julgada improcedente, uma vez que Jake se desincompatibilizou no prazo legal, três meses antes do pleito;","alternative_d":"deve ser julgada procedente, uma vez que Jake não se desincompatibilizou no prazo legal, quatro meses antes do pleito;","correct_answer":"D","explanation":"A) Errada. O objetivo da Ação de Impugnação de Registro de Candidatura (AIRC) é indeferir o pedido de registro de candidatura (e não declarar inelegibilidade do candidato). B) Errada. Só pode ser ajuizada após o registro da candidatura (Agravo Regimental em Recurso Ordinário nº 107-87 – Min. Gilmar Mendes – j. 17.09.2015) e o seu prazo final é a data da diplomação. (Agravo Regimental em Recurso Especial Eleitoral nº 35721 – Rel. Min. Carmem Lúcia – j. 19.08.2010). C) Errada. O prazo legal de desincompatibilização é de 4 meses (e não 3) D) Correta. O prazo legal é de 4 meses anteriores ao pleito, conforme art. 1°, IV, alínea C, da Lei Complementar 64/90: Art. 1º São inelegíveis: IV - para Prefeito e Vice-Prefeito: c) as autoridades policiais, civis ou militares, com exercício no Município, nos 4 (quatro) meses anteriores ao pleito; DIREITO INTERNACIONAL","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_21","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":21,"discipline":"Direito Internacional","topic":"Convenção de Viena sobre o Direito dos Tratados","statement":"Para fins de facilitar a organização dos tratados, bem como as relações oriundas destes, foi criado o Direito dos Tratados que tem, como principal fundamento jurídico, a Convenção de Viena sobre o Direito dos Tratados. Sobre o tema em análise, é correto afirmar que:","alternative_a":"A formulação de reservas é, em regra, facultada ao Estado que assina, ratifica, aceita, aprova ou adere a um tratado, mas o próprio tratado pode proibi-las.","alternative_b":"Um Estado pode, ao assinar, ratificar, aceitar ou aprovar um tratado, ou a ele aderir, formular uma reserva, mesmo que o tratado disponha que só possam ser formuladas determinadas reservas, entre as quais não figure a reserva em questão.","alternative_c":"Contrariando as disposições da Convenção de Viena sobre o Direito dos Tratados, o Estatuto de Roma, que criou o Tribunal Penal Internacional, vedou a formulação de reservas.","alternative_d":"A formulação de reservas é facultada ao Estado que assina, ratifica, aceita, aprova ou adere a um tratado, não podendo os tratados negarem o mencionado direito.","correct_answer":"A","explanation":"A) Correta. Conforme o Artigo 19 do Decreto 7.030/09: 7 \"Art. 19, Decreto 7.030/09: Um Estado pode, ao assinar, ratificar, aceitar ou aprovar um tratado, ou a ele aderir, formular uma reserva, a não ser que: a) a reserva seja proibida pelo tratado; b) o tratado disponha que só possam ser formuladas determinadas reservas, entre as quais não figure a reserva em questão; ou c) nos casos não previstos nas alíneas a e b, a reserva seja incompatível com o objeto e a finalidade do tratado. Artigo 20 Aceitação de Reservas e Objeções às Reservas\" B) Errada. Conforme o Artigo 19, alínea b) do Decreto 7.030/09, um Estado pode, ao assinar, ratificar, aceitar ou aprovar um tratado, ou a ele aderir, formular uma reserva, a não ser que o tratado disponha que só possam ser formuladas determinadas reservas, entre as quais não figure a reserva em questão. C) Errada. É possível a formulação de reservas conforme autoriza o Artigo 19 do Decreto 7.030/09. D) Errada. De acordo com o Artigo 120, D. 4.388/02 (Estatuto de Roma), Não são admitidas reservas a este Estatuto.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_22","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":22,"discipline":"Direito Internacional","topic":"Estatuto de Roma do Tribunal Penal Internacional","statement":"O Tribunal Penal Internacional é um órgão que tem como finalidade o julgamento de indivíduos responsáveis por crimes de grande gravidade e com repercussão internacional, tais como: crimes contra a humanidade, crimes de agressão, crime de genocídio e crimes de guerra. Sobre as suas disposições, é correto afirmar que:","alternative_a":"O poder que o Conselho de Segurança tem para solicitar adiamento do inquérito e do procedimento criminal no Tribunal Penal Internacional, por meio de resolução aprovada nos termos do disposto na Carta das Nações Unidas, está consignado no Estatuto de Roma.","alternative_b":"Não é possível que o Conselho de Segurança denuncie ao(à) procurador(a) do Tribunal Penal Internacional qualquer situação na qual haja indícios de prática de crimes previstos no Estatuto de Roma.","alternative_c":"O crime de agressão foi previsto desde a edição do Estatuto de Roma, embora as disposições sobre as condições para o exercício de jurisdição pelo Tribunal Penal Internacional tenham sido criadas em momentos diferentes.","alternative_d":"Não é possível que o Conselho de Segurança possa solicitar o adiamento de inquéritos e procedimentos criminais perante o Tribunal Penal Internacional, em razão da possibilidade de interferência política indevida.","correct_answer":"A","explanation":"A) Correta. Conforme o Artigo 16 do Decreto 4.388/02: \"Art. 16, Decreto 4.388/02: Adiamento do Inquérito e do Procedimento Criminal Nenhum inquérito ou procedimento crime poderá ter início ou prosseguir os seus termos, com base no presente Estatuto, por um período de doze meses a contar da data em que o Conselho de Segurança assim o tiver solicitado em resolução aprovada nos termos do disposto no Capítulo VII da Carta das Nações Unidas; o pedido poderá ser renovado pelo Conselho de Segurança nas mesmas condições.\" B) Errada. Conforme o Artigo 13 do Decreto 4.388/02: \"Art.13 do Decreto 4.388/02: Exercício da Jurisdição O Tribunal poderá exercer a sua jurisdição em relação a qualquer um dos crimes a que se refere o artigo 5o, de acordo com o disposto no presente Estatuto, se: a) Um Estado Parte denunciar ao Procurador, nos termos do artigo 14, qualquer situação em que haja indícios de ter ocorrido a prática de um ou vários desses crimes; b) O Conselho de Segurança, agindo nos termos do Capítulo VII da Carta das Nações Unidas, denunciar ao Procurador qualquer situação em que haja indícios de ter ocorrido a prática de um ou vários desses crimes; ou c) O Procurador tiver dado início a um inquérito sobre tal crime, nos termos do disposto no artigo 15.\" C) Errada. O crime de agressão não era inicialmente definido pelo Estatuto de Roma ou por qualquer disposição proferida pelo TPI. Entretanto, por força da Resolução RC 6, de 11/06/2010, foi finalmente definido como crime de agressão, por meio da inclusão do artigo 8, bis, ao Estatuto de Roma. D) Errada. É possível a solicitação do adiamento de inquéritos e procedimentos criminais conforme o Artigo 16 do Decreto 4.388/02. DIREITO FINANCEIRO","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_23","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":23,"discipline":"Direito Financeiro","topic":"Atividade Financeira do Estado","statement":"A atividade financeira do Estado, em sua maior parte, compreende o desenvolvimento das atividades políticas, sociais, econômicas e administrativas, que constituem sua finalidade precípua. A respeito da atividade financeira do Estado, é correto afirmar que:","alternative_a":"a atividade financeira do Estado é puramente instrumental, porque obter recursos e realizar gastos é um fim em si mesmo; além disso, o Estado tem por objetivo único o aumento de seu patrimônio (superávit).","alternative_b":"o objetivo fundamental da atividade financeira do Estado é proporcionar recursos econômicos para o custeio de sua manutenção e funcionamento, sendo que esta atividade está intimamente vinculada ao próprio fim do Estado, ou seja, o bem comum da população.","alternative_c":"todas as empresas públicas e as sociedades de economia mista, por expressa disposição constitucional, têm a finalidade de exercerem atividades financeiras em prol do bem comum e, por isso, todas gozam de privilégios fiscais, extensivos ou não às demais empresas do setor privado.","alternative_d":"a exploração direta de atividade econômica pelo Estado brasileiro é regra, permitindo, de forma excepcional, aos particulares, a livre iniciativa e a livre concorrência, de acordo com o que estabelece a Constituição Federal.","correct_answer":"B","explanation":"A) Errada. O superávit não é o único objetivo do estado, pois a atividade financeira busca a consecução das necessidades públicas. B) Correta. A atividade financeira constitui conjunto de meios utilizados pelo Estado para obtenção de valores pecuniários e realização de gastos, visando à execução de necessidades públicas. Portanto, fica claro que a atividade financeira tem um papel nitidamente instrumental, caracterizando-se como uma atividade meio para consecução dos objetivos do estado. C) Errada. O art. 173, § 2º, é expresso no sentido de que as empresas públicas e as sociedades de economia mista não poderão gozar de privilégios fiscais não extensivos às do setor privado. D) Errada. A exploração direta da atividade econômica pelo estado é a exceção, sendo autorizada somente quando necessária aos imperativos da segurança nacional ou a relevante interesse coletivo.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_24","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":24,"discipline":"Direito Financeiro","topic":"Da Receita Pública","statement":"As receitas públicas correspondem às disponibilidades de recursos financeiros que ingressam os cofres públicos, aumentando o saldo financeiro do ente governamental. Por meio desses recursos, são viabilizadas políticas públicas estipuladas em programas e ações. Dito isso, considerando a classificação das receitas públicas, são consideradas Receita de Capital:","alternative_a":"Operações de Crédito, Alienação de Bens, Amortização de Empréstimos e Transferências de Capital.","alternative_b":"Impostos, Taxas e Contribuição de Melhoria, Receita Patrimonial, Receita de Serviços e Alienação de Bens.","alternative_c":"Operações de Crédito, Impostos, Taxas e Contribuição de Melhoria, Receita Industrial e Amortização de Empréstimos.","alternative_d":"Impostos, Taxas e Contribuição de Melhoria, Receita Industrial, Amortização de Empréstimos e Receita de Serviços.","correct_answer":"A","explanation":"A) Correta. Receita de capital é aquela advinda de uma operação que gera patrimônio. Assim, são receitas que aumentam as disponibilidades financeiras do Estado e não provocam efeito sobre o patrimônio líquido. São exemplos as receitas provenientes da realização de recursos financeiros 8 oriundos de operações de Crédito, alienação de Bens, amortização de empréstimos e transferências de capital. Art. 11. Lei nº 4.320/64. A receita classificar-se-á nas seguintes categorias econômicas: Receitas Correntes e Receitas de Capital. §1º - São Receitas Correntes as receitas tributária, de contribuições, patrimonial, agropecuária, industrial, de serviços e outras e, ainda, as provenientes de recursos financeiros recebidos de outras pessoas de direito público ou privado, quando destinadas a atender despesas classificáveis em Despesas Correntes. § 2º - São Receitas de Capital as provenientes da realização de recursos financeiros oriundos de constituição de dívidas; da conversão, em espécie, de bens e direitos; os recursos recebidos de outras pessoas de direito público ou privado, destinados a atender despesas classificáveis em Despesas de Capital e, ainda, o superávit do Orçamento Corrente. RECEITAS DE CAPITAL: - Operações de Crédito - Alienação de Bens - Amortização de Empréstimos - Transferências de Capital - Outras Receitas De Capital TEMA: COMPETÊNCIA TRIBUTÁRIA A) Errada. As 5 principais características da competência tributária são: facultatividade, inalterabilidade, imprescritibilidade, irrenunciabilidade e indelegabilidade. Porém, tais características são fruto de construção doutrinária e não foram, expressamente, incorporadas ao CTN (apenas algumas das referidas características podem ser identificadas de forma expressa a partir da leitura do art. 7º do CTN, tais quais a indelegabilidade e a imprescritibilidade). Art. 7º. CTN. A competência tributária é indelegável, salvo atribuição das funções de arrecadar ou fiscalizar tributos, ou de executar leis, serviços, atos ou decisões administrativas em matéria tributária, conferida por uma pessoa jurídica de direito público a outra, nos termos do § 3º do artigo 18 da Constituição. Art. 8º. CTN. O não-exercício da competência tributária não a defere a pessoa jurídica de direito público diversa daquela a que a Constituição a tenha atribuído. RECEITAS CORRENTES: B) Errada. Observe que a alternativa fala que “o - Receita Tributária (impostos, taxas e contribuições de melhoria) Código Tributário Nacional prevê que o ente federativo competente pode delegar a outra pessoa jurídica de direito público as funções de instituir”, que é incorreto. A competência tributária é - Receita De Contribuições indelegável, ou seja, o ente federativo competente - Receita Patrimonial jamais pode delegar sua função de instituir o tributo. As únicas funções que podem ser delegadas - Receita Agropecuária são aquelas que compõem a capacidade ativa - Receita Industrial tributária, quais sejam: arrecadar e fiscalizar tributos, - Receita De Serviços executar leis, serviços, atos ou decisões administrativas em matéria tributária, nos termos do - Transferências Correntes art. 7º, caput do CTN. - Outras Receitas C) Errada. A capacidade ativa tributária apenas é Correntes delegável de uma pessoa jurídica à outra, conforme art. 7º, caput do CTN. Nesse sentido, o art. 7º, §3º do B) Errada. Apenas a alienação de bens é uma receita CTN determina expressamente que “não constitui de capital; as demais são receitas correntes. delegação de competência o cometimento, a C) Errada. Apenas a amortização e as operações de crédito são receita de capital; as demais são receitas pessoas de direito privado, do encargo ou da função de arrecadar tributos”. correntes. D) Correta. Nos termos do art. 153, §4º, III da CF, a D) Errada. Apenas a amortização é uma receita de capital; as demais são receitas correntes. União pode firmar convênio com os Municípios, a fim de que estes fiscalizem e cobrem o ITR, de forma que os Municípios passam a ter a capacidade ativa DIREITO TRIBUTÁRIO tributária em relação a esse tributo.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_25","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":25,"discipline":"Direito Tributário","topic":"Direito Financeiro","statement":"A respeito da competência tributária, assinale a alternativa correta.","alternative_a":"A competência tributária possui cinco características principais que foram doutrinariamente idealizadas e, posteriormente, incorporadas ao Código Tributário Nacional, quais sejam: facultatividade, inalterabilidade, imprescritibilidade, irrenunciabilidade e indelegabilidade.","alternative_b":"A competência tributária é indelegável, porém o Código Tributário Nacional prevê que o ente federativo competente pode delegar a outra pessoa jurídica de direito público as funções de instituir, arrecadar ou fiscalizar tributos e de executar leis, serviços, atos ou decisões administrativas em matéria tributária.","alternative_c":"A previsão legal que impõe às empresas empregadoras o dever de recolher o imposto sobre a renda de seus funcionários é exemplo de delegação da capacidade ativa tributária da União à pessoa jurídica de direito privado.","alternative_d":"A previsão constitucional que autoriza a União a firmar convênio com os Municípios para que estes arrecadem e fiscalizem o imposto territorial rural é exemplo de delegação da capacidade ativa tributária entre pessoas jurídicas de direito público.","correct_answer":"D","explanation":"Art. 153. CF. Compete à União instituir impostos sobre: 9 § 4º O imposto previsto no inciso VI do caput: III - será fiscalizado e cobrado pelos Municípios que assim optarem, na forma da lei, desde que não implique redução do imposto ou qualquer outra forma de renúncia fiscal.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":"TEMA nao localizado no gabarito; comentario discursivo, sem vereditos por alternativa; TEMA ausente no material; topic derivado da matéria; materia corrigida de Direito Financeiro para Direito Tributário: o gabarito nao traz o cabecalho desta secao"},{"id":"vde_ined3_26","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":26,"discipline":"Direito Tributário","topic":"Espécies Tributárias - Taxas","statement":"Um contribuinte do Município X recebeu a cobrança de taxa de coleta de lixo domiciliar relativamente ao ano de 2020. Contudo, o contribuinte esteve viajando a trabalho durante todo o ano de 2020 e não utilizou o serviço público de coleta de lixo sequer uma vez. Ademais, verificando os fatores utilizados pelo ente municipal para definição do montante do tributo devido, o contribuinte notou que a base de cálculo considerada foi o valor venal do imóvel residencial. A respeito da constitucionalidade da referida taxa, assinale a alternativa correta.","alternative_a":"A taxa exigida do contribuinte é inconstitucional, posto que só poderia ser cobrada se tivesse havido efetiva fruição do serviço público de coleta de lixo domiciliar.","alternative_b":"A taxa exigida do contribuinte é inconstitucional, pois taxa é a espécie tributária criada para remunerar o exercício regular do poder de polícia, não os serviços públicos como o de coleta de lixo domiciliar, que devem ser remunerados por impostos.","alternative_c":"A taxa exigida do contribuinte é inconstitucional, pois sua base de cálculo é própria de imposto, fato expressamente vedado pela Constituição Federal e pelo Código Tributário Nacional.","alternative_d":"A taxa exigida do contribuinte é constitucional, pois o Supremo Tribunal Federal já firmou entendimento no sentido de que a taxa cobrada exclusivamente em razão dos serviços públicos de coleta, remoção e tratamento ou destinação de lixo ou resíduos provenientes de imóveis não viola o conceito constitucional de taxa.","correct_answer":"C","explanation":"A) Errada. O serviço público de coleta de lixo domiciliar é de utilização potencial e foi posto à disposição do contribuinte, fato que já justifica a cobrança da taxa correspondente, independentemente de efetiva utilização. B) Errada. Conforme art. 145, II da CF e art. 77, caput do CTN, a taxa pode ter como fato gerador o exercício regular do poder de polícia ou a utilização, efetiva ou potencial, de serviço público específico e divisível, prestado ao contribuinte ou posto à sua disposição. C) Correta. O valor venal do imóvel já é a base de cáculo própria do IPTU, e, conforme art. 145, §2º da CF e art. 77, parágrafo único do CTN, as taxas não podem ter base de cálculo própria de imposto. Art. 77. Parágrafo único. CTN. A taxa não pode ter base de cálculo ou fato gerador idênticos aos que correspondam a imposto nem ser calculada em função do capital das empresas. Art. 145. §2º. CF. As taxas não poderão ter base de cálculo própria de impostos. D) Errada. Realmente o STF já firmou entendimento de que a “taxa cobrada exclusivamente em razão dos serviços públicos de coleta, remoção e tratamento ou destinação de lixo ou resíduos provenientes de imóveis, não viola o artigo 145, II, da Constituição Federal”, nos termos da Súmula Vinculante nº 19. Porém, no caso em tela a taxa cobrada do contribuinte não é constitucional, por ter base de cálculo própria do IPTU, o que contraria o art. 145, §2º da CF e o art. 77, parágrafo único do CTN","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":"materia corrigida de Direito Financeiro para Direito Tributário: o gabarito nao traz o cabecalho desta secao"},{"id":"vde_ined3_27","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":27,"discipline":"Direito Tributário","topic":"Execução Fiscal","statement":"A respeito da Execução Fiscal, assinale a alternativa correta.","alternative_a":"O ajuizamento da Execução Fiscal depende da existência de um título executivo judicial consubstanciado na Certidão de Dívida Ativa.","alternative_b":"Havendo colisão normativa entre o rito da Execução Fiscal previsto na Lei nº 6.830/1980 e o rito do Processo de Execução previsto no Código de Processo Civil de 2015, prevalecerá a disposição do CPC, por se tratar de norma posterior.","alternative_c":"Apenas a Fazenda possui legitimidade ativa para o ajuizamento de execução fiscal.","alternative_d":"A execução fiscal é a medida judicial que a Fazenda Pública dispõe para cobrar as dívidas de natureza, exclusivamente, tributária.","correct_answer":"C","explanation":"A) Errada. A Certidão de Dívida Ativa (CDA) é um título executivo extrajudicial (e não judicial), conforme art. 784, IX do CPC. Art. 784. CPC. São títulos executivos extrajudiciais: IX - a certidão de dívida ativa da Fazenda Pública da União, dos Estados, do Distrito Federal e dos Municípios, correspondente aos créditos inscritos na forma da lei; B) Errada. O CPC se aplica à Execução Fiscal de forma subsidiária, conforme art. 1º da Lei nº 6.830/1980 (Lei de Execução Fiscal – LEF), uma vez que a LEF é norma especial. Art. 1º. LEF. A execução judicial para cobrança da Dívida Ativa da União, dos Estados, do Distrito Federal, dos Municípios e respectivas autarquias será regida por esta Lei e, subsidiariamente, pelo Código de Processo Civil. C) Correta. A Execução Fiscal é a ação judicial da qual a Fazenda Pública (assim entendida a União, os Estados, o Distrito Federal, os Municípios e respectivas autarquias e fundações públicas de direito público) pode se valer para executar as dívidas das quais é credora, de forma que é apenas dela a legitimidade ativa para o ajuizamento da referida medida. Art. 1º. LEF. A execução judicial para cobrança da Dívida Ativa da União, dos Estados, do Distrito Federal, dos Municípios e respectivas autarquias será regida por esta Lei e, subsidiariamente, pelo Código de Processo Civil. D) Errada. A Fazenda Pública pode ajuizar a Execução Fiscal para cobrar judicialmente dívidas de natureza tributária ou não tributária, conforme art. 2º da LEF. Art. 2º. LEF. Constitui Dívida Ativa da Fazenda Pública aquela definida como tributária ou não tributária na Lei nº 4.320, de 17 de março de 1964, com as alterações posteriores, que estatui normas gerais de direito financeiro para elaboração e controle dos orçamentos e balanços da União, dos Estados, dos Municípios e do Distrito Federal.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":"materia corrigida de Direito Financeiro para Direito Tributário: o gabarito nao traz o cabecalho desta secao"},{"id":"vde_ined3_28","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":28,"discipline":"Direito Tributário","topic":"Crédito Tributário - Lançamento","statement":"A respeito das modalidades de lançamento tributário, assinale a alternativa correta.","alternative_a":"No caso dos tributos sujeitos ao lançamento de ofício e lançamento por declaração, conta-se o prazo decadencial de 5 anos para constituição do crédito tributário pelo lançamento a partir do primeiro dia do exercício seguinte àquele em que o lançamento poderia ter sido efetuado.","alternative_b":"O imposto de renda, tributo anualmente declarado pelos contribuintes, está sujeito a lançamento por declaração.","alternative_c":"Para os tributos sujeitos a lançamento por homologação, a extinção definitiva do crédito tributário ocorre com o pagamento do tributo.","alternative_d":"No caso dos tributos sujeitos a lançamento por homologação, conta-se o prazo decadencial de 5 anos para constituição do crédito tributário pelo lançamento apenas a partir da ocorrência do fato gerador.","correct_answer":"A","explanation":"A) Correta. No caso dos tributos sujeitos a lançamento de ofício e lançamento por declaração, conta-se o prazo decadencial de 5 anos para constituição do crédito tributário pelo lançamento na forma do art. 173, I do CTN, ou seja, a partir do primeiro dia do exercício seguinte àquele em que o lançamento poderia ter sido efetuado. Art. 173. CTN. O direito de a Fazenda Pública constituir o crédito tributário extingue-se após 5 (cinco) anos, contados: I - do primeiro dia do exercício seguinte àquele em que o lançamento poderia ter sido efetuado. 10 B)Errada. O imposto de renda é tributo sujeito a lançamento por homologação. #Atenção para essa pegadinha bem comum!!! Constantemente, ouvimos falar sobre a “Declaração de Imposto de Renda”, por isso é fácil confundir o tipo de lançamento desse imposto, já que rapidamente associamos ao termo “declaração”. No entanto, o tipo de lançamento ao qual o imposto de renda sujeita-se é o lançamento por homologação (o contribuinte presta todas as informações, faz-se o cálculo do imposto, o pagamento, e o Fisco apenas homologa). C) Errada. Para os tributos sujeitos a lançamento por homologação, a extinção definitiva do crédito tributário apenas ocorre com a homologação, pois o pagamento antecipado é feito “sob condição resolutória da ulterior homologação ao lançamento”, conforme art. 150, §1º do CTN. D) Errada. Em regra, no caso dos tributos sujeitos a lançamento por homologação, conta-se o prazo decadencial de 5 anos para a constituição do crédito tributário pelo lançamento, na forma do art. 150, §4º do CTN, ou seja, a partir da ocorrência do fato gerador. Contudo, excepcionalmente, tal prazo será contado na forma do art. 173, I do CTN (ou seja, a partir do primeiro dia do exercício seguinte àquele em que o lançamento poderia ter sido efetuado) desde que: i) comprovada a ocorrência de dolo, fraude ou simulação (independentemente de ter havido pagamento parcial ou não); ii) o débito seja declarado parcialmente e não pago; iii) sequer for declarado o débito (conforme Súmula nº 555 do STJ).","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":"materia corrigida de Direito Financeiro para Direito Tributário: o gabarito nao traz o cabecalho desta secao"},{"id":"vde_ined3_29","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":29,"discipline":"Direito Tributário","topic":"Prescrição e Decadência do Crédito Tributário","statement":"Em 01/07/2010, a empresa Loja de Biquinis Ltda., localizada no Estado X, praticou o fato gerador do ICMS ao vender mercadoria, contudo omitiu as operações de venda para não ser obrigada a recolher o referido imposto. Em 01/11/2015, o Fisco do Estado X descobriu a fraude tributária e constituiu o crédito tributário do ICMS, enviando notificação ao contribuinte sobre o lançamento do tributo, através de auto de infração. A referida notificação de lançamento foi recebida, pelo contribuinte, em 15/11/2015, com intimação para pagamento do tributo até 14/12/2015. Não havendo sido pago o imposto, em 01/11/2017 o Estado X inscreveu a empresa Loja de Biquinis Ltda. em dívida ativa e ajuizou a competente execução fiscal em 31/12/2018. Considerando o caso narrado, assinale a alternativa correta.","alternative_a":"O crédito tributário é indevido, pois ocorreu a sua extinção pelo instituto jurídico da decadência.","alternative_b":"O crédito tributário é indevido, pois ocorreu a sua extinção pelo instituto jurídico da prescrição.","alternative_c":"A contagem do prazo prescricional para o ajuizamento da execução fiscal foi suspensa por 180 dias após a inscrição do débito em dívida ativa.","alternative_d":"O crédito tributário é devido, pois não ocorreu a sua extinção nem pelo instituto jurídico da decadência nem pelo instituto jurídico da prescrição.","correct_answer":"D","explanation":"A) Errada. Considerando que houve fraude tributária, o prazo para constituir o crédito tributário sujeito ao lançamento por homologação teve início a partir do dia 1º do exercício seguinte. Assim, como o fato gerador ocorreu em de 01/07/2010, o prazo se iniciou em 01/01/2011, encerrando-se em 31/12/2015. Como a notificação do lançamento se deu em 15/11/2015, não ocorreu a decadência. B) Errada. Nos termos do art. 174, CTN, o prazo prescricional é de 5 anos, contados da data da constituição definitiva. A constituição definitiva se deu após o decurso do prazo sem pagamento por parte do contribuinte, ou seja, em 15/12/2015, tendo o fisco até 14/12/2020 para ajuizar a Ação de Execução Fiscal para a cobrança do débito. Como o ajuizamento da execução fiscal ocorreu em 31/12/2018 (dentro do prazo), não há que se falar em prescrição. C) Errada. Não se aplica o art. 2º, §1º, da Lei de Execução Fiscal, que prevê a suspensão da prescrição por 180 dias a partir da inscrição em dívida ativa, para os créditos de natureza tributária. D) Correta. O crédito tributário é devido, porque, no presente caso, o prazo decadencial de 5 anos para a realização do lançamento conta-se na forma do art. 173, I do CTN, uma vez que, mesmo se tratando de tributo sujeito a lançamento por homologação, comprovou-se a ocorrência de fraude, conforme determina o art. 150, §4º do CTN. Assim, o prazo decadencial de 5 anos começou a ser contado no primeiro dia do exercício seguinte àquele em que o lançamento poderia ter sido efetuado, ou seja, a partir de 01/01/2011, de forma que o Fisco teria até o dia 31/12/2015 para constituir o crédito tributário, e o fez tempestivamente, em 01/11/2015. Ademais, o contribuinte não realizou o pagamento do tributo, de forma que a constituição definitiva do crédito tributário ocorreu em 15/12/2015, tendo o Fisco até 14/12/2020 para fazer o ajuizamento da Execução Fiscal, por ter o prazo prescricional de 5 anos para tanto, nos termos do art. 174 do CTN, e o fez tempestivamente, em 31/12/2018. Ressalta-se que o art. 1º, §3º da LEF não se aplica à dívida ativa tributária, por isso não houve suspensão do prazo prescricional após a inscrição do débito em dívida ativa. DIREITO ADMINISTRATIVO","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":"materia corrigida de Direito Financeiro para Direito Tributário: o gabarito nao traz o cabecalho desta secao"},{"id":"vde_ined3_30","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":30,"discipline":"Direito Administrativo","topic":"Responsabilidade Civil do Estado","statement":"Imagine uma situação hipotética onde Nate Archibald, agente público, atuando no seu serviço prejudica um particular. Sendo assim, acerca da responsabilidade civil do Estado, assinale a alternativa correta.","alternative_a":"Na análise da responsabilidade civil do Estado em casos de prejuízo causado a terceiros, deve-se verificar a existência de conduta culposa ou dolosa do agente público causador do dano.","alternative_b":"A absolvição do agente público na esfera criminal afasta, automaticamente, a responsabilidade civil do Estado.","alternative_c":"A responsabilidade civil do Estado, assim como a das pessoas jurídicas de direito privado prestadoras de serviço público, baseia-se na teoria do risco integral.","alternative_d":"O Estado responde objetivamente por danos causados a terceiros, mas fica com direito de regresso contra o servidor que causou o dano, desde que este tenha agido com culpa ou dolo.","correct_answer":"D","explanation":"A) Errada. Como se aplica a “Teoria do Risco Administrativo”, o Estado responde independente de culpa ou dolo e, deve promover ação de regresso, em face do agente público (e aí sim aufere culpa ou dolo). B) Errada. As esferas são interdependentes, o que pode ocorrer é a vinculação na esfera administrativa e desde que negue a existência do fato ou autoria (Art. 126, da Lei 8.112/90). C) Errada. Aplica-se a “Teoria do Risco Administrativo” e não do risco integral. 11 D) Correta. CF, § 6º: \"As pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa\". A responsabilidade civil do Estado pelos atos de seus agentes baseia-se na Teoria do Risco Administrativo, que permite a exclusão do dever de indenizar, caso haja a ocorrência de alguma das excludentes do nexo de causalidade (caso fortuito, força maior, etc), diferentemente da Teoria do Risco Integral, em que não se admite as excludentes do nexo de causalidade (direito ambiental e nuclear).","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_31","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":31,"discipline":"Direito Administrativo","topic":"Serviços Públicos","statement":"Blair Waldorf, prefeita de São Paulo, deseja contratar, pelo Poder Público, serviços de construção, operação, administração e gestão de serviços não pedagógicos de 10 unidades municipais de ensino infantil, mediante licitação, pelo prazo de 30 (trinta) anos, com valor estimado de R$ 20.000.000,00 e estipulação de pagamento da remuneração, exclusivamente, pelo Poder Público. Tal explicação constitui, em tese, hipótese de:","alternative_a":"Concessão patrocinada.","alternative_b":"Concessão comum de serviço público.","alternative_c":"Concessão administrativa.","alternative_d":"Concessão de direito real de uso.","correct_answer":"C","explanation":"A) Errada. Nesse caso não haverá a tarifa do usuário, por isso, não pode ser a concessão patrocinada. B) Errada. Concessão comum é a delegação de serviço público a particulares por parte da Administração Pública. C) Correta. CONCESSÃO PATROCINADA - ocorre com serviços públicos + mão de obra, onde a administração dá a contraprestação e usuário paga a tarifa. Exemplo: pedágio e metrô. CONCESSÃO ADMINISTRATIVA - a própria Administração é usuária do serviço. Exemplo: construção de um presídio. (Na concessão administrativa só a ADMINISTRAÇÃO PAGA). D) Errada. Diz respeito a uma forma de utilização de terrenos públicos ou espaço aéreo.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_32","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":32,"discipline":"Direito Administrativo","topic":"Agentes Públicos","statement":"Jughead Jones, servidor público federal, está sendo exonerado. A exoneração, hipótese de vacância, que acarreta a destituição do servidor de cargo, emprego ou função, tem como característica tratar-se de medida aplicável:","alternative_a":"Apenas ex officio pela autoridade imediatamente superior ao agente público.","alternative_b":"Com efeito de desligamento do agente dos quadros do funcionalismo, após constatação de sua incapacidade por laudo médico.","alternative_c":"Em decorrência de penalidade imposta após procedimento disciplinar regular.","alternative_d":"Quando o servidor toma posse, mas não entra em exercício no prazo estabelecido.","correct_answer":"D","explanation":"A) Errada. Pode ser a pedido ou de ofício. B) Errada. Nesse caso, ocorre a readaptação, que é a investidura do servidor em cargo de atribuições e responsabilidades compatíveis com a limitação que tenha sofrido em sua capacidade física ou mental verificada em inspeção médica (art. 24) Lei 8.112/90: Art. 186 § 3° Na hipótese do inciso I o servidor será submetido à junta médica oficial, que atestará a invalidez quando caracterizada a incapacidade para o desempenho das atribuições do cargo ou a impossibilidade de se aplicar o disposto no art. 24. C) Errada. Não se trata de penalidade que são: advertência, suspensão, demissão, cassação de aposentadoria ou disponibilidade; destituição de cargo em comissão; e destituição de função comissionada (art. 127 da Lei 8.112/90) D) Correta. Lei 8.112/90 Art. 8° São formas de provimento de cargo público: I - nomeação; Art. 13, § 1° A posse ocorrerá no prazo de trinta dias contados da publicação do ato de provimento. § 6° Será tornado sem efeito o ato de provimento se a posse não ocorrer no prazo previsto no § 1o deste artigo. Art. 34. A exoneração de cargo efetivo dar-se-á a pedido do servidor, ou de ofício. Parágrafo único. A exoneração de ofício dar-se-á: I - quando não satisfeitas as condições do estágio probatório; II - quando, tendo tomado posse, o servidor não entrar em exercício no prazo estabelecido.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_33","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":33,"discipline":"Direito Administrativo","topic":"Atos Administrativos","statement":"A respeito dos Atos Administrativos, marque a alternativa correta:","alternative_a":"A autoexecutoriedade tem como fundamento salvaguardar o interesse público e o ato pode ser executado imediatamente, desde que haja o crivo do Judiciário.","alternative_b":"A finalidade é um dos atributos do ato administrativo e descreve o que o administrador pretende realizar.","alternative_c":"O motivo é a situação de fato ou de direito que gera a vontade do agente quando pratica o ato administrativo.","alternative_d":"A imperatividade é um dos requisitos do ato administrativo e estabelece a possibilidade de a administração pública definir, unilateralmente, quais serão os atos de consentimento.","correct_answer":"C","explanation":"A) Errada. A autoexecutoriedade significa que o ato pode ser executado independente de ordem judicial. Mas não confunda! Isso não significa que não pode haver controle judicial do ato. Este atributo só estará presente diante de lei ou em casos urgentes. B) Errada. A finalidade geral do ato administrativo é satisfazer o interesse público. Já a finalidade específica é aquela que a lei determinou ao ato em específico. O ato administrativo deve satisfazer ao interesse público ou à finalidade prevista em lei, sendo, portanto, um elemento vinculado. C) Correta. O motivo é a situação de fato e de direito que gera a vontade do agente que pratica o ato. Mas não o confunda com motivação, já que esta é definida como a exposição desse motivo. Logo, todo ato deve ter um motivo, mas nem todo ato precisa da exposição dele. Por exemplo, a exoneração de ocupante de cargo de provimento em comissão não precisa de motivação, mas precisa de motivo. D) Errada. A imperatividade traz a possibilidade de os atos administrativos serem impostos a terceiros independente da concordância destes. Mas não são 12 todos os atos administrativos que são dotados deste atributo. Sobre os atos administrativos A presunção de legitimidade significa que os atos foram realizados em conformidade com a lei. Já a presunção de veracidade significa que os atos, por serem alegados pela administração, presumem-se verdadeiros. A tipicidade prevê que o ato administrativo deve estar definido em lei para que se torne apto a produzir determinados resultados. A competência é o poder legal conferido ao agente para desempenhar as atribuições, ou seja, o agente seria o sujeito da realização do ato. Elementos vinculados são aqueles previstos em lei, então, a competência é um elemento vinculado. A Forma é o modo de exteriorização do ato, a maneira de se manifestar no mundo externo. Por exemplo, o edital é a forma de tornar pública a realização do concurso público. Em sentido amplo, também se incluem como forma as exigências procedimentais para realização do ato. Já que as formalidades estão previstas em lei e devem ser seguidas, também se considera a forma como elemento vinculado dos atos administrativos. Objeto/conteúdo: considerando que a finalidade é o resultado mediato desejado para o ato, considera-se que o objeto é o fim imediato do ato. Assim sendo, representa o resultado prático a que determinado ato administrativo conduz.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_34","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":34,"discipline":"Direito Administrativo","topic":"Organização da Administração Pública - Estatais","statement":"Fallon Carrigton, interessada em investir parcela dos seus milhões herdados da Dinastia Carrigton, deseja entender um pouco mais sobre as empresas estatais. Levando em consideração as especificidades das empresas estatais na organização da Administração Pública brasileira, mostre para Fallon o que se encaixa como correto acerca das estatais:","alternative_a":"Dado que o poder de polícia é titularizado por pessoas jurídicas de direito público, resta inviável sua delegação à sociedade de economia mista.","alternative_b":"O regime de precatórios é inaplicável às sociedades de economia mista prestadoras de serviço público próprio de Estado e de natureza não concorrencial.","alternative_c":"A alienação do controle acionário de empresas públicas e sociedades de economia mista prescinde de autorização legislativa e poderá ser operacionalizada sem processo de licitação pública.","alternative_d":"As sociedades de economia mista não poderão adotar, como tipo societário, sociedade limitada, podendo ser constituídas somente como sociedades anônimas.","correct_answer":"D","explanation":"A) Errada. É possível a delegação do Poder de Polícia desde que observado os requisitos da jurisprudência do STF: 1. O Plenário deste Supremo Tribunal reconheceu repercussão geral ao thema decidendum, veiculado nos autos destes recursos extraordinários, referente à definição da compatibilidade constitucional da delegação do poder de polícia administrativa a pessoas jurídicas de direito privado integrantes da Administração Pública indireta prestadoras de serviço público. (RE 633782, Relator(a): LUIZ FUX, Tribunal Pleno, julgado em 26/10/2020, PROCESSO ELETRÔNICO REPERCUSSÃO GERAL - MÉRITO DJe-279 DIVULG 24-11-2020 PUBLIC 25-11-20) B) Errada. Podem se beneficiar dos regimes de precatórios desde que prestem serviço público próprio do Estado e de natureza não concorrencial. (ADPF 387). C) Errada. A alienação do controle acionário de empresas públicas e sociedades de economia mista exige autorização legislativa e licitação; 2) A exigência de autorização legislativa, todavia, não se aplica à alienação do controle de suas subsidiárias e controladas. Nesse caso, a operação pode ser realizada sem a necessidade de licitação, desde que siga procedimentos que observem os princípios da administração pública inscritos no art. 37 da CF/88, respeitada, sempre, a exigência de necessária competitividade. ADI 5624 - 2019 D) Correta. Art. 4º Lei 13.303/2016. Sociedade de economia mista é a entidade dotada de personalidade jurídica de direito privado, com criação autorizada por lei, sob a forma de sociedade anônima, cujas ações com direito a voto pertençam em sua maioria à União, aos Estados, ao Distrito Federal, aos Municípios ou a entidade da administração indireta. DIREITO AMBIENTAL","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_35","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":35,"discipline":"Direito Ambiental","topic":"Princípios do Direito Ambiental","statement":"A vocação redistributiva do Direito Ambiental indica que o poluidor deve responder pelos custos sociais externos que acompanham o processo produtivo, ou seja, pela poluição ou degradação que causa em decorrência de suas atividades. Dessa forma, o ordenamento jurídico busca a internalização dos prejuízos ambientais de maneira que aquele que internaliza e beneficia- se com o lucro deve arcar e internalizar também os prejuízos que causou, por força do princípio:","alternative_a":"Da prevenção, que garante a integral reparação dos danos ambientais à coletividade, titular do direito difuso.","alternative_b":"Da precaução, que prevê, com base científica, os danos ambientais que serão causados e já os mitiga.","alternative_c":"Do poluidor-pagador, que visa impedir a privatização dos lucros e a socialização das perdas.","alternative_d":"Da solidariedade intergeracional, que determina que a atual geração deve arcar, integralmente, com os danos causados anteriormente.","correct_answer":"C","explanation":"A) Errada. Pois o princípio da prevenção volta-se às atividades de risco certo, conhecido ou concreto, onde já se sabe a extensão e a natureza dos males ambientais. Existe base científica para prever os impactos ambientais negativos decorrentes de determinada atividade lesiva ao meio ambiente, por isso deve-se impor ao empreendedor condicionantes no licenciamento ambiental para mitigar os prejuízos. B) Errada. Pois o princípio da precaução diz que, se determinado empreendimento puder causar danos ambientais sérios ou irreversíveis, ainda que não exista certeza científica (perigo abstrato ou potencial) quanto aos efetivos danos e a sua extensão, o empreendedor será compelido a adotar medidas de precaução, a fim de elidir ou reduzir os riscos ambientais à população (in dubio pro natura). C) Correta. Pois o princípio poluidor-pagador diz que o poluidor deve responder pelos custos sociais da degradação causada por sua atividade impactante (internalização dos prejuízos ambientais), devendo agregar esse valor ao custo produtivo da atividade a 13 fim de evitar que os lucros sejam privatizados e que os prejuízos ambientais se socializem. D) Errada. Pois o princípio da solidariedade intergeracional diz que todos têm direito ao meio ambiente ecologicamente equilibrado, bem de uso comum do povo e essencial à sadia qualidade de vida, impondo, ao Poder Público e à coletividade, o dever de defendê-lo e preservá-lo para as presentes e futuras gerações, conforme art. 225 da CRFB/88.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_36","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":36,"discipline":"Direito Ambiental","topic":"Proteção do Meio Ambiente em Normas Infraconstitucionais","statement":"De acordo com a Resolução CONAMA nº 369/2006, a intervenção ou supressão, eventual e de baixo impacto ambiental, da vegetação em Área de Preservação Permanente (APP) não pode, em qualquer caso, exceder ao percentual de:","alternative_a":"10% (dez por cento) da APP impactada localizada na posse ou propriedade.","alternative_b":"5% (cinco por cento) da APP impactada localizada próxima a mananciais.","alternative_c":"10% (dez por cento) da APP impactada localizada próxima a mananciais.","alternative_d":"5% (cinco por cento) da APP impactada localizada na posse ou propriedade.","correct_answer":"D","explanation":"A) Errada. O percentual é de 5%. B) Errada. O percentual é de 5% (cinco por cento) da APP impactada localizada na posse ou propriedade. C) Errada.O percentual é de 5% (cinco por cento) da APP impactada localizada na posse ou propriedade. D) Correta. Conforme o artigo 11, § 2º da Res. n. 369/06 – CONAMA “a intervenção ou supressão, eventual e de baixo impacto ambiental, da vegetação em APP não pode, em qualquer caso, exceder ao percentual de 5% (cinco por cento) da APP impactada localizada na posse ou propriedade. Deste modo, a intervenção ou supressão, eventual e de baixo impacto ambiental, da vegetação em APP não pode exceder o percentual de 5% da APP impactada localizada na posse ou propriedade. DIREITO CIVIL","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_37","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":37,"discipline":"Direito Civil","topic":"Sucessões - Cessão de Direitos Hereditários","statement":"Aline, Marina e Isabella, após a morte do pai, adquirem um imóvel de herança. Sendo assim, cada uma possui um terço do imóvel. Aline manifesta vontade em alienar o bem, mas Marina sempre se mostrou resistente, pois era o imóvel onde o pai viveu a vida toda, havendo ali uma carga emocional muito grande. Aline aliena, gratuitamente, sua quota para Isabella. Marina, indignada, procura informações de uma advogada. Marque alternativa que corresponda à explicação de acordo com a lei civil.","alternative_a":"Antes de alienar a cota, Aline deveria ter oferecido o bem para Marina.","alternative_b":"Não é possível alienar cota que esteja em condomínio decorrente de herança.","alternative_c":"Marina poderá tomar o bem para si depositando o valor correspondente à cota.","alternative_d":"Aline não tinha obrigação de oferecer a alienação de sua cota para Marina e a referida transferência para Isabella é válida.","correct_answer":"D","explanation":"A) Errada. O herdeiro tem direito de ceder sua cota hereditária para outro herdeiro. No caso de oferecer para terceiro estranho à sucessão então deve ser exercido o direito de preferência aos demais co-herdeiros. A restrição de cessão de cotas hereditárias é apenas em relação a terceiros. B) Errada. É possível realizar a cessão de direitos hereditários de forma gratuita ou onerosa. C) Errada. De acordo com o art. 1.795 do CC: “Art. 1.795, CC: o co-herdeiro, a quem não se der conhecimento da cessão, poderá, depositado o preço, haver para si a quota cedida a estranho, se o requerer até cento e oitenta dias após a transmissão”. Ocorre que a cota não foi cedida para estranho, mas para outra pessoa também herdeira. D) Correta. Aline só teria o dever de realizar o direito de preferência no caso de ter oferecido a sua cota hereditária para terceiro estranho à sucessão. Como na hipótese em questão oferece para sua irmã, pessoa que está inclusa na sucessão, então poderia ceder livremente.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_38","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":38,"discipline":"Direito Civil","topic":"Parte Geral - Direitos da Personalidade","statement":"Uma revista publicou fotografias de Caio vinculadas a uma matéria que falava sobre suas qualidades físicas e morais, mas Caio não havia concedido autorização. Diante dessa situação, Caio pleiteia, em juízo, compensação pecuniária por dano moral. O pedido deve ser julgado:","alternative_a":"Improcedente, salvo comprovação de que houve prejuízo econômico para o autor.","alternative_b":"Procedente, pois houve ofensa à denominada imagem atribuída.","alternative_c":"Improcedente, pois não houve ofensa à honra do autor.","alternative_d":"Procedente, pois a imagem foi utilizada sem autorização e há finalidade econômica.","correct_answer":"D","explanation":"A) Errada. A imagem é violada pelo uso independente de ter causado danos. B) Errada. A imagem-atributo é a forma como a pessoa é vista pelos demais, é a sua “fama”, numa perspectiva histórico-social e psíquica. Viola-se a imagem da pessoa ao trazer uma perspectiva diversa, mesmo que lícita, da perspectiva social que ela goza. C) Errada. O uso da imagem sem autorização gera danos, mesmo que não seja ofensiva. O dano é a própria utilização indevida da imagem com fins lucrativos, não sendo necessária a demonstração do prejuízo material ou moral, ou seja, é desnecessário fazer prova de dano senão da utilização inadequada da imagem, sem autorização da pessoa. D) Correta. A imagem foi usada sem autorização em uma revista para fins econômicos, devendo o pleito ser julgado procedente, conforme o Artigo 20 do CC: “Art. 20, CC: salvo se autorizadas, ou se necessárias à administração da justiça ou à manutenção da ordem pública, a divulgação de escritos, a transmissão da palavra, ou a publicação, a exposição ou a utilização da imagem de uma pessoa poderão ser proibidas, a seu requerimento e sem prejuízo da indenização que couber, se lhe atingirem a honra, a boa fama ou a respeitabilidade, ou se se destinarem a fins comerciais”.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_39","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":39,"discipline":"Direito Civil","topic":"Responsabilidade Civil","statement":"Eduardo, 15 anos, representado por sua mãe, Carmen, herda vultosa quantia em dinheiro de seu tio-avô. Após ganhar uma bicicleta de aniversário, resolve testá-la e, ao sair da loja em que sua mãe trabalha, desequilibra-se e cai na pista de rolamento da rua em frente ao estabelecimento. No momento da queda, Felipe, que conduzia seu carro, desvia-se de Eduardo, que nada sofre, mas colide com a lateral do automóvel de Rebeca, estacionado do outro lado da rua. A colisão ocasionou danos em ambos os veículos automotores, mas, como trafegava em baixa velocidade, Felipe saiu, fisicamente, ileso. Diante destes fatos, assinale a afirmativa correta.","alternative_a":"A incapacidade civil de Eduardo impede Felipe de responsabilizá-lo patrimonialmente pelos danos sofridos.","alternative_b":"Felipe deverá provar a negligência de Carmen no exercício da autoridade parental para que haja indenização.","alternative_c":"Felipe nada deverá pagar à Rebeca, pois agiu em estado de necessidade.","alternative_d":"Rebeca faz jus à indenização pelos danos ocasionados ao seu carro por Felipe, que poderá ressarci-los.","correct_answer":"D","explanation":"A) Errada. Em face da incapacidade absoluta de Eduardo, pois possui apenas 15 anos, devem ser observados os Artigos 928, 932, I, 933 e 934 do CC. Nos termos do Artigo 928 do CC: \"Art. 928, CC: O incapaz responde pelos prejuízos que causar, se as pessoas por ele responsáveis não 14 tiverem obrigação de fazê-lo ou não dispuserem de meios suficientes. Parágrafo único. A indenização prevista neste artigo, que deverá ser eqüitativa, não terá lugar se privar do necessário o incapaz ou as pessoas que dele dependem.\" Ou seja, é uma hipótese de responsabilidade civil subsidiária. No caso, se Carmen não tivesse recursos para pagar a indenização, Eduardo poderia ser obrigado a pagar os prejuízos de Felipe e Rebeca, uma vez que Eduardo recebeu herança de seu tio avô, conforme afirmado no enunciado, sendo que tal indenização não comprometeria sua subsistência ou das pessoas que dele dependem, nos termos do parágrafo único do art. 928 do CC. Diante da incapacidade civil de Eduardo, ele pode ser responsabilizado de forma subsidiária. B) Errada. Conforme o Artigo 933 do CC, a responsabilidade civil de pais para atos de filhos menores é objetiva, ou seja, independe de culpa. \"Art. 933, CC: As pessoas indicadas nos incisos I a V do artigo antecedente, ainda que não haja culpa de sua parte, responderão pelos atos praticados pelos terceiros ali referidos.\" C) Errada. A afirmativa contraria os arts. 929 e 930, CC, ou seja, se a pessoa lesada não for culpada do perigo, vai ter direito à indenização. No caso em que o perigo ocorrer por culpa de terceiro, contra este terá o autor do dano ação regressiva para reaver a importância que tiver ressarcido ao lesado. Sendo assim, ainda que a atitude de Felipe seja lícita, por estar em estado de necessidade, deverá indenizar Rebeca por ter lhe causado um dano. \"Art. 929, CC: Se a pessoa lesada, ou o dono da coisa, no caso do inciso II do art. 188, não forem culpados do perigo, assistir-lhes-á direito à indenização do prejuízo que sofreram.\" \"Art. 930, CC: No caso do inciso II do art. 188, se o perigo ocorrer por culpa de terceiro, contra este terá o autor do dano ação regressiva para haver a importância que tiver ressarcido ao lesado. Parágrafo único. A mesma ação competirá contra aquele em defesa de quem se causou o dano (art. 188, inciso I).\" D) Correta. Conforme os Arts. 929 e 930, CC, Rebeca tem direito de ser ressarcida por Felipe, o qual pode exercer seu direito de regresso em face da mãe de Eduardo.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_40","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":40,"discipline":"Direito Civil","topic":"Direito Reais - dos Limites Entre Prédios e do Direito de Tapagem","statement":"Thor, grande empresário do ramo de eletrônicos, gosta de cultivar, como hobby, alfaces no quintal de seu imóvel urbano. Contudo, o gato de sua vizinha Carol vive atravessando a cerca entre os imóveis, invadindo seu quintal e causando diversos danos à sua preciosa horta. A fim de evitar que tal evento se repita, o empresário deseja construir uma divisória entre os terrenos, porém não acha justo ter que arcar sozinho com os custos da construção. Diante desta situação, Thor procura você, como advogado(a), para saber sobre seus direitos.","alternative_a":"Thor poderá exigir a construção de tapumes especiais para impedir a passagem do gato, não sendo obrigado a concorrer com as despesas junto a Carol.","alternative_b":"Se Thor e Carol residissem em área rural, aquele não poderia exigir a construção de tapumes especiais para impedir a passagem do gato, visto que o legislador civilista foi omisso quanto ao direito de tapagem dos moradores rurais.","alternative_c":"Thor não poderá exigir a construção de tapumes especiais para impedir a passagem do gato, pois apenas quem provocou a necessidade da medida tem o direito de exigir sua construção.","alternative_d":"Thor poderá exigir a construção de tapumes especiais para impedir a passagem do gato, sendo obrigado a concorrer nas despesas junto à Carol.","correct_answer":"A","explanation":"A) Correta. A questão envolve problema de limite entre prédios e direito de tapagem, exigindo que o examinando tenha conhecimento acerca do §3º, art. 1.297 do CC, segundo o qual \"Art. 1.297, §3º, CC: A construção de tapumes especiais para impedir a passagem de animais de pequeno porte, ou para outro fim, pode ser exigida de quem provocou a necessidade deles, pelo proprietário, que não está obrigado a concorrer para as despesas.\" Dessa forma, Thor poderá exigir a construção e não será obrigado a concorrer com as despesas, as quais poderão ficar a cargo de Carol (causadora do incômodo). B) Errada. O caput do Artigo 1.297 do CC, traz a previsão tanto para área urbana quanto para área rural. \"Art. 1.297, CC: O proprietário tem direito a cercar, murar, valar ou tapar de qualquer modo o seu prédio, urbano ou rural, e pode constranger o seu confinante a proceder com ele à demarcação entre os dois prédios, a aviventar rumos apagados e a renovar marcos destruídos ou arruinados, repartindo-se proporcionalmente entre os interessados as respectivas despesas.\" C)Errada. Conforme o Art. 1.297, §3º do CC, Thor poderá exigir a construção e não será obrigado a concorrer com as despesas, as quais poderão ficar a cargo de Carol (causadora do incômodo). D)Errada. Conforme o Art. 1.297, §3º do CC, quem irá ficar responsável pelas despesas será a causadora da situação, nesse caso, Carol.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_41","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":41,"discipline":"Direito Civil","topic":"Obrigações - de Quem Deve Pagar","statement":"Peter, decidido a sair da casa de sua tia, alugou um apartamento de propriedade de Tony, por prazo determinado. Findo o contrato de locação, Steve, amigo de Peter e ciente da condição financeira precária deste, descobriu que o locatário não havia pagado os três últimos meses de aluguel. De pronto, o amigo procurou Tony para efetuar o pagamento da dívida em seu próprio nome sem avisar Peter. Algumas semanas depois, Steve viu, em um jornal de circulação municipal, que Peter ganhou o prêmio acumulado da loteria. Diante disso, o pagador narrou o ocorrido a Peter e exigiu o reembolso, porém este se negou a devolver o valor, sob o pretexto de que tinha meios para ilidir a obrigação. Acerca da situação, assinale a alternativa correta.","alternative_a":"Steve, como terceiro interessado, sub-roga-se, automaticamente, aos direitos do credor, com a transferência de todas as exceções e garantias que o credor primitivo detinha. Por conseguinte, Peter não pode negar-se a efetuar o pagamento, ainda que tivesse meios para ilidir a dívida.","alternative_b":"Steve, como terceiro não interessado e pagante em nome próprio, teria direito a ser reembolsado do que pagou, mas não de sub-rogar-se nos direitos do credor. Todavia, Peter, que desconhecia o pagamento feito por terceiro, eximir-se-á de reembolsar as despesas de Steve, desde que comprove que tinha meios para ilidir a sua dívida com Tony.","alternative_c":"Steve, como terceiro não interessado e pagante em nome próprio, não tem direito a nada, pois tal modalidade de pagamento é considerada um ato de mera liberalidade.","alternative_d":"Steve, como terceiro não interessado e pagante em nome próprio, sub-roga-se, automaticamente, nos direitos do credor, com a transferência de todas as exceções e garantias que o credor primitivo detinha. Por conseguinte, Peter não pode negar-se a efetuar o pagamento, ainda que tivesse meios para ilidir a dívida.","correct_answer":"B","explanation":"A) Errada. O Artigo 306 do CC estabelece que: “Art. 306, CC: o pagamento feito por terceiro, com desconhecimento ou oposição do devedor, não obriga este a ressarcir aquele que pagou, se o devedor tinha meios para exonerar-se do pagamento”. Assim, como o enunciado fala que Peter desconhecia o pagamento e que tinha meios para ilidi-lo, o jovem está desobrigado a efetuar o ressarcimento. 15 B) Correta. Alternativa de acordo com o Artigo 305 do CC: \"Art. 305, CC: O terceiro não interessado, que paga a dívida em seu próprio nome, tem direito a reembolsar-se do que pagar; mas não se sub-roga nos direitos do credor. Parágrafo único. Se pagar antes de vencida a dívida, só terá direito ao reembolso no vencimento.\" C) Errada. Steve tem direito a reembolsar-se do que pagar, conforme Artigo 305 do CC. D) Errada. Conforme dispõe o Artigo 305 do CC, Steve não se subroga nos direitos do credor.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_42","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":42,"discipline":"Direito Civil","topic":"Contratos - da Estipulação em Favor de Terceiro","statement":"Estando a poucos dias do dia dos namorados, Bruce decide fazer uma surpresa para sua companheira Natasha. Após visitar a floricultura local e celebrar contrato de compra e venda de um buquê de flores e uma maravilhosa cesta de café da manhã, Bruce combinou com Yelena, proprietária da loja, que ela faria a entrega dos itens à Natasha no dia 12 de junho, às 8 horas da manhã. Sabendo que Natasha não é parte no contrato e conhecendo o que a legislação civil dispõe sobre estipulação contratual em favor de terceiro, assinale a alternativa incorreta.","alternative_a":"Se o direito de reclamar a entrega dos bens comprados for atribuído à Natasha, Bruce não poderá exonerar Yelena da obrigação.","alternative_b":"Em conformidade com o princípio da relatividade contratual, o legislador civilista apresentou exceções à máxima de que “o contrato apenas gera efeitos inter partes”, ao permitir, por exemplo, que terceiro se beneficie de contrato alheio.","alternative_c":"Caso Bruce reserve-se ao direito de substituir Natasha, a substituição ocorrerá apenas por ato entre vivos.","alternative_d":"É permitido que Bruce e Natasha exijam o cumprimento da obrigação, ficando a última, todavia, sujeita às condições e normas do contrato, se a ele anuir, e desde que o estipulante não substitua o terceiro ali indicado.","correct_answer":"C","explanation":"Atenção: A questão pede a alternativa incorreta A) Correta. Alternativa de acordo com o Artigo 437 do CC: \"Art. 437, CC: Se ao terceiro, em favor de quem se fez o contrato, se deixar o direito de reclamar-lhe a execução, não poderá o estipulante exonerar o devedor.\" B) Correta. Alternativa está correta, ao terceiro (NATASHA), em favor de quem se estipulou a obrigação, também é permitido exigi-la. C) Errada. A alternativa está errada por não compreender a possibilidade de substituição por disposição de última vontade, conforme o parágrafo único do Artigo 438, CC: \"Art. 438, CC: O estipulante pode reservar-se o direito de substituir o terceiro designado no contrato, independentemente da sua anuência e da do outro contratante. Parágrafo único. A substituição pode ser feita por ato entre vivos ou por disposição de última vontade.\" D) Correta. Alternativa está de acordo com o Artigo 436 do CC: \"Art. 436, CC: O que estipula em favor de terceiro pode exigir o cumprimento da obrigação. Parágrafo único. Ao terceiro, em favor de quem se estipulou a obrigação, também é permitido exigi-la, ficando, todavia, sujeito às condições e normas do contrato, se a ele anuir, e o estipulante não o inovar nos termos do art. 438.\" ESTATUTO DA CRIANÇA E DO ADOLESCENTE","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_43","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":43,"discipline":"ECA","topic":"Ato Infracional","statement":"Acerca do Estatuto da Criança e do Adolescente assinale a alternativa correta:","alternative_a":"Um adolescente menor de 18 anos que praticou um ato infracional, ao completar 18 anos não poderá mais submeter-se às regras do Estatuto da Criança e do Adolescente, devendo este ser submetido ao Código Penal.","alternative_b":"A aplicação de medidas socioeducativas ao adolescente pela prática de ato infracional é da competência do juiz ou do próprio Conselho Tutelar.","alternative_c":"O ato infracional análogo ao tráfico de drogas, por si só, não conduz obrigatoriamente à imposição de medida socioeducativa de internação do adolescente.","alternative_d":"No procedimento para aplicação de medida socioeducativa, é válido a desistência de outras provas em face da confissão do adolescente.","correct_answer":"C","explanation":"A) Errada. A súmula 605 do STJ dispõe que “a superveniência da maioridade penal não interfere na apuração de ato infracional nem na aplicabilidade de medida socioeducativa em curso, inclusive na liberdade assistida, enquanto não atingida a idade de 21 anos.” Portanto, o jovem adulto é aquele que cometeu o ato quando ainda tinha menos de 18 anos, mas completou a maioridade penal e deve continuar cumprindo a medida até os 21 anos de idade, aplicando-se o regramento do ECA. B) Errada. Trata-se de competência exclusiva do Juiz. Súmula 108 do STJ - A competência para aplicação de medidas socioeducativas aos adolescentes, pela prática de ato infracional, é exclusiva do juiz. C) Correta. A prática de ato infracional equiparado ao delito de tráfico de entorpecentes, em virtude da sua gravidade abstrata, por si só, não autoriza a segregação dos menores. Súmula 492 do STJ - O ato infracional análogo ao tráfico de drogas, por si só, não conduz obrigatoriamente à imposição de medida socioeducativa de internação do adolescente. D) Errada. Conforme a Súmula 342 do STJ “no procedimento para aplicação de medida socioeducativa, é nula a desistência de outras provas em face da confissão do adolescente”. #Em resumo: A homologação da desistência manifestada pelas partes de produzirem provas por ocasião da audiência de apresentação, com a aplicação da medida sócio-educativa de internação, antes mesmo de iniciada a fase instrutória, com base apenas na confissão do menor infrator, constitui constrangimento ilegal, tendo em vista que viola os princípios constitucionais relativos ao devido processo legal e à ampla defesa, sem falar que os esclarecimento dos fatos e a busca da verdade real interessam também ao Estado. (HC 42382 SP, Rel. Ministro ARNALDO ESTEVES LIMA, QUINTA TURMA, julgado em 02/06/2005, DJ 22/08/2005, p. 321). 16","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_44","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":44,"discipline":"ECA","topic":"Medidas Socioeducativas - Internação","statement":"De acordo com o Estatuto da Criança e do Adolescente são direitos do adolescente privado de liberdade, exceto:","alternative_a":"Encontrar-se pessoalmente com o representante do Ministério Público.","alternative_b":"O adolescente pode peticionar, inclusive, reclamando do estabelecimento educacional em que está cumprindo a medida socioeducativa, para qualquer autoridade.","alternative_c":"Ser informado de sua situação processual sempre que solicitada.","alternative_d":"Permanecer internado na localidade em que praticar o ato infracional.","correct_answer":"D","explanation":"A questão pede para assinalar a exceção (o que não constitui direito do adolescente privado de liberdade), ou seja, a alternativa incorreta! A) Correta. É direito do adolescente privado de liberdade encontrar-se pessoalmente com o representante do Ministério Público. Art. 124. ECA. São direitos do adolescente privado de liberdade, entre outros, os seguintes: I - entrevistar-se pessoalmente com o representante do Ministério Público; B) Correta. É direito do adolescente privado de liberdade peticionar, inclusive, reclamar do estabelecimento educacional em que está cumprindo a medida socioeducativa, para qualquer autoridade. Art. 124. ECA. São direitos do adolescente privado de liberdade, entre outros, os seguintes: II - peticionar diretamente a qualquer autoridade; C) Correta. É direito do adolescente privado de liberdade ser informado de sua situação processual sempre que solicitada. Art. 124. ECA. São direitos do adolescente privado de liberdade, entre outros, os seguintes: IV - ser informado de sua situação processual, sempre que solicitada; D) Errada. Não é direito do adolescente permanecer internado na localidade em que praticar o ato infracional. Em regra, a medida socioeducativa será cumprida no domicílio de seus pais ou responsável, mesmo que tenha praticado o delito em outro local, devido ao direito da convivência familiar. DIREITO DO CONSUMIDOR","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_45","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":45,"discipline":"Direito do Consumidor","topic":"Direitos Básicos do Consumidor","statement":"Isabella adquiriu um anel por meio de compra pelo telefone, produto que era mostrado ao vivo pelo canal de televisão. Ao receber o anel, frustrou-se por, esteticamente, não ter atendido às suas expectativas. Nesse caso, Isabella poderá:","alternative_a":"exercitar o direito de arrependimento em até trinta dias, mas os valores restituídos não serão monetariamente atualizados, por não haver defeito no produto;","alternative_b":"convencionar a devolução do produto, não estando a fornecedora obrigada a aceitar a devolução, dada a inexistência de defeito no produto;","alternative_c":"exigir, no prazo de vinte dias, a restituição da quantia paga, monetariamente atualizada, sem prejuízo de eventuais perdas e danos.","alternative_d":"desistir do contrato, no prazo de sete dias a contar do ato de recebimento do produto;","correct_answer":"D","explanation":"A) Errada. O direito de arrependimento deve ser exercitado no prazo de 7 dias e não 30. B) Errada. Não se trata de devolução e questionamento de existência ou não de defeito no produto. C) Errada. Trata-se de simples exercício do direito de arrependimento com a devolução do valor pago. D) Correta. Conforme o art. 49 do CDC. Observe: Art. 49 do CDC O consumidor pode desistir do contrato, no prazo de 7 dias a contar de sua assinatura ou do ato de recebimento do produto ou serviço, sempre que a contratação de fornecimento de produtos e serviços ocorrer fora do estabelecimento comercial, especialmente por telefone ou a domicílio. Parágrafo único. Se o consumidor exercitar o direito de arrependimento previsto neste artigo, os valores eventualmente pagos, a qualquer título, durante o prazo de reflexão, serão devolvidos, de imediato, monetariamente atualizados.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_46","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":46,"discipline":"Direito do Consumidor","topic":"Direitos Básicos do Consumidor","statement":"No fornecimento de crédito e na venda a prazo, o prazo de validade da oferta deverá ser de, no mínimo:","alternative_a":"1 dia.","alternative_b":"2 dias.","alternative_c":"5 dias.","alternative_d":"7 dias.","correct_answer":"B","explanation":"A) Errada. De acordo com o CDC é de 2 dias. B) Correta. Conforme o art. 54-B, inciso III, do CDC: “No fornecimento de crédito e na venda a prazo, além das informações obrigatórias previstas no art. 52 deste Código e na legislação aplicável à matéria, o fornecedor ou o intermediário deverá informar o consumidor, prévia e adequadamente, no momento da oferta, sobre: III - o montante das prestações e o prazo de validade da oferta, que deve ser, no mínimo, de 2 (dois) dias”. C) Errada. De acordo com o CDC é de 2 dias. D) Errada. De acordo com o CDC é de 2 dias. DIREITO EMPRESARIAL","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_47","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":47,"discipline":"Direito Empresarial","topic":"Direito de Empresa - Conceitos","statement":"Relativamente ao direito empresarial, assinale a alternativa incorreta.","alternative_a":"Conceitua-se empresário como o sujeito de direito que desenvolve atividade econômica organizada para a produção ou para a circulação de bens ou de serviços.","alternative_b":"Quanto à responsabilidade civil de sócio de sociedade em nome coletivo e de sócio comanditado de sociedade em comandita simples, ambos os sócios mencionados são responsáveis, subsidiária, solidária e ilimitadamente, pelas obrigações sociais.","alternative_c":"Em se tratando de sociedade limitada, as deliberações dos sócios serão realizadas em assembleia ou reunião, no entanto estas tornar-se-ão dispensáveis se todos os sócios decidirem, por escrito, sobre a matéria que seria objeto delas.","alternative_d":"É permitido a um sócio de uma sociedade não empresária limitada integralizar, com prestação de serviços, as quotas por ele subscritas.","correct_answer":"D","explanation":"Atenção: A questão pede a alternativa incorreta. A) Correta. Está em conformidade com o Artigo 966 do CC: “Art. 966, CC: Considera-se empresário quem exerce profissionalmente atividade econômica organizada para a produção ou a circulação de bens ou de serviços”. Lembrar aqui que esse conceito é sobre empresário e não empresa. B) Correta. Pode ser encontrada no Código Civil, em seu art. 1.039 acerca das sociedades em nome coletivo, respondendo todos os sócios, solidária e ilimitadamente, pelas obrigações sociais, bem como, 17 em seu art. 1.045, acerca da sociedade em comandita simples, os comanditados, pessoas físicas, responsáveis solidária e ilimitadamente pelas obrigações sociais; enquanto os comanditários, obrigados somente pelo valor de sua quota. C) Correta. Consta no Artigo 1.072, §3º do CC: “Art. 1.072, §3º, CC: a reunião ou a assembleia tornam-se dispensáveis quando todos os sócios decidirem, por escrito, sobre a matéria que seria objeto delas”. D) Errada. Segundo o art. 1.055, § 2º, CC é vedada a contribuição que consista em prestação de serviços nas sociedades limitadas. Vale lembrar que na sociedade simples pura é possível que o sócio contribua com prestação de serviços, conforme o teor do art. 997, V, CC.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_48","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":48,"discipline":"Direito Empresarial","topic":"Falência","statement":"De acordo com o STJ, o ato decisório que decreta a falência possui natureza de sentença constitutiva, pois sua prolação faz operar a dissolução da sociedade empresária, conduzindo à inauguração de um regime jurídico específico. Sobre a Lei 11.101/2005, assinale a alternativa correta.","alternative_a":"O juízo indivisível da falência é aquele competente para conhecer todas as ações sobre bens, interesses e negócios do falido, inclusive causas trabalhistas e fiscais.","alternative_b":"A decisão que decreta a falência é recorrível por agravo, bem como contra sentença que julga a improcedência do pedido de falência.","alternative_c":"A pessoa jurídica constituída sob a forma de cooperativa de consumo poderá beneficiar-se do tratamento jurídico diferenciado e favorecido às empresas de pequeno porte e às pequenas empresas, inclusive para pleitear plano especial de recuperação judicial.","alternative_d":"O juiz poderá decretar a falência durante o processo de recuperação judicial por deliberação da assembleia-geral de credores: pela não apresentação, pelo devedor, do plano de recuperação em 60 dias; quando houver sido rejeitado o plano de recuperação judicial proposto pelos credores; por descumprimento de qualquer obrigação assumida no plano de recuperação; quando identificado o esvaziamento patrimonial da devedora que implique liquidação substancial da empresa, em prejuízo de credores não sujeitos à recuperação judicial, inclusive às Fazendas Públicas, entre outros.","correct_answer":"D","explanation":"A) Errada. Embora o juízo universal da falência seja a regra, ele comporta exceções, conforme o Artigo 76 da lei 11.101/05 supracitada: “Art. 76, Lei 11.101/05: O juízo da falência é indivisível e competente para conhecer todas as ações sobre bens, interesses e negócios do falido, ressalvadas as causas trabalhistas, fiscais e aquelas não reguladas nesta Lei em que o falido figurar como autor ou litisconsorte ativo”. B) Errada. Não há extinção do processo na falência, logo se trata de decisão interlocutória, cabendo o agravo. No entanto, na improcedência do pedido há extinção do processo em primeira instância, portanto o recurso cabível é a apelação. Essas disposições constam no Artigo 100 da Lei 11.101/05: “Art. 100, Lei 11.101/05: Da decisão que decreta a falência cabe agravo, e da sentença que julga a improcedência do pedido cabe apelação”. O fato da decisão ser constitutiva ou declaratória em nada interfere na extinção do processo. C) Errada. Embora se beneficie com o tratamento especial, de acordo com a LC 123/2006, em seu Artigo 3º §4º, “Art. 3º, §4º, LC 123/2006: não poderá se beneficiar do tratamento jurídico diferenciado previsto nesta Lei Complementar, incluído o regime de que trata o art. 12 desta Lei Complementar, para nenhum efeito legal, a pessoa jurídica: VI - constituída sob a forma de cooperativas, salvo as de consumo;” Não podem pedir recuperação judicial, sob qualquer forma, pela vedação contida no inciso II do Artigo 2º. Conforme o Artigo 6º, §º13, também não se sujeitam aos efeitos da recuperação judicial os contratos e obrigações decorrentes dos atos cooperativos praticados pelas sociedades cooperativas com seus cooperados, na forma do art. 79 da Lei nº 5.764, de 16 de dezembro de 1971, consequentemente. D) Correta. Apresenta algumas das hipóteses de convolação de recuperação judicial em falência do Artigo 73 da Lei 11.101/05, que diz: “Art. 73, Lei 11.101/05: o juiz decretará a falência durante o processo de recuperação judicial: I – por deliberação da assembleia-geral de credores, na forma do art. 42 desta Lei; II – pela não apresentação, pelo devedor, do plano de recuperação no prazo do art. 53 desta Lei; III - quando não aplicado o disposto nos §§ 4º, 5º e 6º do art. 56 desta Lei, ou rejeitado o plano de recuperação judicial proposto pelos credores, nos termos do § 7º do art. 56 e do art. 58-A desta Lei; IV – por descumprimento de qualquer obrigação assumida no plano de recuperação, na forma do § 1º do art. 61 desta Lei. V - por descumprimento dos parcelamentos referidos no art. 68 desta Lei ou da transação prevista no art. 10-C da Lei nº 10.522, de 19 de julho de 2002; e VI - quando identificado o esvaziamento patrimonial da devedora que implique liquidação substancial da empresa, em prejuízo de credores não sujeitos à recuperação judicial, inclusive as Fazendas Públicas.”","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_49","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":49,"discipline":"Direito Empresarial","topic":"Lei de Registro de Marcas e Patentes","statement":"Em ação cominatória de abstenção do uso de marca cumulada com danos morais e materiais, o mérito versou sobre a proteção às expressões e sinais empregados apenas como meio de propaganda. Em razão das disposições legais relativas ao registro de marcas, é correto afirmar que:","alternative_a":"São registráveis como marca as expressões ou sinais empregados apenas como meio de propaganda quando fizerem parte do estabelecimento do empresário como elementos incorpóreos distintivos.","alternative_b":"Não são registráveis como marca as expressões ou sinais empregados apenas como meio de propaganda, porque eles já são objeto de registro junto com o desenho industrial no Instituto Nacional da Propriedade Industrial (INPI).","alternative_c":"São registráveis como marca as expressões ou sinais empregados apenas como meio de propaganda, desde que o requerente comprove sua utilização ininterrupta por pelo menos dez anos;","alternative_d":"Não são registráveis como marca as expressões ou sinais empregados apenas como meio de propaganda. Além disso, tais elementos distintivos são insuscetíveis de registro no âmbito da propriedade industrial.","correct_answer":"D","explanation":"A) Errada. Conforme o Artigo 124, VII, da Lei 9.279/1996 \"Art. 124, Lei 9.279/1996: Não são registráveis como marca: VII - sinal ou expressão empregada apenas como meio de propaganda;\" B) Errada. Conforme o Artigo 95 da Lei 9.279/1996: \"Art. 95, Lei 9.279/1996: Considera-se desenho industrial a forma plástica ornamental de um objeto ou o conjunto ornamental de linhas e cores que 18 possa ser aplicado a um produto, proporcionando resultado visual novo e original na sua configuração externa e que possa servir de tipo de fabricação industrial.\" Ou seja, não cabe registro de sinal ou expressão de propaganda como desenho industrial. C) Errada. Sinais empregados apenas como meio de propaganda, não são registráveis como marca, conforme o Artigo 124 da Lei 9.279/1996. D) Correta. Alternativa de acordo com o Artigo 124 da Lei 9.279/1996.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_50","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":50,"discipline":"Direito Empresarial","topic":"Contratos Mercantis","statement":"No que tange aos contratos mercantis específicos, assinale a opção correta.","alternative_a":"Salvo expressa previsão contratual em contrário, desde que atendidas as condições legais, o locatário de contrato de locação mercantil goza da prerrogativa legal de possibilidade de sua renovação, independentemente da vontade do locador.","alternative_b":"Em contrato de compra e venda mercantil, a fixação do preço não pode ser deixada ao arbítrio exclusivo de uma das partes nem de terceiro, sob pena de nulidade.","alternative_c":"Ainda que a cláusula del credere conste no contrato de comissão mercantil, os riscos como os de vício na coisa vendida ou de evicção correm por conta do comitente.","alternative_d":"O transportador responde pelos danos causados às pessoas transportadas, salvo por motivo de força maior ou por culpa exclusiva de terceiro.","correct_answer":"C","explanation":"A) Errada. De acordo com o Artigo 45 da Lei de Locações (Lei 8.245/1991), são nulas de pleno direito as cláusulas do contrato de locação que visem a elidir os objetivos da presente lei, notadamente as que proíbam a prorrogação prevista no art. 47, ou que afastem o direito à renovação, na hipótese do art. 51, ou que imponham obrigações pecuniárias para tanto. Sobre a renovação, para entender os seus requisitos, é importante a leitura do Artigo 51: “Art. 51, Lei 8.245/1991: Nas locações de imóveis destinados ao comércio, o locatário terá direito a renovação do contrato, por igual prazo, desde que, cumulativamente: I - o contrato a renovar tenha sido celebrado por escrito e com prazo determinado; II - o prazo mínimo do contrato a renovar ou a soma dos prazos ininterruptos dos contratos escritos seja de cinco anos; III - o locatário esteja explorando seu comércio, no mesmo ramo, pelo prazo mínimo e ininterrupto de três anos.\" Incorreta a letra A pelo termo “salvo expressa previsão contratual em contrário”, pois tal cláusula, se proibisse a renovação, seria nula. B) Errada. De acordo com o Artigo 485 do CC, a fixação do preço pode ser deixada ao arbítrio de terceiro que os contratantes logo designarem ou prometerem designar. Se esse terceiro não aceitar a incumbência, o contrato ficará sem efeito, salvo quando os contratantes escolherem outra pessoa. Com isso, podem deixar a incumbência para terceiro, mas não para uma das partes, conforme o texto do Artigo 489, CC que diz: “Art. 489, CC: nulo é o contrato de compra e venda, quando se deixa ao arbítrio exclusivo de uma das partes a fixação do preço”. Incorreta a letra B quanto à fixação de preço por terceiro. C) Correta. Cabe ao comissário levar a efeito as negociações atendendo aos interesses do comitente, sendo, por esta razão, empreendidas por conta e risco deste último, ou seja, todos os riscos comerciais do negócio cabem, em princípio, ao comitente. A cláusula “del credere” corresponde ao instituto ou previsão da parte contratante ou representada descontar os valores de comissões ou vendas do representante comercial na hipótese da venda ou da transação ser cancelada ou desfeita, de forma que ainda correm por conta do comitente os demais riscos, como o de vício na coisa vendida ou evicção. Observe a redação do Artigo 698, CC: “Art. 698, CC: Se do contrato de comissão constar a cláusula del credere, responderá o comissário solidariamente com as pessoas com que houver tratado em nome do comitente, caso em que, salvo estipulação em contrário, o comissário tem direito a remuneração mais elevada, para compensar o ônus assumido”. D) Errada. De acordo com o art. 734, CC, o transportador responde pelos danos causados às pessoas transportadas e suas bagagens, salvo motivo de força maior, sendo nula qualquer cláusula excludente da responsabilidade, sendo lícito ao transportador exigir a declaração do valor da bagagem a fim de fixar o limite da indenização. Sobre a culpa exclusiva de terceiro, o Artigo 735 do CC diz que: “Art. 735 CC: a responsabilidade contratual do transportador por acidente com o passageiro não é elidida por culpa de terceiro, contra o qual tem ação regressiva” PROCESSO CIVIL","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_51","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":51,"discipline":"Direito Processual Civil","topic":"Atos Processuais - dos Prazos","statement":"Diogo, na condição de autor, distribuiu processo judicial em face do Banco Crédito Fácil pleiteando a condenação da empresa ao pagamento do valor de R$20.000,00 (vinte mil reais) por danos morais. Após o andamento de todas as fases, (contestação, réplica, audiência de instrução) houve sentença judicial que julgou parcialmente procedente os pedidos do autor, fixando o valor em R$10.000 (dez mil reais). Tendo em vista que as partes ainda não foram intimadas da publicação da sentença, assinale a opção correta.","alternative_a":"Ambas as partes poderão recorrer por meio de apelação somente após a intimação da sentença.","alternative_b":"Apenas o banco poderá recorrer, mas deverá aguardar a intimação, ainda que já tenha tomado ciência da sentença.","alternative_c":"Ambas as partes poderão recorrer, bem como poderão protocolar a apelação, ainda que não tenham sido intimadas oficialmente.","alternative_d":"Não é possível que as partes recorram antes de realizada a intimação.","correct_answer":"C","explanation":"A) Errada. Conforme o Artigo 218, §4º do CPC, as partes podem praticar atos antes do termo inicial do prazo, de modo que não existe a obrigação de aguardar a intimação acerca do ato. \"Art. 218, CPC: Os atos processuais serão realizados nos prazos prescritos em lei. 19 §4º Será considerado tempestivo o ato praticado antes do termo inicial do prazo.\" Desse modo, após tomar ciência da sentença judicial (ou qualquer outro ato judicial), a parte que desejar impugná-la poderá agir de imediato. B) Errada. Tendo em vista que o pedido foi parcialmente procedente, verifica-se a sucumbência recíproca, fato que permite que cada parte venha a impugnar a decisão judicial através do recurso cabível. Além disso, não existe a obrigação de aguardar a intimação acerca do ato, conforme o Artigo 218, §4º do CPC. C) Correta. Alternativa de acordo com o Artigo 218, §4º do CPC. D) Errada. As partes podem praticar atos antes do termo inicial do prazo, de modo que não existe a obrigação de aguardar a intimação acerca do ato. Desse modo, após tomar ciência da sentença judicial (ou qualquer outro ato judicial), a parte que desejar impugná-la poderá agir de imediato.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_52","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":52,"discipline":"Direito Processual Civil","topic":"Recursos - Agravo Interno","statement":"Raphael ajuizou demanda em face de plano de saúde, pleiteando, em sede liminar, que o juízo determinasse a internação e a realização de cirurgia após ter recebido negativa de atendimento. O magistrado negou o pedido de antecipação da tutela, de modo que, ao ser intimado, o autor recorreu através de agravo de instrumento, onde pleiteou a antecipação dos efeitos do recurso para que o relator determinasse a internação e a realização da cirurgia. Recebido o recurso no tribunal, o desembargador relator negou provimento ao recurso sob a alegação de que este fere súmula do próprio tribunal. Acerca do tema, decisão do desembargador relator, indique qual conduta o recorrente poderá tomar para ter o seu recurso apreciado, sabendo que não há omissão, contradição, erro material, tampouco obscuridade na decisão.","alternative_a":"O recorrente poderá utilizar- se do recurso especial para levar a matéria ao Superior Tribunal de Justiça","alternative_b":"Raphael deverá utilizar o recurso de agravo interno, tendo em vista que este é o recurso cabível contra as decisões de desembargador relator.","alternative_c":"O recurso cabível neste caso será a apelação, pois a decisão assemelha-se a uma sentença.","alternative_d":"O recurso cabível será recurso extraordinário, por se tratar da vida do autor, tema que recebe proteção constitucional.","correct_answer":"B","explanation":"A) Errada. O Código de Processo Civil é expresso ao prever que o recurso cabível contra as decisões do desembargador relator será o agravo interno. Nesse sentido, lê-se o Artigo 1.021 do CPC: \"Art. 1.021, CPC: Contra decisão proferida pelo relator caberá agravo interno para o respectivo órgão colegiado, observadas, quanto ao processamento, as regras do regimento interno do tribunal. §1º Na petição de agravo interno, o recorrente impugnará especificadamente os fundamentos da decisão agravada. §2º O agravo será dirigido ao relator, que intimará o agravado para manifestar-se sobre o recurso no prazo de 15 (quinze) dias, ao final do qual, não havendo retratação, o relator levá-lo-á a julgamento pelo órgão colegiado, com inclusão em pauta. §3º É vedado ao relator limitar-se à reprodução dos fundamentos da decisão agravada para julgar improcedente o agravo interno. §4º Quando o agravo interno for declarado manifestamente inadmissível ou improcedente em votação unânime, o órgão colegiado, em decisão fundamentada, condenará o agravante a pagar ao agravado multa fixada entre um e cinco por cento do valor atualizado da causa. §5º A interposição de qualquer outro recurso está condicionada ao depósito prévio do valor da multa prevista no § 4º, à exceção da Fazenda Pública e do beneficiário de gratuidade da justiça, que farão o pagamento ao final.\" Desse modo, tomando ciência do julgamento desfavorável pelo desembargador relator, o interessado deverá manejar o agravo interno de modo a levar ao órgão colegiado o debate acerca da matéria impugnada. Além disso, antes de subir ao STJ, a questão precisa ser resolvida em sede local (no Tribunal local). Assim, como o recurso sequer foi decidido de forma colegiada, precisa antes passar pelo julgamento da turma. B) Correta. Alternativa de acordo com o Artigo 1.021 do CPC, vide comentário da alternativa A. C) Errada. Tomando ciência do julgamento desfavorável pelo desembargador relator, o interessado deverá manejar o agravo interno de modo a levar ao órgão colegiado o debate acerca da matéria impugnada. Nessa situação a parte, o recorrente deverá impugnar, especificamente, a decisão do desembargador e apontar eventual erro de julgamento. D) Errada. O recurso cabível será o agravo interno conforme o Artigo 1.021 do CPC.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_53","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":53,"discipline":"Direito Processual Civil","topic":"Incidente de Desconsideração da Personalidade Jurídica","statement":"A pessoa jurídica Irmãos à Obra foi demandada por Ana Clara que, pretendendo atingir os bens dos sócios, por vislumbrar a ocorrência de confusão patrimonial, deverá instaurar incidente de desconsideração da personalidade jurídica que:","alternative_a":"Deve ser instaurado, ainda que o pleito conste da petição inicial. Ademais, suspende-se o processo por decisão interlocutória, até que seja decidido.","alternative_b":"É decidido por sentença.","alternative_c":"É cabível apenas no cumprimento de sentença e se restarem infrutíferas as tentativas de penhora de bens da sociedade empresária.","alternative_d":"Suspende o processo, salvo se a desconsideração houver sido pleiteada na petição inicial.","correct_answer":"D","explanation":"A) Errada. O Artigo 134, §2º do CPC dispõe que não é necessária a instauração de incidente quando a desconsideração é requerida na petição inicial, nos seguintes termos: “Art. 134, §2º, CPC: Dispensa-se a instauração do incidente se a desconsideração da personalidade jurídica for requerida na petição inicial, hipótese em que será citado o sócio ou a pessoa jurídica”. B) Errada. O incidente não é resolvido por sentença, mas por decisão interlocutória. Dispõe o Artigo 136 do CPC, ora transcrito: “Art. 136, CPC: Concluída a instrução, se necessária, o incidente será resolvido por decisão interlocutória”. C) Errada. O incidente de desconsideração é cabível em todas as fases do processo, não apenas no cumprimento de sentença. Assim dispõe o Artigo 134 do CPC, in verbis: 20 “Art. 134, CPC: O incidente de desconsideração é cabível em todas as fases do processo de conhecimento, no cumprimento de sentença e na execução fundada em título executivo extrajudicial”. D) Correta. A instauração do incidente suspende o processo. Tal suspensão apenas não ocorrerá se a desconsideração for pleiteada na petição inicial. Nesses termos, dispõe o Artigo. 134, § 3º do CPC: “Art. 134, § 3º, CPC: A instauração do incidente suspenderá o processo, salvo na hipótese do § 2º” (ou seja, quando é requerida na petição inicial).","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_54","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":54,"discipline":"Direito Processual Civil","topic":"Procedimento Comum - Petição Inicial","statement":"Day, em decorrência de diversos problemas conjugais, decidiu divorciar- se de Rodrigo Vai. Assim, em virtude da resistência de Rodrigo, Day precisou propor ação de divórcio litigioso. Distribuída a ação, o juiz determinou a emenda da petição inicial, ante a ausência de cópia da certidão de casamento. Diante da situação hipotética narrada, assinale a afirmativa correta.","alternative_a":"Ausente o documento indispensável à propositura da ação, a petição inicial deve ser indeferida de plano.","alternative_b":"Ausente o documento indispensável à propositura da ação, a parte autora deve ser intimada para emendar ou completar a inicial no prazo de 5 (cinco) dias.","alternative_c":"Ausente o documento indispensável à propositura da ação, a parte autora deve ser intimada para emendar ou completar a inicial no prazo de 15 (quinze) dias.","alternative_d":"Ausente o documento indispensável à propositura da ação, resta configurada a hipótese de improcedência liminar do pedido.","correct_answer":"C","explanation":"A) Errada. Ausente algum documento considerado indispensável à propositura da ação, o juiz determinará que o autor a complete ou a emende, nos termos dos arts. 320 e 321 do CPC. Ademais, caso indeferisse de plano, violaria, além dos dispositivos mencionados, os princípios da primazia da resolução do mérito e da cooperação (art. 6º do CPC). B) Errada. O prazo da alternativa a torna incorreta, porquanto o prazo não é de 05 (cinco) dias, mas de 15 (quinze) dias, vide art. 321 do CPC. C) Correta. “Art. 321, CPC: O juiz, ao verificar que a petição inicial não preenche os requisitos dos arts. 319 e 320 ou que apresenta defeitos e irregularidades capazes de dificultar o julgamento de mérito, determinará que o autor, no prazo de 15 (quinze) dias, a emende ou a complete, indicando com precisão o que deve ser corrigido ou completado”. D) Errada. Não é caso de improcedência liminar do pedido, uma vez que não se amolda às hipóteses de tal instituto, que se encontra no Artigo 332 do CPC, in verbis: “Art. 332, CPC: Nas causas que dispensem a fase instrutória, o juiz, independentemente da citação do réu, julgará liminarmente improcedente o pedido que contrariar: I - enunciado de súmula do Supremo Tribunal Federal ou do Superior Tribunal de Justiça; II - acórdão proferido pelo Supremo Tribunal Federal ou pelo Superior Tribunal de Justiça em julgamento de recursos repetitivos; III - entendimento firmado em incidente de resolução de demandas repetitivas ou de assunção de competência; IV - enunciado de súmula de tribunal de justiça sobre direito local. § 1º O juiz também poderá julgar liminarmente improcedente o pedido se verificar, desde logo, a ocorrência de decadência ou de prescrição”.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_55","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":55,"discipline":"Direito Processual Civil","topic":"Litisconsórcio","statement":"Zé Felipe e Virgínia, em conjunto e solidariamente, firmaram compromisso de compra e venda para aquisição de um imóvel de Maria Alice. Em razão da falta de pagamento, a vendedora pretende resolver o negócio, propondo demanda, com esta finalidade, em face dos compradores. A partir dessa narrativa, temos:","alternative_a":"Litisconsórcio passivo, necessário e simples.","alternative_b":"Litisconsórcio passivo, necessário e unitário.","alternative_c":"Litisconsórcio passivo, facultativo e unitário.","alternative_d":"Litisconsórcio passivo, facultativo e simples.","correct_answer":"C","explanation":"A) Errada. O litisconsórcio é passivo (mais de um réu), mas não é necessário. “Art. 114, CPC: O litisconsórcio será necessário por disposição de lei ou quando, pela natureza da relação jurídica controvertida, a eficácia da sentença depender da citação de todos que devam ser litisconsortes” Tendo em vista que se trata de devedores solidários, podendo qualquer um deles ser demandado pelo todo, sem ser necessária a presença do outro na lide. B) Errada. Vide comentários da letra “A”. C) Correta. O litisconsórcio é passivo (mais de um réu), é facultativo (tendo em vista que os devedores são solidários, podendo qualquer um deles ser demandado pelo todo, sem que seja necessária a presença do outro devedor solidário no processo), bem como é unitário, porquanto o resultado atingirá a todos da mesma maneira (art. 116, do CPC). Perceba que o litisconsórcio unitário ocorre quando há incindibilidade da relação jurídica, ou seja, todos os litisconsortes vão sofrer, da mesma maneira, os efeitos da decisão (“todos perdem ou todos ganham”). D) Errada. O litisconsórcio é passivo e é facultativo, mas não é simples, porque no litisconsórcio simples há cindibilidade dos efeitos da decisão, fato que não ocorre no caso.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_56","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":56,"discipline":"Direito Processual Civil","topic":"Da Execução por Quantia Certa","statement":"A execução pode ser instaurada caso o devedor não satisfaça a obrigação certa, líquida e exigível consubstanciada em título executivo. Desse modo, Felipe, observando contrato assinado pelas partes e duas testemunhas (título executivo extrajudicial), iniciou execução civil em face de João, seu inquilino, em razão do descumprimento da obrigação de pagar, pleiteando, nessa oportunidade, o pagamento de R$6.000,00 (seis mil reais) referente a três meses de aluguel, fixando de pronto os honorários advocatícios em dez por cento. Acerca do tema, é correto dizer que:","alternative_a":"Se João pagar, integralmente, o valor devido no prazo de três dias, os honorários advocatícios serão reduzidos pela metade.","alternative_b":"João deverá pagar a dívida no prazo de três dias, hipótese na qual os honorários serão dispensados.","alternative_c":"João poderá pagar a dívida no prazo de 15 dias, sob pena de multa e honorários de 10% cada.","alternative_d":"João poderá pagar a dívida no prazo de 15 dias úteis, hipótese em que os honorários e a multa serão reduzidas pela metade.","correct_answer":"A","explanation":"A) Correta. Conforme o Artigo 827 do CPC: \"Art. 827, CPC: Ao despachar a inicial, o juiz fixará, de plano, os honorários advocatícios de dez por cento, a serem pagos pelo executado. §1º No caso de integral pagamento no prazo de 3 (três) dias, o valor dos honorários advocatícios será reduzido pela metade.\" Desse modo, uma vez efetuado o pagamento integral do débito, João terá um benefício na condenação em honorários. A doutrina chama esse benefício de 21 sanção premial e serve como um estímulo ao adimplemento das obrigações. B) Errada. Caso João efetue o pagamento do débito no prazo de 3 dias, os honorários serão reduzidos pela metade e não dispensados. C) Errada. O valor dos honorários serão de 10% conforme Artigo 827 do CPC. D) Errada. Os honorários serão reduzidos pela metade no caso do pagamento do débito ocorrer no prazo de 3 dias. DIREITO PENAL","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_57","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":57,"discipline":"Direito Penal","topic":"Lei de Tóxicos (Lei 11.343/06) e Estatuto do Desarmamento (Lei 10.826/06)","statement":"A autoridade policial do Ceará, delegacia especializada no combate ao tráfico de drogas, após apurar, em escuta telefônica devidamente autorizada, que uma certa quantidade de drogas seria introduzida no presídio por ordem de Naruto, agente penitenciário, obteve, do juízo competente, mandado de busca e apreensão, tendo como alvo a residência de Sakura, mulher do detento Sasuke. Durante a diligência, foram apreendidos dois tabletes, cada um com 1kg de cannabis sativa, além de uma pistola Glock 45, com numeração suprimida, devidamente municiada, guardada dentro de um armário de roupas. Sakura admitiu a posse da droga e da arma, bem como o fato de a droga ter sido adquirida a mando de Naruto, que forneceu a quantia necessária para sua aquisição e garantiria sua entrada no presídio. Nesse caso, a tipicidade adequada é:","alternative_a":"Sakura – tráfico de drogas e posse de arma de fogo com numeração suprimida; Naruto – tráfico de drogas com as majorantes de praticar o crime prevalecendo-se de função pública e de custear a prática criminosa;","alternative_b":"Sakura – tráfico de drogas com as majorantes de o crime ter sido cometido nas dependências ou imediações de estabelecimentos prisionais e com o emprego de arma de fogo; Naruto – tráfico de drogas com as majorantes de praticar o crime prevalecendo-se de função pública, de o crime ter sido cometido nas dependências ou imediações de estabelecimentos prisionais e com o emprego de arma de fogo, além de custear a prática criminosa.","alternative_c":"Sakura – tráfico de drogas com a majorante do emprego de arma de fogo; Naruto – tráfico de drogas com as majorantes de praticar o crime prevalecendo-se de função pública e com o emprego de arma de fogo.","alternative_d":"Sakura – tráfico de drogas e posse de arma de fogo com numeração suprimida; Naruto – tráfico de drogas, com as majorantes de praticar o crime prevalecendo-se de função pública e de custear a prática criminosa, além de posse de arma de fogo com numeração suprimida.","correct_answer":"A","explanation":"A) Correta. Sakura e Naruto praticaram, em concurso, o delito de tráfico de drogas na modalidade de guardar droga (artigo 33 da Lei nº 11.343/06). Sakura também responde pelo crime de posse ilegal de arma de fogo com numeração suprimida (artigo 16, § 1º, inciso I, da Lei 10.826/06), pois admitiu a posse da arma. Quanto a Naruto, levando em consideração que custeou a aquisição da droga e se prevaleceu de sua função pública de agente penitenciário, contatando mulher de preso para a prática do crime, responderá ainda pelas majorantes dos incisos II e VII do artigo 40, Lei nº 11.343/06. Resumindo, Sakura responderá pelo tráfico de drogas e posse de arma de fogo com numeração suprimida e Naruto responderá pelo tráfico de drogas com as majorantes de praticar o crime prevalecendo-se de função pública e de custear a prática criminosa. B) Errada. Quanto a Sakura, não há que se falar em majorantes de o crime ter sido cometido nas dependências ou imediações de estabelecimentos prisionais e com o emprego de arma de fogo. A incidência da causa de aumento do art. 40, IV, da Lei 11.343/06 pressupõe que o uso da arma esteja diretamente ligado ao tráfico de drogas, visando assegurar a mercância ilícita (relação de crime-meio e crime-fim). Nesse caso, absolve-se o crime do Estatuto do Desarmamento. Por outro lado, se a arma de fogo não for efetivamente empregada para assegurar o tráfico (ex.: apreensão de drogas e armas em um galpão), haverá o crime de tráfico de drogas sem a referida causa de aumento, em concurso material com o delito autônomo do Estatuto do Desarmamento. Ademais, para que incida a majorante do art. 40, III, da Lei de Drogas, embora não seja necessário que as drogas efetivamente passem por dentro dos locais que se busca dar maior proteção (estabelecimento prisional), é exigido que o crime tenha ocorrido em seu interior, fato não configurado na hipótese. C) Errada. No caso de sakura, não haverá a incidência da majorante pelo emprego de arma de fogo pois a arma de fogo não foi efetivamente empregada para assegurar o tráfico. No caso, houve o crime de tráfico de drogas sem a referida causa de aumento, em concurso material com o delito autônomo do Estatuto do Desarmamento. D) Errada. Naruto não concorreu para o crime de posse de arma de fogo com numeração suprimida. Fique atento sobre o financiamento no tráfico de drogas!!! Se o agente financia ou custeia o tráfico, mas não pratica nenhum verbo do art. 33, responderá apenas pelo art. 36 da Lei de Drogas. Se o agente, além de financiar ou custear o tráfico, também pratica algum verbo do art. 33 (autofinanciamento), responderá apenas pelo art. 33 c/c o art. 40, VII da Lei de Drogas (não será condenado pelo art. 36). STJ. 6ª Turma. REsp 1290296-PR.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_58","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":58,"discipline":"Direito Penal","topic":"Crimes Contra o Patrimônio","statement":"Matheus subtraiu o celular de Ana Clara no dia 24/12/2019, mediante grave ameaça consistente na promessa de ofender sua integridade corporal com o emprego de uma faca de 22 cm de lâmina. A ação foi percebida por guardas municipais em patrulhamento, que detiveram Matheus de imediato, ainda com a faca na mão e com o celular que fora subtraído. Líbero subtraiu o celular de Renata no dia 14/05/2021, mediante grave ameaça, utilizando também uma arma branca, mas foi rapidamente detido por policiais. Nesse sentido, sabendo que você foi advogado(a) de Matheus em 2019 e, posteriormente, de Líbero em 2021, assinale a alternativa verdadeira.","alternative_a":"Matheus e Líbero tiveram suas penas majoradas no crime de roubo, uma vez que a novatio legis in mellius 13.964/19 majora a pena de roubo cometido com arma branca.","alternative_b":"Matheus e Líbero não tiveram suas penas majoradas no crime de roubo, uma vez que a novatio legis 13.964/19 não majora a pena de roubo cometido com arma branca.","alternative_c":"Matheus não terá sua pena de roubo majorada, uma vez que a lei 13.964/19, por ser uma novatio legis in pejus, não poderá, em nenhuma hipótese, retroagir nesse contexto. Todavia, Líbero terá sua pena majorada, observando-se a data do fato.","alternative_d":"Matheus terá sua pena de roubo majorada uma vez que a lei 13.964/19, por ser uma novatio legis in pejus, poderá retroagir nesse contexto. Todavia, Líbero não terá sua pena majorada, observando-se a data do fato.","correct_answer":"C","explanation":"A) Errada. Quando Matheus realizou o crime de roubo, ainda estava em vigor a Lei 13.654/2018, portanto ainda não era causa de aumento. Já no caso de Líbero, por ser posterior à Lei do Pacote Anticrime, terá causa de aumento. B) Errada. Quando Matheus realizou o crime de roubo, ainda estava em vigor a Lei 13.654/2018, portanto ainda não era causa de aumento. Já no caso de Líbero, por ser posterior à Lei do Pacote Anticrime, terá causa de aumento. C) Correta. Trata-se de questão que envolve as alterações legislativas realizadas pela Lei 13.654/2018 e pela Lei 13.964/19, publicada em 24/12/2019. Antes da Lei 13.654/18, era causa de aumento de pena no crime de roubo ao se utilizar a arma branca. Depois dessa Lei, o emprego da arma branca DEIXOU DE SER 22 CONSIDERADA como aumento de pena. Atualmente, com o pacote anticrime, a Lei 13.964/19 inseriu, no § 2º do art. 157, o inciso VI, que majora novamente a pena do roubo cometido com emprego de arma branca. Nesse sentido, quando Matheus realizou o crime de roubo, ainda estava em vigor a Lei 13.654/2018, portanto ainda não era causa de aumento. Já no caso de Líbero, por ser posterior à Lei do Pacote Anticrime, terá causa de aumento. D) Errada. Quando Matheus realizou o crime de roubo, ainda estava em vigor a Lei 13.654/2018, portanto ainda não era causa de aumento. Já no caso de Líbero, por ser posterior à Lei do Pacote Anticrime, terá causa de aumento.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_59","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":59,"discipline":"Direito Penal","topic":"Crimes Contra a Administração Pública","statement":"Durante uma fiscalização de rotina in loco de um determinado estabelecimento comercial, dois fiscais solicitam, ao comerciante, a documentação pertinente. O comerciante exibe os documentos aos fiscais e estes constatam a ocorrência de irregularidades que os obrigariam a autuar o estabelecimento. Os fiscais comunicam, ao comerciante, que ele será autuado e, neste momento, ele oferece a quantia de R$ 10.000,00 (dez mil reais) para que os agentes deixassem de fazer a autuação. Os fiscais responderam que estariam de acordo mediante o pagamento de R$ 50.000,00 (cinquenta mil reais). Os fiscais, quando o comerciante afirma não possuir essa quantia, realizam a autuação na forma da lei. Diante da narrativa, assinale a afirmativa correta.","alternative_a":"O comerciante cometeu o crime de corrupção e os fiscais cometeram o crime de concussão, todos na modalidade tentada.","alternative_b":"O comerciante cometeu o crime de corrupção ativa e os fiscais cometeram o crime de corrupção passiva.","alternative_c":"O comerciante cometeu o crime de corrupção ativa na modalidade tentada e os fiscais não cometeram nenhum crime.","alternative_d":"O comerciante cometeu o crime de corrupção e os fiscais, de prevaricação.","correct_answer":"B","explanation":"A) Errada. Os crimes praticados foram de corrupção ativa (comerciante) e corrupção passiva (fiscais). Ambos os crimes são formais, e se consumam independentemente da obtenção do resultado almejado. Dessa forma, não há que se falar em crime tentado. B) Correta. De fato, nos termos do art. 333 do Código Penal, comerciante que oferece a quantia para que funcionários públicos deixem de lavrar a autuação comete o crime de corrupção ativa. Por outro lado, conforme disposto no art. 317 do Código Penal, o funcionário público que solicita vantagem indevida para si ou para outra pessoa comete o crime de corrupção passiva. Art. 333, CP: “Oferecer ou prometer vantagem indevida a funcionário público, para determiná-lo a praticar, omitir ou retardar ato de ofício: Pena – reclusão, de 2 (dois) a 12 (doze) anos, e multa.” Art. 317, CP: “Solicitar ou receber, para si ou para outrem, direta ou indiretamente, ainda que fora da função ou antes de assumi-la, mas em razão dela, vantagem indevida, ou aceitar promessa de tal vantagem: Pena–reclusão, de 2 (dois) a 12 (doze) anos, e multa.” C) Errada. Os crimes praticados foram de corrupção ativa (comerciante) e corrupção passiva (fiscais). Ambos os crimes são formais, e se consumam independentemente da obtenção do resultado almejado. Dessa forma, não há que se falar em crime tentado. D) Errada. Os crimes praticados foram de corrupção ativa (comerciante) e corrupção passiva (fiscais). Quando o funcionário público SOLICITA ao particular a vantagem indevida e este dá, apenas o funcionário público terá praticado crime, visto que o particular não OFERECEU nem PROMETEU. Quando o particular dá dinheiro ao funcionário público, haverá tanto a corrupção ativa quanto a passiva, pois houve OFERECIMENTO do particular e RECEBIMENTO do funcionário público.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_60","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":60,"discipline":"Direito Penal","topic":"Dos Crimes em Licitações e Contratos Administrativos","statement":"Pablo e Marina são sócios e únicos diretores responsáveis por uma empresa de construção. Desejosos de participar de uma licitação para a construção de uma escola pública e movidos pelo interesse de executar uma obra impecável, apresentam uma proposta 10% mais barata que os valores normalmente contratados com o setor público para obras semelhantes. Contudo, considerando que o edital exigia que a empresa contratada não tivesse sido declarada inidônea – requisito que a empresa de Pablo e Marina não possuía – os sócios decidem forjar um documento simulando que a declaração de inidoneidade de sua empresa fora anulada judicialmente. Ao final do processo licitatório, a empresa de Pablo e Marina é selecionada e a obra é executada pelo valor previsto. Seis meses depois de entregarem a obra, a falsificação é descoberta. Nesse caso, a responsabilidade penal de Pablo e Marina corresponde a:","alternative_a":"Crime de inserção de dados falsos em sistema de informações.","alternative_b":"Crime de fraude em licitação ou contrato.","alternative_c":"Crime de contratação inidônea.","alternative_d":"Nenhum crime, pois a obra foi realizada e não houve prejuízo à Administração Pública.","correct_answer":"C","explanation":"A) Errada. O crime do art. 313–A do CP é crime próprio e somente pode ser praticado por funcionário público. Além disso, não houve inserção ou facilitação de dados falsos, mas sim contratação inidônea (Art. 337-M, CP). B) Errada. Houve contratação inidônea (Art. 337-M, CP), e não fraude em licitação (Art. 337-L, CP) C) Correta. Questão nova que traz puramente leitura da lei. A conduta descrita na questão se enquadra no art. 337-M que trata sobre contratação inidônea: Art. 337-M, CP: “Admitir à licitação empresa ou profissional declarado inidôneo: Pena - reclusão, de 1 (um) ano a 3 (três) anos, e multa. (...) § 2º Incide na mesma pena do caput deste artigo aquele que, declarado inidôneo, venha a participar de licitação e, na mesma pena do § 1º deste artigo, aquele que, declarado inidôneo, venha a contratar com a Administração Pública. Não confundir com o crime de fraude à licitação ou contrato (o nome pode enganar).” D) Errada. Conforme o fundamentado anteriormente, houve crime de contratação inidônea (Art. 337-M, CP).","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_61","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":61,"discipline":"Direito Penal","topic":"Crimes Contra a Administração Pública","statement":"Desejando apropriar-se de dinheiro público, Matheus, funcionário concursado da Prefeitura de Manaus, elabora o seguinte plano criminoso: (I) valendo-se de seu cargo e função na secretaria de fazenda daquele município, Matheus cadastra a conta-corrente da empresa de seu cunhado, Renato, como sendo a conta de uma das empresas que vencera uma licitação para execução de serviços; (II) ao realizar a autorização para o pagamento dessa empresa, Matheus destina apenas 95% dos valores à conta-corrente da empresa regularmente contratada e 5% à conta-corrente da empresa de seu cunhado; (III) Renato, por sua vez, saca os valores, dividindo-os com Matheus na proporção de 50% para cada um; (IV) Ana Clara, também funcionária concursada da prefeitura e trabalhando na mesma secretaria, que tem como responsabilidade conferir os pagamentos autorizados por Matheus antes da liberação, deixa, por negligência, de fazer a conferência, de modo que o desvio ocorre. A responsabilidade penal de Matheus, Renata e Ana Clara, respectivamente, configura-se como:","alternative_a":"Matheus - peculato doloso; Renata - peculato doloso; Ana Clara - peculato doloso.","alternative_b":"Matheus - peculato doloso; Renata - peculato doloso; Ana Clara - peculato culposo.","alternative_c":"Matheus - estelionato; Renata - peculato doloso; Ana Clara - conduta atípica.","alternative_d":"Matheus - fraude em licitação; Renata - peculato doloso; Ana Clara - nenhum crime.","correct_answer":"B","explanation":"A) Errada. Matheus e Renata responderão por peculato doloso. Contudo, Ana Clara responderá por peculato culposo, já que não conferiu os pagamentos efetuados incorretamente, por negligência. 23 B) Correta. Matheus praticou peculato, crime previsto no art. 312, CP. Renata, apesar de não ser funcionária pública, também responderá pelo crime de peculato doloso, visto que é de seu conhecimento a qualidade de Matheus como funcionário público, transmitindo-lhe por ser elementar do crime (concurso de crime, teoria unitária ou monista). Ana Clara, sendo funcionária pública, responderá por peculato culposo, já que não conferiu os pagamentos efetuados incorretamente, por negligência. Art. 312, CP: “Apropriar-se o funcionário público de dinheiro, valor ou qualquer outro bem móvel, público ou particular, de que tem a posse em razão do cargo, ou desviá-lo, em proveito próprio ou alheio”. C) Errada. Não se trata de estelionato, mas de crime funcional, eis que Matheus era funcionário público e Renata agiu sabendo desta condição, razão pela qual ambos devem responder por peculato doloso (art. 312, CP). Quanto a Ana Clara, sua conduta não é atípica, pois há previsão do peculato culposo (art. 312, §2º, CP). D) Errada. Conforme o fundamentado nas alternativas anteriores, houve a prática de crime de peculato doloso quanto a Matheus e Renata e, quanto a Ana Clara, peculato culposo.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_62","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":62,"discipline":"Direito Penal","topic":"Tipicidade","statement":"Jorge ingressou em uma loja de conveniência de determinado posto de gasolina, com a intenção de praticar um crime de roubo, portando um simulacro de arma de fogo. Após ingressar no local e anunciar o assalto, verifica que a única pessoa presente e que estava responsável pelo caixa era o adolescente Caio, de 16 anos de idade, que ajudava seu pai idoso, verdadeiro proprietário do estabelecimento. Lamentando o fato de o adolescente estar trabalhando, Jorge retira-se do local sem subtrair qualquer bem. Os fatos são descobertos pela autoridade policial após divulgação das imagens das câmeras de segurança, mas Caio e seu pai optam por não comparecerem à sede policial, uma vez que não possuem interesse na responsabilização de Jorge, por este ter decidido não subtrair os bens durante a execução do delito. Com base nas informações expostas, é correto afirmar que a conduta de Jorge configura:","alternative_a":"Crime de roubo simples, devendo ser reconhecida a causa de diminuição de pena, em razão do arrependimento posterior.","alternative_b":"Conduta atípica em relação ao crime de roubo, em razão do arrependimento eficaz. Não há como ter a persecução penal diante do desinteresse de Caio e de seu representante em verem o autor do fato responsabilizado pelo delito residual.","alternative_c":"Crime de roubo majorado pelo emprego de arma de fogo, com causa de redução de pena em razão da tentativa.","alternative_d":"Conduta atípica em relação ao crime de roubo, em razão da desistência voluntária. Não há como ter a persecução penal diante do desinteresse de Caio e de seu representante em verem o autor do fato responsabilizado pelo delito residual.","correct_answer":"D","explanation":"A) Errada. Não se trata de arrependimento posterior, mas sim de desistência voluntária. Na desistência voluntária, o agente abandona a execução do crime quando ainda lhe sobra, do ponto de vista objetivo, alguma margem de ação, que foi o que aconteceu no caso descrito na questão. No arrependimento posterior, o agente já finalizou todos os atos executórios. Trata-se de causa de redução de pena, que incide quando o acusado pratica crime sem violência ou grave ameaça e, arrependido, decide reparar o dano ou devolver o objeto até o recebimento da denúncia ou queixa. B) Errada. Não se trata de arrependimento eficaz, mas sim de desistência voluntária. Na desistência voluntária, o agente abandona a execução do crime quando ainda lhe sobra, do ponto de vista objetivo, alguma margem de ação. No arrependimento eficaz, não há margem alguma, porque o processo de execução está encerrado, e o agente atua apenas para evitar que sobrevenha o resultado.” (PACELLI, Eugênio. Manual de Direito Penal. 5ª. ed. São Paulo: Atlas, 2019. p. 311-312). No caso, nos termos do art. 15 do CP, o agente responderia somente pelos atos já praticados, ou seja, a ameaça. Contudo, diante da ausência de representação, não há justa causa para a persecução penal. C) Errada. Não há prática do crime de roubo, pois José desistiu voluntariamente de praticar o crime de roubo. Dessa forma, não subtraiu coisa alheia para si ou para outrem, mediante violência ou grave ameaça. Assim, a conduta é atípica quanto ao suposto crime de roubo. D) Correta. Nota-se que, no caso, José desistiu voluntariamente de praticar o crime de roubo. A conduta narrada não é roubo (atípica nesse ponto), pois não subtraiu coisa alheia para si ou para outrem, mediante violência ou grave ameaça. Contudo, nos termos do art. 15 do CP, deve responder pelos atos já praticados. Assim, a conduta é típica quanto à ameaça, porém, diante da ausência de representação, não há justa causa para a persecução penal. Desistência voluntária e arrependimento eficaz Art. 15, CP: “O agente que, voluntariamente, desiste de prosseguir na execução ou impede que o resultado se produza, só responde pelos atos já praticados.” Arrependimento posterior Art. 16, CP: “Nos crimes cometidos sem violência ou grave ameaça à pessoa, reparado o dano ou restituída a coisa, até o recebimento da denúncia ou da queixa, por ato voluntário do agente, a pena será reduzida de um a dois terços.” PROCESSO PENAL","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_63","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":63,"discipline":"Direito Processual Penal","topic":"Acordo de Não Persecução Penal","statement":"Jairo foi preso em flagrante em posse de um rádio transmissor durante operação policial que combatia o tráfico de drogas. Autuado pela infração prevista no art. 35 da Lei nº 11.343/2006, Jairo foi apresentado para audiência de custódia, tendo o Ministério Público oferecido acordo de não persecução penal, mediante condições específicas. Devolvidos os autos ao Ministério Público para reanálise da proposta, nela insistiu-se o parquet. Caso o juiz não concorde com a manifestação do acusador, pode:","alternative_a":"Remeter os autos ao procurador-geral de justiça. Sem possibilidade de recurso em sede de acordo de não persecução penal.","alternative_b":"Decretar a prisão preventiva e devolver os autos ao Ministério Público, a fim de que a proposta de acordo seja reformulada, com a concordância do investigado e de seu defensor.","alternative_c":"Recusar a homologação e devolver os autos ao Ministério Público para a análise da necessidade de complementação das investigações ou o oferecimento da denúncia. Também é possível recurso em sentido estrito da decisão que não homologar o acordo de não persecução penal.","alternative_d":"Decretar a prisão preventiva e devolver os autos ao Ministério Público para a análise da necessidade de complementação das investigações ou o oferecimento da denúncia.","correct_answer":"C","explanation":"A) Errada. O juiz pode recusar a homologação, de modo que, neste caso,deverá remeter os autos ao Ministério Público, e não ao Procurador-Geral de Justiça, para a análise da necessidade de complementação das investigações ou o oferecimento da denúncia. B) Errada. Após a lei 13.964/2019 não há previsão de decretação da prisão preventiva de ofício. Segundo o art. 28-A, §5º, do CP: “Se o juiz considerar inadequadas, insuficientes ou abusivas as condições dispostas no acordo de não persecução penal, devolverá os autos ao Ministério Público para que seja reformulada a proposta de acordo, com concordância do investigado e seu defensor.” 24 C) Correta. De acordo com o CPP (§ 7º do art. 28-A), caso o MP proponha um ANPP e o juiz entenda que as condições propostas são inadequadas, insuficientes ou abusivas, deverá devolver os autos ao MP para adequação. Porém, se o MP insistir nas condições anteriormente propostas, o juiz deverá recusar homologar o ANPP (não remeter ao PGJ) e devolver novamente os autos ao MP para análise da necessidade de complementação das investigações ou oferecimento da denúncia (situação esta que é a resposta da questão). Caberá Recurso em Sentido Estrito da decisão judicial que recusar homologação à proposta de acordo de não persecução penal. D) Errada. Após a lei 13.964/2019 não há previsão de decretação da prisão preventiva de ofício.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_64","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":64,"discipline":"Direito Processual Penal","topic":"Recursos","statement":"Maria foi presa em flagrante transportando 2 kg de cocaína. O motorista do veículo e o outro acompanhante conseguiram fugir sem que fossem identificados. Em audiência de custódia, o juiz recusou o pedido de conversão do flagrante em preventiva, concedendo liberdade provisória à indiciada, com cautelar de comparecimento mensal ao juízo. Inconformado, o representante do parquet interpôs recurso em sentido estrito (RESE), sendo os autos remetidos ao juízo competente. Na Vara Criminal, o Ministério Público ofereceu denúncia por infração aos arts. 33 e 35 da Lei nº 11.343/2006. O juiz rejeitou parcialmente a denúncia quanto ao crime do art. 35 e revogou a decisão do juiz da custódia, decretando a prisão preventiva, sem a oitiva da defesa, com imediata expedição de mandado de prisão. Diante do caso narrado, assinale a alternativa que elenca as medidas cabíveis.","alternative_a":"Mandado de segurança pelo promotor, em razão da rejeição parcial da denúncia; petição simples da defesa no RESE, recorrendo da decretação da prisão em juízo de retração sem prévia oitiva da defesa.","alternative_b":"Recurso em sentido estrito por parte do promotor, em razão da rejeição parcial da denúncia; petição simples da defesa no RSE, recorrendo da decretação da prisão em juízo de retração sem prévia oitiva da defesa.","alternative_c":"Recurso em sentido estrito por parte do promotor, em razão da rejeição parcial da denúncia; habeas corpus pela defesa, em razão da decretação da prisão em juízo de retratação sem prévia oitiva da defesa;","alternative_d":"Mandado de segurança pelo promotor, em razão da rejeição parcial da denúncia; habeas corpus pela defesa, em razão da decretação da prisão em juízo de retratação sem prévia oitiva da defesa.","correct_answer":"C","explanation":"A) Errada. Não há que se falar em Mandado de Segurança da acusação para combater decisão de rejeição da denúncia ou da queixa, pois, nos termos do artigo 581, I, do CPP, trata-se de Recurso em Sentido Estrito. Além disso, quanto à defesa, não há previsão de petição simples para recorrer da decretação da prisão em juízo de retratação sem prévia oitiva da defesa, sendo o instrumento adequado a ser apresentado pela defesa o Habeas Corpus. B) Errada. Quanto ao recurso da acusação caberá Recurso em Sentido Estrito, pois trata-se de decisão de rejeição da denúncia ou da queixa (artigo 581, I, do CPP). Não há previsão de petição simples para recorrer da decretação da prisão em juízo de retratação sem prévia oitiva da defesa, sendo o instrumento adequado a ser apresentado pela defesa o Habeas Corpus. C) Correta. Quanto ao recurso da acusação caberá Recurso em Sentido Estrito, pois trata-se de decisão de rejeição da denúncia ou da queixa (artigo 581, I, do CPP). Quanto ao recurso da defesa, caberá o habeas corpus, pois este tutela o direito de ir, vir e permanecer, quando se estiver diante de uma coação ilegal, como, por exemplo, quando há decretação da prisão em juízo de retratação sem prévia oitiva da defesa, que é o caso da questão (artigo 648 do CPP). “Art. 581, CPP: Caberá recurso, no sentido estrito, da decisão, despacho ou sentença: I - que não receber a denúncia ou a queixa;” D) Errada. Não há que se falar em Mandado de Segurança da acusação para combater decisão de rejeição da denúncia ou da queixa, pois, nos termos do artigo 581, I, do CPP, trata-se de Recurso em Sentido Estrito. Quanto ao recurso da defesa, caberá o habeas corpus, pois este tutela o direito de ir, vir e permanecer, quando se estiver diante de uma coação ilegal, como, por exemplo, quando há decretação da prisão em juízo de retratação sem prévia oitiva da defesa, que é o caso da questão (artigo 648 do CPP).","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_65","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":65,"discipline":"Direito Processual Penal","topic":"Inquérito Policial","statement":"25 No curso de inquérito policial, a autoridade policial indiciou Napoleão pela prática do crime de homicídio qualificado, em que pese os elementos de informação colhidos demonstrassem, de maneira clara, que o investigado agiu em legítima defesa. Visando combater tal decisão e buscar o “trancamento” do inquérito policial, o advogado de Napoleão poderá:","alternative_a":"Impetrar habeas corpus, sendo competente para julgamento um juiz de 1º grau.","alternative_b":"O trancamento do inquérito policial só pode ser concedido pelo Ministério Público, uma vez que há uma hierarquia entre tais entidades.","alternative_c":"Impetrar habeas corpus, sendo competente para julgamento o Tribunal de Justiça respectivo.","alternative_d":"Interpor recurso para o chefe de polícia;","correct_answer":"A","explanation":"A) Correta. O trancamento do inquérito poderá ser pugnado por intermédio de habeas corpus tutela, pois este tutela o direito de ir, vir e permanecer, quando se estiver diante de uma coação ilegal (artigo 648 do CPP), que é o caso da questão apresentada. Cuidando-se de inquérito policial instaurado por portaria da autoridade policial ou em auto de prisão em flagrante, o delegado de polícia é a autoridade coatora, devendo o HC ser apreciado por um juiz de 1ª instância. No entanto, se o IP tiver sido instaurado por requisição da autoridade judiciária ou do MP, caberá, ao Tribunal competente para o processo e julgamento dessa autoridade, a apreciação da ordem de habeas corpus. (Manual de Processo Penal, Renato Brasileiro). B) Errada. Não há previsão legal nesse sentido. C) Errada. Cuidando-se de inquérito policial instaurado por portaria da autoridade policial ou em auto de prisão em flagrante, o delegado de polícia é a autoridade coatora, devendo o HC ser apreciado por um juiz de 1ª instância. No entanto, se o IP tiver sido instaurado por requisição da autoridade judiciária ou do MP, caberá, ao Tribunal competente para o processo e julgamento dessa autoridade, a apreciação da ordem de habeas corpus. (Manual de Processo Penal, Renato Brasileiro). D) Errada. O recurso ao Chefe de Polícia caberá nos casos em que despacho indeferir o requerimento de abertura de inquérito policial (artigo 5, §2º, do CPP).","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_66","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":66,"discipline":"Direito Processual Penal","topic":"Recursos","statement":"Devido à grande quantidade de trabalho, determinado promotor de justiça solicitou que seu estagiário analisasse duas decisões de diferentes processos em que estava sendo intimado, esclarecendo que deveria ser informado qual o recurso cabível caso a decisão fosse desfavorável ao Ministério Público. No primeiro processo, foi proferida decisão de impronúncia em procedimento onde se imputava a prática do crime de aborto qualificado pelo resultado morte da gestante. Na segunda ação penal, foi proferida decisão de rejeição da denúncia oferecida pelo parquet pela prática de um crime de roubo. Considerando apenas as informações narradas, o estagiário deverá esclarecer que a decisão de impronúncia e a de rejeição da denúncia deverão ser combatidas através de:","alternative_a":"Apelação, em ambos os casos, não cabendo juízo de retratação.","alternative_b":"Recurso em sentido estrito, em ambos os casos, cabendo juízo de retratação.","alternative_c":"Apelação e recurso em sentido estrito, respectivamente, cabendo juízo de retratação apenas na segunda hipótese.","alternative_d":"Recurso em sentido estrito e apelação, respectivamente, cabendo juízo de retratação apenas na primeira hipótese.","correct_answer":"C","explanation":"A) Errada. No primeiro caso trata-se de apelação (art. 416 do CPP). Contudo, no segundo caso o recurso cabível é o recurso em sentido estrito (art. 581, I do CPP). Há a possibilidade de retratação no recurso em sentido estrito (art. 589 do CPP). 25 B) Errada. No primeiro caso trata-se de apelação (art. 416 do CPP). No segundo caso, o recurso cabível é o recurso em sentido estrito (art. 581, I do CPP). Há a possibilidade de retratação no recurso em sentido estrito (art. 589 do CPP). C) Correta. Contra a sentença de impronúncia ou de absolvição sumária caberá apelação (art. 416 do CPP). Da decisão, despacho ou sentença que não receber a denúncia ou a queixa caberá recurso em sentido estrito (art. 581, I do CPP). Há a possibilidade de retratação no recurso em sentido estrito (art. 589 do CPP). D) Errada. No primeiro caso trata-se de apelação (art. 416 do CPP). No segundo caso, o recurso cabível é o recurso em sentido estrito (art. 581, I do CPP). Há a possibilidade de retratação no recurso em sentido estrito (art. 589 do CPP).","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_67","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":67,"discipline":"Direito Processual Penal","topic":"Ação Penal","statement":"Ao sair de sua casa, em 17/05/2020, Miriam foi surpreendida por faixa anônima estendida na via pública contendo diversas ofensas à sua honra. Diante da humilhação sofrida, Miriam deixou o país e foi morar no exterior sem se interessar em descobrir o responsável pelos fatos. Em 03/01/2021, Miriam recebeu mensagem de Sandra, sua antiga vizinha, confessando que ela teria sido a autora das ofensas, bem como esclarecendo que informou os fatos ao delegado de polícia, em razão de seu arrependimento. Miriam entrou em contato com seu advogado em 25/01/2021, para esclarecimentos jurídicos, informando que permanece no exterior. O advogado deverá esclarecer, naquela ocasião, que o crime praticado seria de injúria, de ação penal privada, logo:","alternative_a":"A queixa-crime poderá ser oferecida por Miriam, mas se for feita através de procurador, exigem-se poderes especiais.","alternative_b":"A queixa-crime poderá ser oferecida por Miriam, pessoalmente ou por procurador sem poderes especiais.","alternative_c":"A inicial acusatória não poderá ser oferecida por Miriam, pois operou-se o prazo decadencial.","alternative_d":"A abertura do inquérito policial não poderá ser determinada pela autoridade policial nem requerida por Miriam, pois operou-se o prazo prescricional para representação.","correct_answer":"A","explanation":"A) Correta. Nos casos de Ação Privada, o direito de queixa-crime ou de representação tem prazo decadencial de 6 MESES a partir do CONHECIMENTO do autor do crime. Além disso, o direito de representação poderá ser exercido pessoalmente ou por PROCURADOR com poderes ESPECIAIS. B) Errada. Se for feita através de procurador, exigem-se poderes especiais (Art. 103 CP e 38 CPP). Art. 103 CP e 38 CPP: “A queixa de ação penal privada exclusiva pode ser oferecida pessoalmente ou por procurador, desde que se trate de procuração com poderes especiais, nos termos do art. 44 do CPP.” C) Errada. Não houve decadência, pois o prazo inicia-se após o descobrimento do autor do crime, não da data de ocorrência do crime. D) Errada. Nos termos do artigo 5º, §5º do Código de Processo Penal: “Nos crimes de ação privada, a autoridade policial somente poderá proceder a inquérito a requerimento de quem tenha qualidade para intentá-la.\". Não há que se falar em prazo prescricional.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_68","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":68,"discipline":"Direito Processual Penal","topic":"Ação Penal","statement":"João ofereceu queixa-crime em face de José, imputando-lhe a prática do crime de calúnia majorada. No curso da instrução, após recebimento da queixa-crime, João não compareceu para dar prosseguimento ao feito. O oficial de justiça informou que não foi possível intimar João pelo fato de a área de sua residência ser considerada de risco. O Ministério Público, na qualidade de custos legis, através de seus próprios servidores, auxiliou o Oficial de Justiça e foi realizada a intimação do querelante para dar prosseguimento. Na ocasião, informou-se a data da audiência designada. Passados 30 (trinta) dias, João manteve-se inerte e não compareceu à audiência de instrução e julgamento. Considerando apenas os fatos narrados, assinale a alternativa correta.","alternative_a":"O reconhecimento da extinção da punibilidade em razão do perdão do ofendido ocorrido depende de requerimento do Ministério Público, não podendo ser declarado de ofício pelo magistrado.","alternative_b":"A perempção restou configurada, gerando a extinção da punibilidade do agente, aplicando-se o princípio da disponibilidade das ações penais privadas.","alternative_c":"O perdão do ofendido restou configurado, gerando a extinção da punibilidade do querelado, independentemente de sua concordância.","alternative_d":"O procedimento deve prosseguir, cabendo ao Ministério Público assumir o polo ativo diante da omissão do querelante.","correct_answer":"B","explanation":"A) Errada. Se o Juiz reconhecer extinta a punibilidade deverá declará-la de ofício (art. 61, CPP). B) Correta. No caso apresentado ocorreu a perempção, pois, intimado, João manteve-se inerte e não compareceu à audiência de instrução e julgamento. Art. 60, CPP: “Nos casos em que somente se procede mediante queixa, considerar-se-á perempta a ação penal: (...) III - quando o querelante deixar de comparecer, sem motivo justificado, a qualquer ato do processo a que deva estar presente, ou deixar de formular o pedido de condenação nas alegações finais; (...)” C) Errada. Para que o perdão do ofendido seja causa de extinção de punibilidade é necessário que o querelado aceite D) Errada. O caso apresentado trata de ação penal privada. Deste modo, o Ministério Público atua tão somente como fiscal da lei. No caso apresentado ocorreu a perempção. DIREITO PREVIDENCIÁRIO","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_69","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":69,"discipline":"Direito Previdenciário","topic":"Seguridade Social","statement":"Os regimes da previdência social tem como objetivo a universalidade da cobertura e do atendimento. Sendo assim, de acordo com as diretivas constitucionais, ela é organizada mediante o regime:","alternative_a":"geral da previdência social e regime próprio de previdência social dos servidores Públicos, apenas.","alternative_b":"geral da previdência social, regime próprio de previdência social dos servidores Públicos e regime privado de previdência complementar.","alternative_c":"geral da previdência social, regime próprio de previdência social dos servidores Públicos e regime próprio de previdência social dos celetistas.","alternative_d":"geral da previdência social, apenas.","correct_answer":"B","explanation":"A) Errada. Está incorreta, pois não mencionou o regime privado de previdência complementar, conforme art. 201 e 202 da CF. Art. 201 da CF. A previdência social será organizada sob a forma do Regime Geral de Previdência Social, de caráter contributivo e de filiação obrigatória, observados critérios que preservem o equilíbrio financeiro e atuarial, e atenderá, na forma da lei, a: Art. 202 da CF. O regime de previdência privada, de caráter complementar e organizado de forma autônoma em relação ao regime geral de previdência social, será facultativo, baseado na constituição de reservas que garantam o benefício contratado, e regulado por lei complementar. B) Correta. Alternativa em consonância com o art. 201 e 202 da CF. C) Errada.Está incorreta, pois menciona um regime que não existe regime próprio de previdência social dos celetistas. D) Errada. Deixou de mencionar o regime próprio de previdência social dos servidores Públicos e regime privado de previdência complementar. 26","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_70","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":70,"discipline":"Direito Previdenciário","topic":"Benefício Previdenciário","statement":"Marina estava estudando direito previdenciário para a prova da OAB, quando se deparou com uma questão a respeito dos benefícios previdenciários. Em razão disso, foi perguntado a sua professora se é permitido a cumulação de benefício da Previdência Social, com exceção da existência de direito adquirido. Diante disso, marque a alternativa em que menciona qual benefício pode ser cumulado:","alternative_a":"Seguro desemprego e auxílio-acidente","alternative_b":"Aposentadoria e auxílio-doença","alternative_c":"Mais de uma aposentadoria","alternative_d":"Salário-maternidade e auxílio-doença","correct_answer":"A","explanation":"A) Correta. Está em consonância com o parágrafo único do art. 124 da Lei 8213/91. Art. 124, parágrafo único da Lei 8213/91. É vedado o recebimento conjunto do seguro-desemprego com qualquer benefício de prestação continuada da Previdência Social, exceto pensão por morte ou auxílio-acidente. B) Errada. Está incorreta, pois não é possível a cumulação de aposentadoria e auxílio-doença, conforme art. 124, I da Lei 8213/91. Art. 124 da Lei 8213/91. Salvo no caso de direito adquirido, não é permitido o recebimento conjunto dos seguintes benefícios da Previdência Social: I - aposentadoria e auxílio-doença; C) Errada. Está incorreta, pois não é possível a cumulação de mais de uma aposentadoria, conforme art. 124, II da Lei 8213/91. Art. 124 da Lei 8213/91. Salvo no caso de direito adquirido, não é permitido o recebimento conjunto dos seguintes benefícios da Previdência Social: II - mais de uma aposentadoria; D) Errada. Está incorreta, pois não é possível a cumulação de salário-maternidade e auxílio-doença, conforme art. 124, IV da Lei 8213/91. Art. 124 da Lei 8213/91. Salvo no caso de direito adquirido, não é permitido o recebimento conjunto dos seguintes benefícios da Previdência Social: IV - salário-maternidade e auxílio-doença; DIREITO DO TRABALHO","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_71","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":71,"discipline":"Direito do Trabalho","topic":"Gestante","statement":"Chika é empregada da empresa Ultra Romântica Ltda., exercendo atividade considerada insalubre pela NR-15 e já classificada como grau médio. Ocorre que Chika ficou grávida em março de 2022 e procura você, como advogado","alternative_a":", pois seu empregador quer afastá-la de suas atividades durante a gravidez, sem a percepção de remuneração durante o período. À luz das disposições presentes na CLT e de acordo com o entendimento do Supremo Tribunal Federal, assinale a alternativa correta. a) Chika poderá continuar exercendo sua atividade durante a gravidez, devendo ser afastada somente caso apresente atestado de saúde emitido por médico de sua confiança recomendando o seu afastamento.","alternative_b":"Chika somente poderia continuar exercendo sua atividade se o grau de insalubridade fosse mínimo, de acordo com a previsão expressa da CLT.","alternative_c":"Chika deverá ser afastada de suas atividades, independentemente do grau de insalubridade, sem prejuízo da sua remuneração, nessa incluído o adicional de insalubridade.","alternative_d":"Chika deverá ser afastada de suas atividades, em razão do grau ser médio, e nesse período não será remunerada, pois estará configurada a suspensão.","correct_answer":"C","explanation":"A) Errada. Ela não poderá continuar exercendo a atividade em local insalubre e muito menos poderá ser afastada apenas com a apresentação de atestado médico. B) Errada. Independentemente do grau (máximo, médio ou mínimo), deverá ser afastada de suas funções, sem a necessidade de emissão de atestado médico, conforme art. 394-A da CLT. Art. 394-A da CLT. Sem prejuízo de sua remuneração, nesta incluído o valor do adicional de insalubridade, a empregada deverá ser afastada de: I - atividades consideradas insalubres em grau máximo, enquanto durar a gestação; II - atividades consideradas insalubres em grau médio ou mínimo, quando apresentar atestado de saúde, emitido por médico de confiança da mulher, que recomende o afastamento durante a gestação; (Vide ADIN 5938) III - atividades consideradas insalubres em qualquer grau, quando apresentar atestado de saúde, emitido por médico de confiança da mulher, que recomende o afastamento durante a lactação. (Vide ADIN 5938) ATENÇÃO Após o julgamento da ADIN 5938, as partes finais dos incisos II e III do art. 394-A da CLT foram julgadas inconstitucionais. Ou seja, a empregada gestante e a empregada lactante que exercerem atividades insalubres, independentemente do grau (máximo, médio ou mínimo), deverão ser afastadas de suas funções, sem a necessidade de emissão de atestado médico. Ademais, durante esse período, a empregada gestante e lactante continuará recebendo sua remuneração normalmente, nela incluído o adicional de insalubridade. C) Correta. Alternativa em consonância com o art. 394-A da CLT. Art. 394-A da CLT.. Sem prejuízo de sua remuneração, nesta incluído o valor do adicional de insalubridade, a empregada deverá ser afastada de: I - atividades consideradas insalubres em grau máximo, enquanto durar a gestação; II - atividades consideradas insalubres em grau médio ou mínimo, quando apresentar atestado de saúde, emitido por médico de confiança da mulher, que recomende o afastamento durante a gestação; (Vide ADIN 5938) III - atividades consideradas insalubres em qualquer grau, quando apresentar atestado de saúde, emitido por médico de confiança da mulher, que recomende o afastamento durante a lactação. (Vide ADIN 5938) D) Errada. Chika deverá ser afastada das suas atividades, porém continuará recebendo sua remuneração mensal e o adicional de insalubridade, conforme art. 394-A, §3° da CLT. Art. 394-A, §3° da CLT. Quando não for possível que a gestante ou a lactante afastada nos termos do caput deste artigo exerça suas atividades em local salubre 27 na empresa, a hipótese será considerada como gravidez de risco e ensejará a percepção de salário-maternidade, nos termos da Lei no 8.213, de 24 de julho de 1991, durante todo o período de afastamento.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_72","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":72,"discipline":"Direito do Trabalho","topic":"Participação nos Lucros ou Resultados","statement":"Matheus, dono da empresa Plus Ultra Ltda., deseja implantar a participação nos lucros e resultados (PLR) para seus funcionários. Para isso, ele procura você, como advogado","alternative_a":", para saber mais sobre a PLR e sua aplicação prática. Na oportunidade, você, como advogado(a), deverá esclarecer que: a) A PLR é uma parcela de natureza salarial, constituindo base de incidência de todos os encargos trabalhistas.","alternative_b":"A empresa não poderá celebrar acordo coletivo de trabalho acerca da PLR, pois a matéria está incluída no rol de objetos que não podem ser discutidos em acordo ou convenção coletiva de trabalho.","alternative_c":"A PLR é uma parcela de natureza indenizatória desvinculada da remuneração que poderá ser paga, no máximo, duas vezes por ano.","alternative_d":"Caso a empresa Plus Utra Ltda. tenha resultado positivo, não terá a obrigação de pagar os funcionários que tenham contribuído com a empresa se o contrato de trabalho desses funcionários for extinto antes da data prevista para o pagamento.","correct_answer":"C","explanation":"A) Errada. De acordo com o art. 7º, XI da CF/88, a PLR é desvinculada da remuneração, ou seja, possui natureza indenizatória. Art. 7º da CF. São direitos dos trabalhadores urbanos e rurais, além de outros que visem à melhoria de sua condição social: XI - participação nos lucros, ou resultados, desvinculada da remuneração, e, excepcionalmente, participação na gestão da empresa, conforme definido em lei; B) Errada. Podem ser objeto de ACT ou CCT, conforme art. 611-A, XV da CLT Art. 611-A da CLT. A convenção coletiva e o acordo coletivo de trabalho têm prevalência sobre a lei quando, entre outros, dispuserem sobre: XV - participação nos lucros ou resultados da empresa. C) Correta. De acordo com o art. 7º, XI da CF/88,. D) Errada. A empresa terá a obrigação de pagar os funcionários que tenham contribuído com a empresa. Pois segundo a Súmula nº 451 do TST prevê que fere o princípio da isonomia instituir vantagem mediante acordo coletivo ou norma regulamentar que condiciona a percepção da PLR ao fato de estar o contrato do trabalho em vigor na data prevista para o pagamento.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_73","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":73,"discipline":"Direito do Trabalho","topic":"Férias","statement":"Fernanda foi contratada para trabalhar 04 vezes por semana na casa da família Assis. Sabendo que em maio de 2023, ela poderá usufruir das suas férias, já começa a se programar com a sua família para poder aproveitá-las. Ocorre que Fernanda possui diversas dúvidas a respeito do regime de férias e principalmente da forma como sua chefe informou. De acordo com a legislação, assinale a alternativa que indica a orientação correta informada pela chefe de Fernanda.","alternative_a":"As férias poderão ser usufruídas em até 3 períodos, sendo que um deles não poderá ser inferior a 14 corridos e os demais não poderão ser inferiores a 5 dias corridos, cada um.","alternative_b":"O período de férias poderá, a critério do empregador, ser fracionado em até 2 períodos, sendo 1 deles de, no mínimo, 14 dias corridos.","alternative_c":"O abono de férias deverá ser requerido até 30 dias antes do início do período aquisitivo.","alternative_d":"É obrigatório ao empregado doméstico converter um terço do período de férias a que tiver direito em abono pecuniário, no valor da remuneração que lhe seria devida nos dias correspondentes.","correct_answer":"B","explanation":"A) Errada. Pois Fernanda é considerada empregada doméstica, em razão de trabalhar mais de 02 dias em casa de família, nos termos do art. 1° da LC 150/2015. Art. 1o,LC 150/1015 Ao empregado doméstico, assim considerado aquele que presta serviços de forma contínua, subordinada, onerosa e pessoal e de finalidade não lucrativa à pessoa ou à família, no âmbito residencial destas, por mais de 2 (dois) dias por semana, aplica-se o disposto nesta Lei. B) Correta. Alternativa em consonância com o art. 15, §2° da LC 150/2015, pois Fernanda é considerada empregada doméstica. Art. 17, LC 150/1015. O empregado doméstico terá direito a férias anuais remuneradas de 30 (trinta) dias, salvo o disposto no § 3o do art. 3o, com acréscimo de, pelo menos, um terço do salário normal, após cada período de 12 (doze) meses de trabalho prestado à mesma pessoa ou família. § 2o O período de férias poderá, a critério do empregador, ser fracionado em até 2 (dois) períodos, sendo 1 (um) deles de, no mínimo, 14 (quatorze) dias corridos. C) Errada. Pois o abono de férias deve ser requerido até 30 dias antes do término do período aquisitivo, conforme o §4° do art. 17 da LC 120/2015. Art. 17. § 4o, LC 150/1015. O abono de férias deverá ser requerido até 30 (trinta) dias antes do término do período aquisitivo. D) Errada. Pois é uma faculdade do empregado fazer essa conversão, conforme o §3° do art. 17 da LC 120/2015. Art. 17. § 3o, LC 150/1015. É facultado ao empregado doméstico converter um terço do período de férias a que tiver direito em abono pecuniário, no valor da remuneração que lhe seria devida nos dias correspondentes.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_74","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":74,"discipline":"Direito do Trabalho","topic":"Extinção do Contrato de Trabalho - Justa Causa","statement":"A fábrica na qual Miyamura trabalha, em cumprimento à Norma Regulamentadora 6 (NR6) e em atendimento ao artigo 157 da Consolidação das Leis do Trabalho, distribui equipamentos de proteção individual (EPIs) aos seus empregados. Miyamura recebe, conforme a necessidade, capacete, luvas e óculos de proteção para o exercício de suas funções. No entanto, Miyamura se opõe ao uso do capacete e dos óculos, pois esses não combinam com seu estilo, em razão dos piercings que possui. A partir do caso narrado, assinale a alternativa correta.","alternative_a":"Caso Miyamura perceba um salário superior a duas vezes o limite máximo dos benefícios do Regime Geral da Previdência Social, ele poderá negociar diretamente o uso dos EPIs com seu empregador.","alternative_b":"O empregador de Miyamura poderá demiti-lo por justa causa, uma vez que a recusa ao uso dos EPIs é considerada falta grave.","alternative_c":"A Reforma Trabalhista tornou facultativa a distribuição dos EPIs, possibilitando a Miyamura o uso ou não dos equipamentos.","alternative_d":"Caberá à fábrica demitir Miyamura apenas sem justa causa, pagando-lhe todas as verbas rescisórias referentes a essa modalidade de rescisão contratual.","correct_answer":"B","explanation":"A) Errada. Para ser considerado hipersuficiente é necessário o empregado ser portador de diploma de nível superior e receber salário mensal igual ou superior a duas vezes o limite máximo dos benefícios do RGPS, conforme art. 444 da CLT. Além disso só poderá ser objeto de livre estipulação quando não contravenha às disposições de proteção ao trabalho Art. 444 da CLT. As relações contratuais de trabalho podem ser objeto de livre estipulação das partes interessadas em tudo quanto não contravenha às disposições de proteção ao trabalho, aos contratos coletivos que lhes sejam aplicáveis e às decisões das autoridades competentes. Parágrafo único. A livre estipulação a que se refere o caput deste artigo aplica-se às hipóteses previstas no art. 611-A desta Consolidação, com a mesma eficácia legal e preponderância sobre os instrumentos 28 coletivos, no caso de empregado portador de diploma de nível superior e que perceba salário mensal igual ou superior a duas vezes o limite máximo dos benefícios do Regime Geral de Previdência Social. B) Correta. Consoante ao artigo 158, parágrafo único, alínea “b” da CLT, considera-se falta grave a recusa injustificada do empregado ao uso dos equipamentos de proteção individual fornecidos pela empresa. Nessa ótica, a fábrica poderá demitir Miyamura por justa causa. Art. 158 da CLT - Cabe aos empregados: b) ao uso dos equipamentos de proteção individual fornecidos pela empresa. Art. 482 da CLT - Constituem justa causa para rescisão do contrato de trabalho pelo empregador: h) ato de indisciplina ou de insubordinação. C) Errada. Não tornou facultativa a entrega dos EPI’s. Art. 158 da CLT - Cabe aos empregados: b) ao uso dos equipamentos de proteção individual fornecidos pela empresa. D) Errada. A empresa poderá demitir Miyamura por justa causa, em razão de ato de indisciplina, conforme art. 482 da CLT. Art. 482 da CLT - Constituem justa causa para rescisão do contrato de trabalho pelo empregador: h) ato de indisciplina ou de insubordinação.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_75","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":75,"discipline":"Direito do Trabalho","topic":"Empregado Doméstico","statement":"Reki tem interesse em contratar um empregado doméstico, porém, antes de efetuar a contratação, ele deseja saber mais acerca dos direitos fundamentais trabalhistas garantidos ao trabalhador doméstico. À luz da Consolidação das Leis Trabalhistas e da Lei Complementar nº 150/2015, assinale a alternativa correta.","alternative_a":"O empregado doméstico é aquele que trabalha por mais de três dias por semana no âmbito residencial.","alternative_b":"A remuneração do período trabalhado em viagem deverá ter adicional de, no mínimo, 25% em relação à hora normal, não cabendo a conversão da remuneração em banco de horas.","alternative_c":"A LC 150/2015 estabeleceu hipótese de jornada de 12 horas de trabalho por 36 horas de descanso, havendo apenas a necessidade do acordo escrito entre as partes, além de respeitar ou indenizar os intervalos para repouso e alimentação.","alternative_d":"Reki poderá contratar um empregado doméstico a título de experiência, desde que o prazo máximo do contrato seja de 60 dias.","correct_answer":"C","explanation":"A) Errada. Alternativa em desacordo com o caput do art. 1° da LC 150/2015. Art. 1o da LC 150/2015 Ao empregado doméstico, assim considerado aquele que presta serviços de forma contínua, subordinada, onerosa e pessoal e de finalidade não lucrativa à pessoa ou à família, no âmbito residencial destas, por mais de 2 (dois) dias por semana, aplica-se o disposto nesta Lei. B) Errada. Quanto ao adicional de viagem, esse será de no mínimo 25%, cabendo a conversão da remuneração em banco de horas, consoante o art. 11, §3º do mesmo dispositivo legal. Art. 11 da LC 150/2015. Em relação ao empregado responsável por acompanhar o empregador prestando serviços em viagem, serão consideradas apenas as horas efetivamente trabalhadas no período, podendo ser compensadas as horas extraordinárias em outro dia, observado o art. 2o. § 2o A remuneração-hora do serviço em viagem será, no mínimo, 25% (vinte e cinco por cento) superior ao valor do salário-hora normal. § 3o O disposto no § 2o deste artigo poderá ser, mediante acordo, convertido em acréscimo no banco de horas, a ser utilizado a critério do empregado. C) Correta. O art. 10 da LC 150/2015 prevê a possibilidade de acordo escrito entre as partes estabelecer jornada 12x36, desde que indenizados ou observados os intervalos para repouso e alimentação. Art. 10 da LC 150/2015 É facultado às partes, mediante acordo escrito entre essas, estabelecer horário de trabalho de 12 (doze) horas seguidas por 36 (trinta e seis) horas ininterruptas de descanso, observados ou indenizados os intervalos para repouso e alimentação. D) Errada. No que tange o contrato de experiência, esse é admitido para o trabalho doméstico. Todavia, o prazo máximo do contrato será de 90 dias, de acordo com o art. 4º, I da LC 150/2015, seguindo a regra geral do art. 445 da CLT. Art. 4o da LC 150/2015 É facultada a contratação, por prazo determinado, do empregado doméstico: I - mediante contrato de experiência; Art. 445 da CLT - O contrato de trabalho por prazo determinado não poderá ser estipulado por mais de 2 (dois) anos, observada a regra do art. 451. Parágrafo único. O contrato de experiência não poderá exceder de 90 (noventa) dias. PROCESSO DO TRABALHO","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_76","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":76,"discipline":"Direito Processual do Trabalho","topic":"Prazos","statement":"A respeito dos recursos no processo do trabalho, assinale a opção correta.","alternative_a":"Nos casos de feriado local forense que prorrogue o prazo para a interposição do recurso, caberá, à parte, provar a existência do feriado.","alternative_b":"O jus postulandi das partes, previsto na CLT, alcança os recursos trabalhistas até a competência do TST, não sendo aplicável aos recursos no STF.","alternative_c":"No Tribunal Superior do Trabalho, a decisão denegatória de embargos em que há ausência de comprovação de divergência jurisprudencial deve ser combatida através de recurso extraordinário.","alternative_d":"É cabível mandado de segurança quando as partes formularem pedido de homologação de acordo judicial e o juiz não o fizer.","correct_answer":"A","explanation":"A) Correta. Alternativa está de acordo com a súmula 385, I, TST. SÚMULA N.º 385 - FERIADO LOCAL. AUSÊNCIA DE EXPEDIENTE FORENSE. PRAZO RECURSAL. PRORROGAÇÃO. COMPROVAÇÃO. NECESSIDADE. ATO ADMINISTRATIVO DO JUÍZO “A QUO” I – Incumbe à parte o ônus de provar, quando da interposição do recurso, a existência de feriado local que autorize a prorrogação do prazo recursal. B) Errada. O jus postulandi das partes, estabelecido no art. 791 da CLT, limita-se às Varas do Trabalho e aos 29 Tribunais Regionais do Trabalho, não alcançando a ação rescisória, a ação cautelar, o mandado de segurança e os recursos de competência do Tribunal Superior do Trabalho. SÚMULA Nº 425 - JUS POSTULANDI NA JUSTIÇA DO TRABALHO. ALCANCE. O jus postulandi das partes, estabelecido no art. 791 da CLT, limita-se às Varas do Trabalho e aos Tribunais Regionais do Trabalho, não alcançando a ação rescisória, a ação cautelar, o mandado de segurança e os recursos de competência do Tribunal Superior do Trabalho. C) Errada. O recurso cabível é o agravo e não o recurso extraordinário, conforme art. 894, § 4º, da CLT. Art. 894, § 4º, da CLT. Da decisão denegatória dos embargos caberá agravo, no prazo de 8 (oito) dias. D) Errada. Não é cabível MS, pois a homologação de acordo judicial constitui faculdade do juiz, inexistindo direito líquido e certo, conforme súmula 418 do TST. SÚMULA Nº 418 - MANDADO DE SEGURANÇA VISANDO À CONCESSÃO DE LIMINAR OU HOMOLOGAÇÃO DE ACORDO A concessão de liminar ou a homologação de acordo constituem faculdade do juiz, inexistindo direito líquido e certo tutelável pela via do mandado de segurança.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_77","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":77,"discipline":"Direito Processual do Trabalho","topic":"Procedimento Sumaríssimo","statement":"Sobre o procedimento sumaríssimo, assinale a alternativa correta.","alternative_a":"Os dissídios individuais submetidos ao procedimento sumaríssimo são aqueles cujo valor não exceda a trinta vezes o salário-mínimo vigente na data do ajuizamento da reclamação.","alternative_b":"As testemunhas, até o máximo de três para cada parte, comparecerão à audiência de instrução e julgamento, independentemente de intimação.","alternative_c":"Estão excluídas do procedimento sumaríssimo as demandas em que são partes: a Administração Pública direta, autárquica e fundacional.","alternative_d":"As partes serão intimadas da sentença posteriormente à audiência em que for prolatada.","correct_answer":"C","explanation":"A) Errada. A alternativa está incorreta, pois menciona que o valor não pode exceder 30 vezes o salário-mínimo, porém, conforme o art. 852-A da CLT, não pode exceder 40. Art. 852-A da CLT: Os dissídios individuais cujo valor não exceda a quarenta vezes o salário mínimo vigente na data do ajuizamento da reclamação ficam submetidos ao procedimento sumaríssimo B) Errada. O número máximo de testemunhas é de até 02, conforme art. 852-H, § 2º, da CLT. Art. 852-H, § 2º, da CLT: As testemunhas, até o máximo de duas para cada parte, comparecerão à audiência de instrução e julgamento independentemente de intimação. C) Correta. Alternativa em consonância com o art. 852-H, parágrafo único, da CLT. Art. 852-H, parágrafo único, da CLT: Estão excluídas do procedimento sumaríssimo as demandas em que é parte a Administração Pública Direta, autárquica e fundacional. D) Errada. As partes são intimadas da sentença na própria audiência e não posteriormente, conforme art. 852, I, § 3º, da CLT. Art. 852, I, § 3º, da CLT: As partes serão intimadas da sentença na própria audiência em que prolatada.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_78","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":78,"discipline":"Direito Processual do Trabalho","topic":"Execução","statement":"Sobre a execução no processo do trabalho, assinale a alternativa correta.","alternative_a":"A liquidação da sentença não abrangerá o cálculo das contribuições previdenciárias devidas em razão da condenação, uma vez que, para a apuração do crédito da Previdência Social, observam-se os critérios estabelecidos na legislação previdenciária.","alternative_b":"A exigência da garantia ou penhora para a oposição dos embargos à execução na seara trabalhista também se aplica às entidades filantrópicas e/ou àqueles que compõem ou compuseram a diretoria dessas instituições.","alternative_c":"Garantida a execução ou penhorados os bens, o executado terá 8 (oito) dias para apresentar embargos, cabendo igual prazo ao exequente para impugnação.","alternative_d":"Devendo o agravo de petição delimitar, justificadamente, a matéria e os valores objeto de discordância, não fere direito líquido e certo o prosseguimento da execução quanto aos tópicos e valores não especificados no agravo.","correct_answer":"D","explanation":"A) Errada. A liquidação da sentença abrangerá o cálculo das contribuições previdenciárias, conforme art. 879, § 1º, da CLT. Art. 879, § 1º, da CLT. A liquidação ABRANGERÁ, também, o cálculo das contribuições previdenciárias devidas. B) Errada. Não há exigência de garantia ou penhora para as entidades filantrópicas e àqueles que compõem ou compuseram a diretoria dessas instituições, conforme art. 884, § 6º, da CLT. Art. 884, § 6º, da CLT. “A exigência da garantia ou penhora não se aplica às entidades filantrópicas e/ou àqueles que compõem ou compuseram a diretoria dessas instituições. C) Errada. A alternativa está incorreta, pois o prazo para apresentação de embargos é de 05 dias, conforme art. 884 da CLT. Art. 884 da CLT. Garantida a execução ou penhorados os bens, terá o executado 5 (cinco) dias para apresentar embargos, cabendo igual prazo ao exequente para impugnação. D) Correta. Alternativa de acordo com a súmula 416 do TST. SÚMULA Nº 416 - MANDADO DE SEGURANÇA. EXECUÇÃO. LEI Nº 8.432/1992. ART. 897, § 1º, DA CLT. CABIMENTO Devendo o agravo de petição delimitar justificadamente a matéria e os valores objeto de discordância, não fere direito líquido e certo o prosseguimento da execução quanto aos tópicos e valores não especificados no agravo.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_79","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":79,"discipline":"Direito Processual do Trabalho","topic":"Depósito Recursal","statement":"Juliana ajuizou uma ação trabalhista contra uma entidade sem fins lucrativos. A demanda foi julgada totalmente procedente e a entidade sem fins lucrativos pretende recorrer da sentença que lhe foi desfavorável. Neste caso, em relação às custas e ao depósito recursal, a entidade sem fins lucrativos estará:","alternative_a":"Dispensada do depósito recursal e do pagamento de custas.","alternative_b":"Deverá preparar, adequadamente, o recurso, comprovando a realização do depósito recursal e o pagamento de custas.","alternative_c":"Dispensada do depósito recursal, devendo apenas realizar os pagamentos das custas.","alternative_d":"Deverá pagar as custas processuais e realizar o depósito recursal pela metade.","correct_answer":"D","explanation":"A) Errada. A alternativa só está incorreta, pois deveria ter mencionado que o pagamento do depósito 30 recursal é pela metade, por se tratar de uma entidade sem fins lucrativos, conforme art. 899, §9° da CLT. Art. 899, § 9o, da CLT. O valor do depósito recursal será reduzido pela metade para entidades sem fins lucrativos, empregadores domésticos, microempreendedores individuais, microempresas e empresas de pequeno porte. B) Errada. As entidades sem fins lucrativos deverão pagar as custas processuais, tendo que realizar o depósito recursal pela metade, conforme art. 899, §9° da CLT. C) Errada. As entidades sem fins lucrativos não estão dispensadas do depósito recursal. Como já vimos, o seu pagamento é pela metade. D) Correta. Alternativa em consonância com o artigo 899, § 9o, da CLT. Art. 899, § 9o, da CLT. O valor do depósito recursal será reduzido pela metade para entidades sem fins lucrativos, empregadores domésticos, microempreendedores individuais, microempresas e empresas de pequeno porte.","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null},{"id":"vde_ined3_80","origem":"Método VDE","simulado":"Simulado Inédito 3","question_number":80,"discipline":"Direito Processual do Trabalho","topic":"Inquérito Judicial para Apuração de Falta Grave","statement":"Em relação à ação de inquérito judicial para apuração de falta grave, assinale a alternativa correta.","alternative_a":"A petição inicial do inquérito judicial para apuração de falta grave poderá ser apresentada oralmente.","alternative_b":"Havendo prévio reconhecimento da estabilidade do empregado, o julgamento do inquérito pelo juízo não prejudicará a execução para pagamento dos salários devidos ao empregado, até a data da instauração do mesmo inquérito.","alternative_c":"O prazo para a instauração do inquérito judicial para apuração de falta grave contra empregado garantido com estabilidade é de 30 (trinta) dias, contado a partir do suposto ato ilícito.","alternative_d":"O número máximo de testemunhas no inquérito judicial para apuração de falta grave que tramite pelo rito ordinário é de 5 (cinco).","correct_answer":"B","explanation":"A) Errada. A ação de inquérito judicial para apuração de falta grave deverá ser apresentada dentro de 30 dias ao juízo por escrito, conforme art. 853 da CLT. Art. 853 da CLT. Para a instauração do inquérito para apuração de falta grave contra empregado garantido com estabilidade, o empregador apresentará reclamação por escrito à Junta ou Juízo de Direito, dentro de 30 (trinta) dias, contados da data da suspensão do empregado. B) Correta. Alternativa em consonância com o art. 855 da CLT. Art. 855 da CLT. Se tiver havido prévio reconhecimento da estabilidade do empregado, o julgamento do inquérito pela Junta ou Juízo não prejudicará a execução para pagamento dos salários devidos ao empregado, até a data da instauração do mesmo inquérito. C) Errada. O prazo é contado da data da suspensão do empregado, conforme art. 853 da CLT. Art. 853 da CLT. Para a instauração do inquérito para apuração de falta grave contra empregado garantido com estabilidade, o empregador apresentará reclamação por escrito à Junta ou Juízo de Direito, dentro de 30 (trinta) dias, contados da data da suspensão do empregado. D) Errada. O limite de testemunhos no inquérito judicial para apuração de falta grave é de até 06, conforme art. 821 da CLT. Art. 821 da CLT. Cada uma das partes não poderá indicar mais de 3 (três) testemunhas, salvo quando se tratar de inquérito, caso em que esse número poderá ser elevado a 6 (seis). <https://www.planalto.gov.br/ccivil_03/Constituicao/Constituicao46.htm#art18%C2%A73> <https://www.planalto.gov.br/ccivil_03/Constituicao/Constituicao46.htm#art18%C2%A73> <https://www.planalto.gov.br/ccivil_03/leis/L4320.htm> <http://www.stf.jus.br/portal/peticaoInicial/verPeticaoInicial.asp?base=ADIN&s1=5938&processo=5938> <http://www.stf.jus.br/portal/peticaoInicial/verPeticaoInicial.asp?base=ADIN&s1=5938&processo=5938> <https://portal.stf.jus.br/processos/detalhe.asp?incidente=5447065> <http://www.stf.jus.br/portal/peticaoInicial/verPeticaoInicial.asp?base=ADIN&s1=5938&processo=5938> <http://www.stf.jus.br/portal/peticaoInicial/verPeticaoInicial.asp?base=ADIN&s1=5938&processo=5938> <http://www.stf.jus.br/portal/peticaoInicial/verPeticaoInicial.asp?base=ADIN&s1=5938&processo=5938> <http://www.stf.jus.br/portal/peticaoInicial/verPeticaoInicial.asp?base=ADIN&s1=5938&processo=5938> <https://portal.stf.jus.br/processos/detalhe.asp?incidente=5447065> <http://www.stf.jus.br/portal/peticaoInicial/verPeticaoInicial.asp?base=ADIN&s1=5938&processo=5938> <http://www.stf.jus.br/portal/peticaoInicial/verPeticaoInicial.asp?base=ADIN&s1=5938&processo=5938> <http://www.stf.jus.br/portal/peticaoInicial/verPeticaoInicial.asp?base=ADIN&s1=5938&processo=5938> <https://portal.stf.jus.br/processos/detalhe.asp?incidente=5447065> <http://www.stf.jus.br/portal/peticaoInicial/verPeticaoInicial.asp?base=ADIN&s1=5938&processo=5938> <http://www.stf.jus.br/portal/peticaoInicial/verPeticaoInicial.asp?base=ADIN&s1=5938&processo=5938> <http://www.stf.jus.br/portal/peticaoInicial/verPeticaoInicial.asp?base=ADIN&s1=5938&processo=5938> <http://www.stf.jus.br/portal/peticaoInicial/verPeticaoInicial.asp?base=ADIN&s1=5938&processo=5938> <https://portal.stf.jus.br/processos/detalhe.asp?incidente=5447065> <https://www.planalto.gov.br/ccivil_03/LEIS/L8213cons.htm> <https://www.planalto.gov.br/ccivil_03/LEIS/L8213cons.htm> <https://www.planalto.gov.br/ccivil_03/decreto-lei/del5452.htm#art451>","source_file":"Prova - Simulado 08 - Inédito 3.pdf","notes":null}]};
